// Kite Callback - Exchanges request_token for access_token
app.get("/api/kite/callback", async (c) => {
  try {
    if (!KITE_API_KEY || !KITE_API_SECRET) {
      return c.redirect("/?login_error=true&error=Kite+credentials+not+configured");
    }
    const requestToken = c.req.query("request_token");
    const status = c.req.query("status");

    console.log(`[AUTH] Callback received with status=${status}`);

    if (status !== "success" || !requestToken) {
      console.warn("[AUTH] Invalid callback: missing status or token");
      return c.redirect("/?login_error=true&error=Invalid+request");
    }

    // Exchange request_token for access_token (SECURELY ON BACKEND)
    const tokenData = await exchangeRequestToken(requestToken);

    if (!tokenData) {
      console.error("[AUTH] Token exchange failed");
      return c.redirect("/?login_error=true&error=Token+exchange+failed");
    }

    console.log(`[AUTH] Token exchange successful for ${tokenData.userId}`);

    // Store session in memory/database (NEVER expose to frontend)
    const sessionId = randomBytes(32).toString("hex");
    const expiresAt = nextKiteExpiryTime();
    sessions.set(sessionId, {
      accessToken: tokenData.accessToken,
      userId: tokenData.userId,
      email: tokenData.email,
      loginTime: Date.now(),
      expiresAt,
    });

    // Store session ID in secure HTTP-only cookie
    const maxAgeSeconds = Math.max(60, Math.floor((expiresAt - Date.now()) / 1000));
    const secure = process.env.NODE_ENV === "production" ? "; Secure" : "";
    c.header(
      "Set-Cookie",
      `session_id=${sessionId}; Path=/; HttpOnly${secure}; SameSite=Lax; Max-Age=${maxAgeSeconds}`
    );

    console.log("[AUTH] Session stored, redirecting to dashboard");
    return c.redirect("/?login_success=true");
  } catch (err) {
    console.error("[AUTH] Callback error:", err instanceof Error ? err.message : err);
    return c.redirect("/?login_error=true&error=Server+error");
  }
});

app.post("/api/kite/logout", (c) => {
  const cookies = c.req.header("cookie") || "";
  const sessionId = cookies
    .split("; ")
    .find((row: string) => row.startsWith("session_id="))
    ?.substring(11);
  if (sessionId) sessions.delete(sessionId);
  c.header(
    "Set-Cookie",
    "session_id=; Path=/; HttpOnly; SameSite=Lax; Max-Age=0"
  );
  return c.json({ connected: false });
});

// Kite Status - Returns connection status and user info (NEVER exposes tokens)
app.get("/api/kite/status", (c) => {
  try {
    const session = getSession(c);

    if (!session) {
      return c.json({
        connected: false,
        user: null,
      });
    }

    // NEVER return access token to frontend
    return c.json({
      connected: true,
      user: {
        userId: session.userId,
        email: session.email,
      },
    });
  } catch (err) {
    console.error("[STATUS] Error:", err instanceof Error ? err.message : err);
    return c.json({
      connected: false,
      user: null,
    });
  }
});

// ============================================================================
// ACCOUNT DATA -- Kite positions/holdings/margins/orders (read-only)
//
// Purpose: surface the logged-in user's real portfolio. This used to live
// only in a separate Streamlit "trading-dashboard" app; per the 2026-08-16
// consolidation decision it now lives here, reusing the existing cookie-
// based Kite session (getSession) instead of a second login flow. No order
// placement/modification -- GET-only, mirrors the account-viewing scope the
// standalone dashboard had.
// ============================================================================
interface KiteAccountCacheEntry {
  data: any;
  fetchedAt: number;
}
const kiteAccountCache = new Map<string, KiteAccountCacheEntry>(); // keyed by accessToken
const KITE_ACCOUNT_CACHE_TTL_MS = 20_000;

async function fetchKiteAccountData(accessToken: string) {
  const headers = {
    "X-Kite-Version": "3",
    Authorization: `token ${KITE_API_KEY}:${accessToken}`,
  };
  const [positionsRes, holdingsRes, marginsRes, ordersRes] = await Promise.all([
    fetch(`${KITE_API_BASE}/portfolio/positions`, { headers }),
    fetch(`${KITE_API_BASE}/portfolio/holdings`, { headers }),
    fetch(`${KITE_API_BASE}/user/margins`, { headers }),
    fetch(`${KITE_API_BASE}/orders`, { headers }),
  ]);
  const [positionsJson, holdingsJson, marginsJson, ordersJson] = await Promise.all([
    positionsRes.json().catch(() => null),
    holdingsRes.json().catch(() => null),
    marginsRes.json().catch(() => null),
    ordersRes.json().catch(() => null),
  ]);
  return {
    positions: positionsRes.ok ? (positionsJson?.data?.net ?? []) : [],
    positionsError: positionsRes.ok ? null : (positionsJson?.message || `HTTP ${positionsRes.status}`),
    holdings: holdingsRes.ok ? (holdingsJson?.data ?? []) : [],
    holdingsError: holdingsRes.ok ? null : (holdingsJson?.message || `HTTP ${holdingsRes.status}`),
    margins: marginsRes.ok ? (marginsJson?.data ?? null) : null,
    marginsError: marginsRes.ok ? null : (marginsJson?.message || `HTTP ${marginsRes.status}`),
    orders: ordersRes.ok ? (ordersJson?.data ?? []) : [],
    ordersError: ordersRes.ok ? null : (ordersJson?.message || `HTTP ${ordersRes.status}`),
  };
}

app.get("/api/account/kite", async (c) => {
  const session = getSession(c);
  if (!session) {
    return c.json({ connected: false, error: "Not logged in to Kite. Visit /api/kite/login first." }, 401);
  }
  try {
    const cacheKey = session.accessToken;
    const cached = kiteAccountCache.get(cacheKey);
    if (cached && Date.now() - cached.fetchedAt < KITE_ACCOUNT_CACHE_TTL_MS) {
      return c.json({ connected: true, cached: true, ...cached.data });
    }
    const data = await fetchKiteAccountData(session.accessToken);
    kiteAccountCache.set(cacheKey, { data, fetchedAt: Date.now() });
    return c.json({ connected: true, cached: false, ...data });
  } catch (err) {
    console.error("[ACCOUNT-KITE] fetch failed:", err instanceof Error ? err.message : err);
    return c.json({ connected: true, error: err instanceof Error ? err.message : "Unknown error fetching Kite account data" }, 502);
  }
});


// ============================================================================
// DHAN TOTP-BASED AUTO ACCESS TOKEN REFRESH
//
// Purpose: eliminate the daily manual "paste DHAN_ACCESS_TOKEN into Railway"
// step. Dhan access tokens are hard-capped at 24h validity by exchange/SEBI
// rule (not a Dhan-specific limit, so this cannot be made longer-lived).
// Instead, this computes a fresh RFC 6238 TOTP code from DHAN_TOTP_SECRET
// on demand and calls Dhan's documented generateAccessToken endpoint
// (https://auth.dhan.co/app/generateAccessToken) with DHAN_CLIENT_ID +
// DHAN_PIN + totp. No API-key/secret OAuth consent flow needed for this
// (individual-trader) method.
//
// The resulting access token is encrypted at rest (AES-256-GCM, reusing the
// same encryptToken/decryptToken helpers as the Drive integration) and
// persisted to the Railway volume so it survives restarts. In-memory value
// is reused until ~5 minutes before its reported expiryTime, at which point
// it is silently refreshed before the next Dhan API call.
//
// Requires three Railway variables: DHAN_CLIENT_ID (already in use),
// DHAN_PIN (6-digit numeric), DHAN_TOTP_SECRET (base32 secret from Dhan's
// Setup TOTP screen). If any are missing, getValidDhanAccessToken() falls
// back to the legacy static DHAN_ACCESS_TOKEN env var so nothing breaks
// mid-migration.
// ============================================================================

interface DhanSessionState {
  accessTokenEncrypted: string | null;
  expiryTime: string | null; // ISO timestamp as returned by Dhan
  lastRefreshedAt: string | null;
  lastError: string | null;
}

const dhanSession: DhanSessionState = {
  accessTokenEncrypted: null,
  expiryTime: null,
  lastRefreshedAt: null,
  lastError: null,
};

loadDhanSessionFromDisk();

function dhanAuthFilePath(): string {
  return joinPath(driveAuthDataDir(), "dhan-session.json");
}

function persistDhanSession(): void {
  try {
    const dir = driveAuthDataDir();
    if (!existsSync(dir)) mkdirSync(dir, { recursive: true });
    writeFileSync(dhanAuthFilePath(), JSON.stringify(dhanSession), { mode: 0o600 });
  } catch (err) {
    console.error("[DHAN-AUTH] Failed to persist session to disk:", err instanceof Error ? err.message : err);
  }
}

function loadDhanSessionFromDisk(): void {
  try {
    const filePath = dhanAuthFilePath();
    if (!existsSync(filePath)) {
      console.log(`[DHAN-AUTH] No persisted session at ${filePath} (first boot or not yet refreshed).`);
      return;
    }
    const parsed = JSON.parse(readFileSync(filePath, "utf8"));
    if (parsed && parsed.accessTokenEncrypted) {
      dhanSession.accessTokenEncrypted = parsed.accessTokenEncrypted;
      dhanSession.expiryTime = parsed.expiryTime || null;
      dhanSession.lastRefreshedAt = parsed.lastRefreshedAt || null;
      console.log(`[DHAN-AUTH] Restored Dhan session from disk (expires ${parsed.expiryTime || "unknown"}).`);
    }
  } catch (err) {
    console.error("[DHAN-AUTH] Failed to load persisted session:", err instanceof Error ? err.message : err);
  }
}

// RFC 4648 base32 decode (no padding required) — Dhan's TOTP secret comes
// base32-encoded, same as any standard authenticator-app secret.
function base32Decode(input: string): Buffer {
  const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";
  const clean = input.toUpperCase().replace(/[^A-Z2-7]/g, "");
  let bits = "";
  for (const char of clean) {
    const val = alphabet.indexOf(char);
    if (val === -1) continue;
    bits += val.toString(2).padStart(5, "0");
  }
  const bytes: number[] = [];
  for (let i = 0; i + 8 <= bits.length; i += 8) {
    bytes.push(parseInt(bits.slice(i, i + 8), 2));
  }
  return Buffer.from(bytes);
}

// RFC 6238 TOTP — 30s step, 6 digits, HMAC-SHA1 (the universal default used
// by every authenticator app and by Dhan's own TOTP setup screen).
function generateTotp(secretBase32: string, stepSeconds = 30, digits = 6): string {
  const key = base32Decode(secretBase32);
  const counter = Math.floor(Date.now() / 1000 / stepSeconds);
  const counterBuf = Buffer.alloc(8);
  counterBuf.writeBigUInt64BE(BigInt(counter));
  const hmac = createHmac("sha1", key).update(counterBuf).digest();
  const offset = hmac[hmac.length - 1] & 0x0f;
  const binCode =
    ((hmac[offset] & 0x7f) << 24) |
    ((hmac[offset + 1] & 0xff) << 16) |
    ((hmac[offset + 2] & 0xff) << 8) |
    (hmac[offset + 3] & 0xff);
  const code = (binCode % 10 ** digits).toString().padStart(digits, "0");
  return code;
}

let dhanRefreshInFlight: Promise<string | null> | null = null;

async function refreshDhanAccessToken(): Promise<string | null> {
  // Multiple background cycles (M1 production, TradeLab multi-expiry, etc.)
  // can all discover an empty/expired session within the same tick at
  // startup. Without this lock, each would fire its own TOTP-based
  // generateAccessToken call — wasteful, and Dhan rejects rapid repeat
  // calls, so only the first caller actually refreshes; everyone else
  // awaits and reuses that same in-flight result.
  if (dhanRefreshInFlight) return dhanRefreshInFlight;
  dhanRefreshInFlight = (async () => {
    const clientId = process.env.DHAN_CLIENT_ID?.trim() || "";
  const pin = process.env.DHAN_PIN?.trim() || "";
  const totpSecret = process.env.DHAN_TOTP_SECRET?.trim() || "";
  if (!clientId || !pin || !totpSecret) {
    dhanSession.lastError = "DHAN_CLIENT_ID / DHAN_PIN / DHAN_TOTP_SECRET not fully configured for auto-refresh.";
    return null;
  }

  try {
    const totp = generateTotp(totpSecret);
    const params = new URLSearchParams({ dhanClientId: clientId, pin, totp });
    const res = await fetch(`https://auth.dhan.co/app/generateAccessToken?${params.toString()}`, {
      method: "POST",
    });
    const json: any = await res.json().catch(() => null);
    if (!res.ok || !json || !json.accessToken) {
      dhanSession.lastError = json?.errorMessage || `Dhan generateAccessToken failed (HTTP ${res.status})`;
      console.error("[DHAN-AUTH] Auto-refresh failed:", dhanSession.lastError);
      return null;
    }
    dhanSession.accessTokenEncrypted = encryptToken(json.accessToken);
    dhanSession.expiryTime = json.expiryTime || null;
    dhanSession.lastRefreshedAt = new Date().toISOString();
    dhanSession.lastError = null;
    persistDhanSession();
    console.log(`[DHAN-AUTH] Access token auto-refreshed via TOTP, expires ${dhanSession.expiryTime}.`);
    return json.accessToken;
  } catch (err) {
    dhanSession.lastError = err instanceof Error ? err.message : "Unknown Dhan auto-refresh error";
    console.error("[DHAN-AUTH] Auto-refresh error:", dhanSession.lastError);
    return null;
  }
  })().finally(() => {
    dhanRefreshInFlight = null;
  });
  return dhanRefreshInFlight;
}

// Drop-in replacement for `process.env.DHAN_ACCESS_TOKEN?.trim() || ""`.
// Returns a live, auto-refreshed token when TOTP auto-refresh is configured;
// otherwise falls back to the legacy static env var so existing setups keep
// working unchanged during migration.
async function getValidDhanAccessToken(): Promise<string | null> {
  const bufferMs = 5 * 60 * 1000; // refresh 5 minutes before reported expiry
  if (dhanSession.accessTokenEncrypted && dhanSession.expiryTime) {
    const expiresAt = new Date(dhanSession.expiryTime).getTime();
    if (!Number.isNaN(expiresAt) && Date.now() < expiresAt - bufferMs) {
      const decrypted = decryptToken(dhanSession.accessTokenEncrypted);
      if (decrypted) return decrypted;
    }
  }
  const refreshed = await refreshDhanAccessToken();
  if (refreshed) return refreshed;
  // Fallback: legacy static token (pre-automation setups, or if auto-refresh
  // is temporarily failing but a manually-pasted token is still valid).
  const legacy = process.env.DHAN_ACCESS_TOKEN?.trim() || "";
  return legacy || null;
}

// Config-presence check used by startup gates and status displays. True if
// EITHER the legacy static token is set, OR the full TOTP auto-refresh
// trio (client id + pin + totp secret) is set — so nothing that used to
// gate on "DHAN_ACCESS_TOKEN present" silently stops working after
// migrating to auto-refresh (where that legacy var is no longer set).
function isDhanConfigured(): boolean {
  const hasLegacyToken = Boolean(process.env.DHAN_ACCESS_TOKEN?.trim());
  const hasClientId = Boolean(process.env.DHAN_CLIENT_ID?.trim());
  const hasAutoRefresh = Boolean(
    process.env.DHAN_CLIENT_ID?.trim() && process.env.DHAN_PIN?.trim() && process.env.DHAN_TOTP_SECRET?.trim()
  );
  return hasClientId && (hasLegacyToken || hasAutoRefresh);
}

app.get("/api/audit/dhan-auto-refresh-status", (c) => {
  const auditKey = process.env.DHAN_AUDIT_KEY?.trim() || "";
  const providedKey = c.req.query("key")?.trim() || "";
  if (!auditKey || providedKey !== auditKey) {
    return c.json({ status: "ERROR", error: "Missing or invalid audit key." }, 403);
  }
  return c.json({
    architectureRole: "DHAN_TOTP_AUTO_REFRESH",
    configured: Boolean(
      process.env.DHAN_CLIENT_ID?.trim() && process.env.DHAN_PIN?.trim() && process.env.DHAN_TOTP_SECRET?.trim()
    ),
    hasStoredToken: Boolean(dhanSession.accessTokenEncrypted),
    expiryTime: dhanSession.expiryTime,
    lastRefreshedAt: dhanSession.lastRefreshedAt,
    lastError: dhanSession.lastError,
    legacyStaticTokenPresent: Boolean(process.env.DHAN_ACCESS_TOKEN?.trim()),
    tokenExposed: false,
  }, 200);
});

// ============================================================================
// DHAN MIGRATION — D1 AUTHENTICATION HEALTH (READ-ONLY)
// Purpose: verify Railway-held Dhan credentials and Data API entitlement
// without exposing secrets or enabling any trading/order action.
// Official test endpoint: GET https://api.dhan.co/v2/profile
// ============================================================================

type DhanAuthHealthStatus = "PASS" | "FAIL" | "NOT_CONFIGURED";

app.get("/api/dhan/health", async (c) => {
  const accessToken = (await getValidDhanAccessToken()) || "";
  const configuredClientId = process.env.DHAN_CLIENT_ID?.trim() || "";

  if (!accessToken || !configuredClientId) {
    return c.json({
      architectureRole: "D1_DHAN_AUTHENTICATION_HEALTH",
      generatedAt: new Date().toISOString(),
      status: "NOT_CONFIGURED" as DhanAuthHealthStatus,
      configured: {
        clientId: !!configuredClientId,
        accessToken: !!accessToken,
      },
      readOnlyMode: true,
      orderAccessUsed: false,
      tokenExposed: false,
      error: "DHAN_CLIENT_ID and/or DHAN_ACCESS_TOKEN is not configured in Railway Variables.",
    }, 503);
  }

  try {
    const response = await fetch("https://api.dhan.co/v2/profile", {
      method: "GET",
      headers: {
        Accept: "application/json",
        "access-token": accessToken,
      },
    });

    const raw = await response.text();
    let payload: any = null;
    try {
      payload = raw ? JSON.parse(raw) : null;
    } catch {
      payload = null;
    }

    if (!response.ok || !payload || typeof payload !== "object") {
      return c.json({
        architectureRole: "D1_DHAN_AUTHENTICATION_HEALTH",
        generatedAt: new Date().toISOString(),
        status: "FAIL" as DhanAuthHealthStatus,
        httpStatus: response.status,
        authValid: false,
        clientIdMatch: null,
        dataPlanActive: false,
        derivativesActive: false,
        readOnlyMode: true,
        orderAccessUsed: false,
        tokenExposed: false,
        providerError: payload && typeof payload === "object" ? {
          errorType: payload.errorType ?? null,
          errorCode: payload.errorCode ?? null,
          errorMessage: payload.errorMessage ?? null,
        } : {
          errorType: "NON_JSON_RESPONSE",
          errorCode: null,
          errorMessage: `Dhan profile returned HTTP ${response.status}`,
        },
      }, response.status >= 400 && response.status < 600 ? response.status as any : 502);
    }

    const returnedClientId = String(payload.dhanClientId ?? "").trim();
    const clientIdMatch = returnedClientId.length > 0 && returnedClientId === configuredClientId;
    const activeSegment = String(payload.activeSegment ?? "");
    const dataPlan = String(payload.dataPlan ?? "");
    // Dhan's /v2/profile returns activeSegment as a comma-separated list of
    // single-letter codes (e.g. "E, D, C, M, ") — NOT the full word
    // "derivative". Match "D" as a standalone comma/space-delimited token so
    // this doesn't false-negative on accounts that genuinely have F&O active.
    const derivativesActive = activeSegment
      .split(",")
      .map((s) => s.trim().toUpperCase())
      .includes("D");
    const dataPlanActive = /^active$/i.test(dataPlan.trim());
    const authValid = returnedClientId.length > 0;

    const status: DhanAuthHealthStatus = authValid && clientIdMatch ? "PASS" : "FAIL";

    return c.json({
      architectureRole: "D1_DHAN_AUTHENTICATION_HEALTH",
      generatedAt: new Date().toISOString(),
      status,
      authValid,
      clientIdMatch,
      dhanClientIdMasked: returnedClientId
        ? `${returnedClientId.slice(0, 3)}***${returnedClientId.slice(-2)}`
        : null,
      tokenValidity: payload.tokenValidity ?? null,
      activeSegment: payload.activeSegment ?? null,
      derivativesActive,
      dataPlan: payload.dataPlan ?? null,
      dataPlanActive,
      dataValidity: payload.dataValidity ?? null,
      ddpi: payload.ddpi ?? null,
      mtf: payload.mtf ?? null,
      migrationReadiness: authValid && clientIdMatch && dataPlanActive && derivativesActive
        ? "READY_FOR_D2_SECURITY_ID_MAPPING"
        : "HOLD_AND_FIX_D1_REQUIREMENTS",
      readOnlyMode: true,
      orderAccessUsed: false,
      tokenExposed: false,
      boundaries: {
        marketDataMigrationOnly: true,
        orderPlacement: false,
        orderModification: false,
        orderCancellation: false,
      },
    }, status === "PASS" ? 200 : 409);
  } catch (err) {
    console.error("[DHAN D1] profile health check failed:", err instanceof Error ? err.message : err);
    return c.json({
      architectureRole: "D1_DHAN_AUTHENTICATION_HEALTH",
      generatedAt: new Date().toISOString(),
      status: "FAIL" as DhanAuthHealthStatus,
      authValid: false,
      clientIdMatch: null,
      dataPlanActive: false,
      derivativesActive: false,
      readOnlyMode: true,
      orderAccessUsed: false,
      tokenExposed: false,
      error: err instanceof Error ? err.message : "Unknown Dhan profile request failure",
    }, 502);
  }
});

// ============================================================================
// ACCOUNT DATA -- Dhan positions/holdings/fund-limit/orders (read-only)
// Same consolidation rationale as the Kite account endpoint above. Uses the
// existing TOTP auto-refreshed token (getValidDhanAccessToken) -- no new
// auth flow needed.
// ============================================================================
interface DhanAccountCacheEntry {
  data: any;
  fetchedAt: number;
}
let dhanAccountCache: DhanAccountCacheEntry | null = null;
const DHAN_ACCOUNT_CACHE_TTL_MS = 20_000;

async function fetchDhanAccountData(accessToken: string) {
  const headers = { Accept: "application/json", "access-token": accessToken };
  const parseJson = async (res: Response) => {
    const raw = await res.text();
    try {
      return raw ? JSON.parse(raw) : null;
    } catch {
      return null;
    }
  };
  const [positionsRes, holdingsRes, fundsRes, ordersRes] = await Promise.all([
    dhanRateLimitedFetch("https://api.dhan.co/v2/positions", { headers }),
    dhanRateLimitedFetch("https://api.dhan.co/v2/holdings", { headers }),
    dhanRateLimitedFetch("https://api.dhan.co/v2/fundlimit", { headers }),
    dhanRateLimitedFetch("https://api.dhan.co/v2/orders", { headers }),
  ]);
  const [positionsJson, holdingsJson, fundsJson, ordersJson] = await Promise.all([
    parseJson(positionsRes),
    parseJson(holdingsRes),
    parseJson(fundsRes),
    parseJson(ordersRes),
  ]);
  return {
    positions: positionsRes.ok && Array.isArray(positionsJson) ? positionsJson : [],
    positionsError: positionsRes.ok ? null : (positionsJson?.errorMessage || `HTTP ${positionsRes.status}`),
    holdings: holdingsRes.ok && Array.isArray(holdingsJson) ? holdingsJson : [],
    holdingsError: holdingsRes.ok ? null : (holdingsJson?.errorMessage || `HTTP ${holdingsRes.status}`),
    funds: fundsRes.ok ? fundsJson : null,
    fundsError: fundsRes.ok ? null : (fundsJson?.errorMessage || `HTTP ${fundsRes.status}`),
    orders: ordersRes.ok && Array.isArray(ordersJson) ? ordersJson : [],
    ordersError: ordersRes.ok ? null : (ordersJson?.errorMessage || `HTTP ${ordersRes.status}`),
  };
}

app.get("/api/account/dhan", async (c) => {
  const clientId = process.env.DHAN_CLIENT_ID?.trim() || "";
  if (!clientId) {
    return c.json({ connected: false, error: "DHAN_CLIENT_ID not configured in Railway Variables." }, 503);
  }
  try {
    if (dhanAccountCache && Date.now() - dhanAccountCache.fetchedAt < DHAN_ACCOUNT_CACHE_TTL_MS) {
      return c.json({ connected: true, cached: true, ...dhanAccountCache.data });
    }
    const accessToken = (await getValidDhanAccessToken()) || "";
    if (!accessToken) {
      return c.json({ connected: false, error: "No valid Dhan access token available (auto-refresh and legacy token both unavailable)." }, 401);
    }
    const data = await fetchDhanAccountData(accessToken);
    dhanAccountCache = { data, fetchedAt: Date.now() };
    return c.json({ connected: true, cached: false, ...data });
  } catch (err) {
    console.error("[ACCOUNT-DHAN] fetch failed:", err instanceof Error ? err.message : err);
    return c.json({ connected: true, error: err instanceof Error ? err.message : "Unknown error fetching Dhan account data" }, 502);
  }
});

export default app;

// ============================================================================
// DHAN MIGRATION — D2 SECURITY-ID / CONTRACT IDENTITY MAPPER (READ-ONLY)
// Purpose: verify official Dhan Option Chain APIs (expirylist + optionchain)
// resolve to a real, identifiable NIFTY/BANKNIFTY contract set — spot price,
// nearest expiry, ATM strike, CE/PE presence — before any live adapter (D3)
// is built. Does NOT touch Zerodha, scoring, or the Rule Engine.
//
// NOTE ON SENSEX: no officially-confirmed Dhan UnderlyingScrip ID was found
// during this build. Per the strict "never fabricate identity fields" rule,
// SENSEX is intentionally left NOT_YET_MAPPED here rather than guessed.
//
// Official endpoints (Dhan v2 docs):
//   POST https://api.dhan.co/v2/optionchain/expirylist
//   POST https://api.dhan.co/v2/optionchain
// Rate limit: 1 request per 3 seconds (enforced below with a fixed delay).
// ============================================================================

const DHAN_UNDERLYING_MAP: Record<string, { underlyingScrip: number; underlyingSeg: string }> = {
  NIFTY: { underlyingScrip: 13, underlyingSeg: "IDX_I" },
  BANKNIFTY: { underlyingScrip: 25, underlyingSeg: "IDX_I" },
  // SENSEX — added 2026-08-11 via V3-D Step 1 raw-data-availability audit.
  // securityId=51 originally started as an UNOFFICIAL candidate (a
  // third-party community SDK README, NOT Dhan's official docs) and was
  // first live-verified by /api/audit/dhan-raw-check: Dhan's returned close
  // (78542.44 on 2026-08-10) matched independent sources (Trading
  // Economics, Yahoo Finance) to the exact rupee/paisa.
  // UPGRADED 2026-08-13: now additionally confirmed directly from Dhan's
  // own scrip-master CSV via /api/audit/dhan-instrument-master?symbol=SENSEX
  // — INDEX row SEM_SMST_SECURITY_ID=51, SEM_TRADING_SYMBOL=SENSEX,
  // SEM_EXM_EXCH_ID=BSE (not guessed), same evidence standard as the
  // FINNIFTY/MIDCPNIFTY/INDIA VIX confirmations. Matching BSXFUT/BSXOPT
  // futures+options contracts also present in the same scan.
  // Does NOT affect the M1 production cutover or Recorder cutover — both
  // remain hardcoded to "NIFTY" | "BANKNIFTY" only (see
  // dhanM1BuildProductionSnapshot, dhanRecorderSourceMetrics) and are
  // independent of this map, so SENSEX production scoring stays on Kite,
  // unchanged, per the D6.1.2 fail-closed design. This map entry is used by
  // the read-only D3/D4 diagnostic adapters and the additive TradeLab
  // Dhan-only M2/M3/M8/M9 modules only.
  SENSEX: { underlyingScrip: 51, underlyingSeg: "IDX_I" },
  // FINNIFTY — confirmed 2026-08-12. securityId=27 live-verified via
  // /v2/charts/intraday (IDX_I/INDEX): 374 minute candles, close=26432.4
  // on 2026-08-11, matching FINNIFTY's real independently-sourced range
  // (~26,532 on 2026-08-10). Futures contract IDs (58070/48702) were
  // separately cross-validated against two independent scrip-master scans.
  FINNIFTY: { underlyingScrip: 27, underlyingSeg: "IDX_I" },
  // MIDCPNIFTY — confirmed 2026-08-12. securityId=442 came directly from
  // Dhan's own scrip-master CSV INDEX row (SEM_TRADING_SYMBOL=MIDCPNIFTY,
  // SEM_CUSTOM_SYMBOL="Nifty Midcap Select" -- not guessed) and was
  // live-verified via /v2/charts/intraday: 374 minute candles,
  // close=14990.55 on 2026-08-11, matching MIDCPNIFTY's real range
  // (~14,780-14,955 in early August 2026).
  MIDCPNIFTY: { underlyingScrip: 442, underlyingSeg: "IDX_I" },
};

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

app.get("/api/dhan/contracts", async (c) => {
  const symbolParam = (c.req.query("symbol") || "").trim().toUpperCase();
  const accessToken = (await getValidDhanAccessToken()) || "";
  const clientId = process.env.DHAN_CLIENT_ID?.trim() || "";

  if (!accessToken || !clientId) {
    return c.json(
      {
        architectureRole: "D2_SECURITY_ID_MAPPER",
        generatedAt: new Date().toISOString(),
        status: "NOT_CONFIGURED",
        error: "DHAN_ACCESS_TOKEN or DHAN_CLIENT_ID missing in Railway variables",
      },
      503
    );
  }

  if (!symbolParam) {
    return c.json(
      {
        architectureRole: "D2_SECURITY_ID_MAPPER",
        generatedAt: new Date().toISOString(),
        status: "BAD_REQUEST",
        error: "Missing ?symbol= query param",
        supportedSymbols: Object.keys(DHAN_UNDERLYING_MAP),
      },
      400
    );
  }

  const mapping = DHAN_UNDERLYING_MAP[symbolParam];
  if (!mapping) {
    return c.json(
      {
        architectureRole: "D2_SECURITY_ID_MAPPER",
        generatedAt: new Date().toISOString(),
        status: "NOT_YET_MAPPED",
        symbol: symbolParam,
        reason:
          symbolParam === "SENSEX"
            ? "No officially-confirmed Dhan UnderlyingScrip ID was found for SENSEX during this build. Left unmapped rather than guessed, per the never-fabricate-identity rule."
            : "Symbol not in DHAN_UNDERLYING_MAP.",
        supportedSymbols: Object.keys(DHAN_UNDERLYING_MAP),
      },
      501
    );
  }

  const headers = {
    "Content-Type": "application/json",
    "access-token": accessToken,
    "client-id": clientId,
  };

  try {
    // Step 1: expiry list (identity check H1 — does this underlying resolve
    // to a real, currently-active contract series at all?)
    const expiryRes = await fetch("https://api.dhan.co/v2/optionchain/expirylist", {
      method: "POST",
      headers,
      body: JSON.stringify({
        UnderlyingScrip: mapping.underlyingScrip,
        UnderlyingSeg: mapping.underlyingSeg,
      }),
    });
    const expiryRaw = await expiryRes.text();
    let expiryPayload: any = null;
    try {
      expiryPayload = expiryRaw ? JSON.parse(expiryRaw) : null;
    } catch {
      expiryPayload = null;
    }

    if (!expiryRes.ok || !expiryPayload || !Array.isArray(expiryPayload.data) || expiryPayload.data.length === 0) {
      return c.json(
        {
          architectureRole: "D2_SECURITY_ID_MAPPER",
          generatedAt: new Date().toISOString(),
          status: "FAIL",
          symbol: symbolParam,
          step: "expirylist",
          httpStatus: expiryRes.status,
          identityCheckH1_expiryListResolved: false,
          providerResponse: expiryPayload,
        },
        502
      );
    }

    const expiries: string[] = expiryPayload.data;
    const nearestExpiry = expiries[0];

    // Respect Dhan's documented Option Chain rate limit (1 req / 3s) before
    // making the second call.
    await sleep(3100);

    // Step 2: option chain for nearest expiry (identity check H2 — does the
    // resolved contract series actually contain a priced ATM CE+PE pair?)
    const chainRes = await fetch("https://api.dhan.co/v2/optionchain", {
      method: "POST",
      headers,
      body: JSON.stringify({
        UnderlyingScrip: mapping.underlyingScrip,
        UnderlyingSeg: mapping.underlyingSeg,
        Expiry: nearestExpiry,
      }),
    });
    const chainRaw = await chainRes.text();
    let chainPayload: any = null;
    try {
      chainPayload = chainRaw ? JSON.parse(chainRaw) : null;
    } catch {
      chainPayload = null;
    }

    if (!chainRes.ok || !chainPayload || !chainPayload.data || typeof chainPayload.data.oc !== "object") {
      return c.json(
        {
          architectureRole: "D2_SECURITY_ID_MAPPER",
          generatedAt: new Date().toISOString(),
          status: "FAIL",
          symbol: symbolParam,
          step: "optionchain",
          httpStatus: chainRes.status,
          identityCheckH1_expiryListResolved: true,
          identityCheckH2_chainResolved: false,
          nearestExpiry,
          providerResponse: chainPayload,
        },
        502
      );
    }

    const spot: number | null =
      typeof chainPayload.data.last_price === "number" ? chainPayload.data.last_price : null;
    const oc: Record<string, { ce?: any; pe?: any }> = chainPayload.data.oc;
    const strikes = Object.keys(oc)
      .map((s) => parseFloat(s))
      .filter((n) => !Number.isNaN(n))
      .sort((a, b) => a - b);

    let atmStrike: number | null = null;
    if (spot !== null && strikes.length > 0) {
      atmStrike = strikes.reduce((closest, s) =>
        Math.abs(s - spot) < Math.abs(closest - spot) ? s : closest
      , strikes[0]);
    }

    const atmKey = atmStrike !== null
      ? Object.keys(oc).find((k) => parseFloat(k) === atmStrike)
      : undefined;
    const atmEntry = atmKey ? oc[atmKey] : null;
    const atmCePresent = !!(atmEntry && atmEntry.ce);
    const atmPePresent = !!(atmEntry && atmEntry.pe);

    const identityCheckH1 = true; // expiry list resolved (already validated above)
    const identityCheckH2 = strikes.length > 0 && spot !== null && atmCePresent && atmPePresent;

    return c.json({
      architectureRole: "D2_SECURITY_ID_MAPPER",
      generatedAt: new Date().toISOString(),
      status: identityCheckH1 && identityCheckH2 ? "PASS" : "PARTIAL",
      symbol: symbolParam,
      underlyingScrip: mapping.underlyingScrip,
      underlyingSeg: mapping.underlyingSeg,
      identityCheckH1_expiryListResolved: identityCheckH1,
      identityCheckH2_atmContractPairFound: identityCheckH2,
      expiryCount: expiries.length,
      nearestExpiry,
      allExpiries: expiries,
      spot,
      atmStrike,
      atmCePresent,
      atmPePresent,
      strikeCount: strikes.length,
      strikeRange: strikes.length > 0 ? { min: strikes[0], max: strikes[strikes.length - 1] } : null,
      sampleAtmCe: atmCePresent ? atmEntry.ce : null,
      sampleAtmPe: atmPePresent ? atmEntry.pe : null,
      note: "This confirms contract IDENTITY (spot/expiry/strike/CE-PE presence) via the official Option Chain API. CORRECTION (verified live 2026-08-11): unlike earlier assumed, the Option Chain API DOES return a per-strike security_id (see sampleAtmCe/sampleAtmPe above) — no separate /v2/instrument/{exchangeSegment} call is required for D3 WebSocket subscriptions.",
      readOnlyMode: true,
      orderAccessUsed: false,
      tokenExposed: false,
    });
  } catch (err) {
    return c.json(
      {
        architectureRole: "D2_SECURITY_ID_MAPPER",
        generatedAt: new Date().toISOString(),
        status: "FAIL",
        symbol: symbolParam,
        step: "network-error",
        error: err instanceof Error ? err.message : String(err),
      },
      500
    );
  }
});


// ============================================================================
// DHAN MIGRATION — D3 LIVE ADAPTER (READ-ONLY)
// Purpose: fetch live NIFTY/BANKNIFTY spot, nearest expiry, and ATM±N strike
// option data (LTP, bid, ask, volume, OI, IV, native Greeks, security_id)
// via the official Dhan Option Chain API — with rate-limit protection and
// response caching so multiple modules can reuse one Dhan call instead of
// each firing its own. Does NOT touch Zerodha, scoring, or the Rule Engine.
//
// Rate limit: Dhan allows 1 unique Option Chain request per 3 seconds.
// "Unique" = same UnderlyingScrip+UnderlyingSeg+Expiry. This cache keys on
// exactly that, so repeat calls within CACHE_TTL_MS are served from memory
// and never re-hit Dhan, and calls for a NEW key are still spaced to respect
// the rate limit rather than fired concurrently.
//
// SENSEX securityId=51 IS in DHAN_UNDERLYING_MAP above (confirmed directly
// from Dhan's own scrip-master CSV as of 2026-08-13 — see the map comment).
// This adapter therefore also serves SENSEX diagnostic requests through the
// same code path below; nothing here special-cases it out.
// ============================================================================

interface DhanLiveCacheEntry {
  fetchedAt: number;
  payload: any;
}

const DHAN_LIVE_CACHE = new Map<string, DhanLiveCacheEntry>();
const DHAN_LIVE_CACHE_TTL_MS = 30 * 1000; // matches the platform's live-refresh cadence elsewhere
let dhanLastRequestAt = 0;
const DHAN_MIN_REQUEST_GAP_MS = 3100; // Dhan's documented 1-req/3s limit, +100ms margin

// PHASE 0 FIX (2026-08-14): dhanRateLimitedFetch previously used a naive
// "check dhanLastRequestAt, await sleep, then set dhanLastRequestAt"
// pattern. If two callers invoked it concurrently (e.g. the background
// tradeLabDhanMultiExpiryRefreshCycle() and an on-demand dashboard/
// diagnostic request landing at nearly the same instant), BOTH could read
// the same stale dhanLastRequestAt before either updated it, both compute
// the same "wait", both sleep the same duration, then both fetch() at
// once — breaking Dhan's 1-req/3s limit. This is the confirmed root cause
// of the "805 Too many requests" 429 failures seen twice in Railway
// deploy logs on 2026-08-14 (BANKNIFTY optionchain). Same class of bug as
// the earlier DHAN TOTP auto-refresh race, fixed the same way: chain every
// call through a single queue so the wait-then-timestamp step can never be
// entered by two callers at once. The actual network fetch() still runs
// outside the chain, so slow responses don't block subsequent requests
// beyond the mandatory spacing.
let dhanFetchQueueTail: Promise<void> = Promise.resolve();

async function dhanRateLimitedFetch(url: string, init: RequestInit): Promise<Response> {
  const reserveSlot = async () => {
    const now = Date.now();
    const wait = dhanLastRequestAt + DHAN_MIN_REQUEST_GAP_MS - now;
    if (wait > 0) await sleep(wait);
    dhanLastRequestAt = Date.now();
  };
  // Reassigning dhanFetchQueueTail happens synchronously (no await before
  // it), so two concurrent calls can never both chain onto the same prior
  // tail — this is what makes the reservation atomic.
  const myTurn = dhanFetchQueueTail.then(reserveSlot, reserveSlot);
  dhanFetchQueueTail = myTurn;
  await myTurn;
  return fetch(url, init);
}

app.get("/api/dhan/live", async (c) => {
  const symbolParam = (c.req.query("symbol") || "").trim().toUpperCase();
  const rangeParam = parseInt(c.req.query("range") || "3", 10);
  const range = Number.isFinite(rangeParam) && rangeParam > 0 && rangeParam <= 10 ? rangeParam : 3;
  const accessToken = (await getValidDhanAccessToken()) || "";
  const clientId = process.env.DHAN_CLIENT_ID?.trim() || "";

  if (!accessToken || !clientId) {
    return c.json(
      {
        architectureRole: "D3_LIVE_ADAPTER",
        generatedAt: new Date().toISOString(),
        status: "NOT_CONFIGURED",
        error: "DHAN_ACCESS_TOKEN or DHAN_CLIENT_ID missing in Railway variables",
      },
      503
    );
  }

  const mapping = DHAN_UNDERLYING_MAP[symbolParam];
  if (!mapping) {
    return c.json(
      {
        architectureRole: "D3_LIVE_ADAPTER",
        generatedAt: new Date().toISOString(),
        status: "NOT_YET_MAPPED",
        symbol: symbolParam,
        reason:
          symbolParam === "SENSEX"
            ? "No officially-confirmed Dhan UnderlyingScrip ID found for SENSEX. Left unmapped rather than guessed."
            : "Symbol not in DHAN_UNDERLYING_MAP.",
        supportedSymbols: Object.keys(DHAN_UNDERLYING_MAP),
      },
      501
    );
  }

  const headers = {
    "Content-Type": "application/json",
    "access-token": accessToken,
    "client-id": clientId,
  };

  try {
    // --- Expiry resolution (cached separately, longer TTL — expiry lists
    // change at most once a week, never intraday) ---
    const expiryCacheKey = `expirylist_${symbolParam}`;
    let expiries: string[];
    const cachedExpiry = DHAN_LIVE_CACHE.get(expiryCacheKey);
    if (cachedExpiry && Date.now() - cachedExpiry.fetchedAt < 5 * 60 * 1000) {
      expiries = cachedExpiry.payload;
    } else {
      const expiryRes = await dhanRateLimitedFetch("https://api.dhan.co/v2/optionchain/expirylist", {
        method: "POST",
        headers,
        body: JSON.stringify({
          UnderlyingScrip: mapping.underlyingScrip,
          UnderlyingSeg: mapping.underlyingSeg,
        }),
      });
      const raw = await expiryRes.text();
      let parsed: any = null;
      try {
        parsed = raw ? JSON.parse(raw) : null;
      } catch {
        parsed = null;
      }
      if (!expiryRes.ok || !parsed || !Array.isArray(parsed.data) || parsed.data.length === 0) {
        return c.json(
          {
            architectureRole: "D3_LIVE_ADAPTER",
            generatedAt: new Date().toISOString(),
            status: "FAIL",
            symbol: symbolParam,
            step: "expirylist",
            httpStatus: expiryRes.status,
            providerResponse: parsed,
          },
          502
        );
      }
      expiries = parsed.data;
      DHAN_LIVE_CACHE.set(expiryCacheKey, { fetchedAt: Date.now(), payload: expiries });
    }

    const expiryQuery = c.req.query("expiry");
    const targetExpiry = expiryQuery && expiries.includes(expiryQuery) ? expiryQuery : expiries[0];

    // --- Option chain (cached per underlying+expiry, short TTL — this is
    // the "live" data multiple modules can reuse instead of each calling
    // Dhan separately) ---
    const chainCacheKey = `optionchain_${symbolParam}_${targetExpiry}`;
    let chainPayload: any;
    let servedFromCache = false;
    const cachedChain = DHAN_LIVE_CACHE.get(chainCacheKey);
    if (cachedChain && Date.now() - cachedChain.fetchedAt < DHAN_LIVE_CACHE_TTL_MS) {
      chainPayload = cachedChain.payload;
      servedFromCache = true;
    } else {
      const chainRes = await dhanRateLimitedFetch("https://api.dhan.co/v2/optionchain", {
        method: "POST",
        headers,
        body: JSON.stringify({
          UnderlyingScrip: mapping.underlyingScrip,
          UnderlyingSeg: mapping.underlyingSeg,
          Expiry: targetExpiry,
        }),
      });
      const raw = await chainRes.text();
      let parsed: any = null;
      try {
        parsed = raw ? JSON.parse(raw) : null;
      } catch {
        parsed = null;
      }
      if (!chainRes.ok || !parsed || !parsed.data || typeof parsed.data.oc !== "object") {
        return c.json(
          {
            architectureRole: "D3_LIVE_ADAPTER",
            generatedAt: new Date().toISOString(),
            status: "FAIL",
            symbol: symbolParam,
            step: "optionchain",
            httpStatus: chainRes.status,
            targetExpiry,
            providerResponse: parsed,
          },
          502
        );
      }
      chainPayload = parsed;
      DHAN_LIVE_CACHE.set(chainCacheKey, { fetchedAt: Date.now(), payload: chainPayload });
    }

    const spot: number | null =
      typeof chainPayload.data.last_price === "number" ? chainPayload.data.last_price : null;
    const oc: Record<string, { ce?: any; pe?: any }> = chainPayload.data.oc;
    const allStrikes = Object.keys(oc)
      .map((s) => ({ raw: s, val: parseFloat(s) }))
      .filter((x) => !Number.isNaN(x.val))
      .sort((a, b) => a.val - b.val);

    if (spot === null || allStrikes.length === 0) {
      return c.json(
        {
          architectureRole: "D3_LIVE_ADAPTER",
          generatedAt: new Date().toISOString(),
          status: "FAIL",
          symbol: symbolParam,
          step: "identity",
          error: "spot or strikes UNAVAILABLE from provider — fail-closed, not treating as zero",
        },
        502
      );
    }

    let atmIndex = 0;
    let atmDiff = Math.abs(allStrikes[0].val - spot);
    for (let i = 1; i < allStrikes.length; i++) {
      const diff = Math.abs(allStrikes[i].val - spot);
      if (diff < atmDiff) {
        atmDiff = diff;
        atmIndex = i;
      }
    }

    const lo = Math.max(0, atmIndex - range);
    const hi = Math.min(allStrikes.length - 1, atmIndex + range);
    const selected = allStrikes.slice(lo, hi + 1);

    // Helper: pull a leg's fields WITHOUT ever substituting a fabricated
    // zero for a missing value — null/UNAVAILABLE instead, per strict rule.
    function extractLeg(leg: any | undefined) {
      if (!leg) return null;
      return {
        securityId: typeof leg.security_id === "number" ? leg.security_id : null,
        lastPrice: typeof leg.last_price === "number" ? leg.last_price : null,
        bid: typeof leg.top_bid_price === "number" ? leg.top_bid_price : null,
        bidQty: typeof leg.top_bid_quantity === "number" ? leg.top_bid_quantity : null,
        ask: typeof leg.top_ask_price === "number" ? leg.top_ask_price : null,
        askQty: typeof leg.top_ask_quantity === "number" ? leg.top_ask_quantity : null,
        volume: typeof leg.volume === "number" ? leg.volume : null,
        oi: typeof leg.oi === "number" ? leg.oi : null,
        previousOi: typeof leg.previous_oi === "number" ? leg.previous_oi : null,
        previousVolume: typeof leg.previous_volume === "number" ? leg.previous_volume : null,
        previousClose: typeof leg.previous_close_price === "number" ? leg.previous_close_price : null,
        iv: typeof leg.implied_volatility === "number" ? leg.implied_volatility : null,
        delta: leg.greeks && typeof leg.greeks.delta === "number" ? leg.greeks.delta : null,
        gamma: leg.greeks && typeof leg.greeks.gamma === "number" ? leg.greeks.gamma : null,
        theta: leg.greeks && typeof leg.greeks.theta === "number" ? leg.greeks.theta : null,
        vega: leg.greeks && typeof leg.greeks.vega === "number" ? leg.greeks.vega : null,
        greeksSource: "DHAN_NATIVE", // per spec: use Dhan native Greeks, not Black-Scholes fallback
      };
    }

    const atmStrikeValue = allStrikes[atmIndex].val;
    const strikesOut = selected.map((s) => {
      const entry = oc[s.raw];
      const isAtm = s.val === atmStrikeValue;
      return {
        strike: s.val,
        ceMoneyness: isAtm ? "ATM" : s.val < spot ? "ITM" : "OTM",
        peMoneyness: isAtm ? "ATM" : s.val > spot ? "ITM" : "OTM",
        ce: extractLeg(entry?.ce),
        pe: extractLeg(entry?.pe),
      };
    });

    return c.json({
      architectureRole: "D3_LIVE_ADAPTER",
      generatedAt: new Date().toISOString(),
      status: "PASS",
      symbol: symbolParam,
      underlyingScrip: mapping.underlyingScrip,
      underlyingSeg: mapping.underlyingSeg,
      expiry: targetExpiry,
      availableExpiries: expiries,
      spot,
      atmStrike: allStrikes[atmIndex].val,
      strikeRangeRequested: range,
      strikeCountReturned: strikesOut.length,
      strikes: strikesOut,
      providerTimestamp: "UNAVAILABLE_FROM_PROVIDER", // Dhan's Option Chain response does not include a per-quote exchange timestamp field — never fabricated
      serverFetchTime: new Date(
        servedFromCache ? DHAN_LIVE_CACHE.get(chainCacheKey)!.fetchedAt : Date.now()
      ).toISOString(),
      servedFromCache,
      cacheTtlMs: DHAN_LIVE_CACHE_TTL_MS,
      greeksSource: "DHAN_NATIVE",
      readOnlyMode: true,
      orderAccessUsed: false,
      tokenExposed: false,
    });
  } catch (err) {
    return c.json(
      {
        architectureRole: "D3_LIVE_ADAPTER",
        generatedAt: new Date().toISOString(),
        status: "FAIL",
        symbol: symbolParam,
        step: "network-error",
        error: err instanceof Error ? err.message : String(err),
      },
      500
    );
  }
});

// ============================================================================
// DHAN MIGRATION — D4 NORMALIZED ADAPTER (READ-ONLY, DIAGNOSTIC ONLY)
// Purpose: convert raw Dhan Option Chain payload into a provider-neutral
// normalized shape, PARALLEL to (not replacing) the existing PremiumData /
// IndexMetrics interfaces used by M1-M12B. This is intentionally a NEW,
// separate type + route — it does not modify PremiumData/IndexMetrics, does
// not touch refreshMarketSnapshot(), Kite, or any M1-M12B module wiring
// (that integration is explicitly D6 scope, not this pass).
//
// Fields Dhan's Option Chain API cannot supply (tradingSymbol, lotSize,
// tickSize — these require the separate instrument-master endpoint, not yet
// fetched per D2's scope decision) are left null with an explicit reason,
// never fabricated. Intrinsic/extrinsic and moneyness are computed here
// from spot+strike, mirroring the existing platform convention.
// ============================================================================

interface DhanNormalizedLeg {
  provider: "DHAN";
  underlying: string;
  exchangeSegment: string; // the underlying's segment (IDX_I) — the LEG's own
                            // trading segment (e.g. NSE_FNO) is not confirmed
                            // by the Option Chain API response and is left null
  legExchangeSegment: null; // UNAVAILABLE_FROM_OPTIONCHAIN_API — requires instrument master
  securityId: number | null;
  tradingSymbol: null; // UNAVAILABLE_FROM_OPTIONCHAIN_API — requires instrument master
  expiryDate: string;
  strike: number;
  optionType: "CE" | "PE";
  moneyness: "ITM" | "ATM" | "OTM";
  lotSize: null; // UNAVAILABLE_FROM_OPTIONCHAIN_API — requires instrument master
  tickSize: null; // UNAVAILABLE_FROM_OPTIONCHAIN_API — requires instrument master
  lastPrice: number | null;
  bid: number | null;
  ask: number | null;
  volume: number | null;
  oi: number | null;
  previousOi: number | null;
  previousClose: number | null;
  change: number | null; // lastPrice - previousClose, null if either input missing
  intrinsic: number | null;
  extrinsic: number | null;
  intrinsicPct: number | null;
  extrinsicPct: number | null;
  iv: number | null;
  ivSuspect: boolean; // true when iv===0 AND lastPrice>0 — a known Dhan zero-DTE/deep-ITM quirk observed live 2026-08-11, not a genuine reading
  delta: number | null;
  gamma: number | null;
  theta: number | null;
  vega: number | null;
  greeksSource: "DHAN_NATIVE";
  greeksSuspect: boolean; // true when all of delta/gamma/theta/vega are exactly 0 while lastPrice>0
  averagePrice: number | null;
  averagePriceSource: "UNVERIFIED AVERAGE PRICE — NOT VWAP"; // Dhan's average_price meaning has not been verified against a true session VWAP, same caution as the existing Kite-side convention
  dayHigh: null; // UNAVAILABLE — requires separate OHLC/historical call, out of scope this pass
  dayLow: null; // UNAVAILABLE — requires separate OHLC/historical call, out of scope this pass
  pdh: null; // UNAVAILABLE — same reason
  pdl: null; // UNAVAILABLE — same reason
  quoteTimestamp: "UNAVAILABLE_FROM_PROVIDER";
  contractRegime: "DHAN_OPTIONCHAIN_DERIVED"; // distinct from the Kite-side "LIVE_CONTRACT_MASTER" — this leg has NOT been cross-checked against Dhan's instrument master, only against the live Option Chain snapshot
}

function normalizeDhanLeg(params: {
  underlying: string;
  underlyingSeg: string;
  expiry: string;
  strike: number;
  optionType: "CE" | "PE";
  spot: number;
  leg: any | undefined;
}): DhanNormalizedLeg | null {
  const { underlying, underlyingSeg, expiry, strike, optionType, spot, leg } = params;
  if (!leg) return null;

  const lastPrice = typeof leg.last_price === "number" ? leg.last_price : null;
  const previousClose = typeof leg.previous_close_price === "number" ? leg.previous_close_price : null;
  const change = lastPrice !== null && previousClose !== null ? lastPrice - previousClose : null;

  let moneyness: "ITM" | "ATM" | "OTM";
  if (strike === spot) moneyness = "ATM";
  else if (optionType === "CE") moneyness = strike < spot ? "ITM" : "OTM";
  else moneyness = strike > spot ? "ITM" : "OTM";

  let intrinsic: number | null = null;
  let extrinsic: number | null = null;
  let intrinsicPct: number | null = null;
  let extrinsicPct: number | null = null;
  if (lastPrice !== null) {
    intrinsic = optionType === "CE" ? Math.max(0, spot - strike) : Math.max(0, strike - spot);
    extrinsic = Math.max(0, lastPrice - intrinsic);
    if (lastPrice > 0) {
      intrinsicPct = (intrinsic / lastPrice) * 100;
      extrinsicPct = (extrinsic / lastPrice) * 100;
    }
  }

  const iv = typeof leg.implied_volatility === "number" ? leg.implied_volatility : null;
  const delta = leg.greeks && typeof leg.greeks.delta === "number" ? leg.greeks.delta : null;
  const gamma = leg.greeks && typeof leg.greeks.gamma === "number" ? leg.greeks.gamma : null;
  const theta = leg.greeks && typeof leg.greeks.theta === "number" ? leg.greeks.theta : null;
  const vega = leg.greeks && typeof leg.greeks.vega === "number" ? leg.greeks.vega : null;

  // Flag the exact quirk observed live 2026-08-11: deep-ITM/zero-DTE legs
  // where Dhan returns iv=0 and all Greeks=0 despite a real nonzero
  // lastPrice. This is NOT treated as a genuine zero — downstream must
  // treat ivSuspect/greeksSuspect === true as UNAVAILABLE, not as data.
  const ivSuspect = iv === 0 && lastPrice !== null && lastPrice > 0;
  const greeksSuspect =
    delta === 0 && gamma === 0 && theta === 0 && vega === 0 && lastPrice !== null && lastPrice > 0;

  return {
    provider: "DHAN",
    underlying,
    exchangeSegment: underlyingSeg,
    legExchangeSegment: null,
    securityId: typeof leg.security_id === "number" ? leg.security_id : null,
    tradingSymbol: null,
    expiryDate: expiry,
    strike,
    optionType,
    moneyness,
    lotSize: null,
    tickSize: null,
    lastPrice,
    bid: typeof leg.top_bid_price === "number" ? leg.top_bid_price : null,
    ask: typeof leg.top_ask_price === "number" ? leg.top_ask_price : null,
    volume: typeof leg.volume === "number" ? leg.volume : null,
    oi: typeof leg.oi === "number" ? leg.oi : null,
    previousOi: typeof leg.previous_oi === "number" ? leg.previous_oi : null,
    previousClose,
    change,
    intrinsic,
    extrinsic,
    intrinsicPct,
    extrinsicPct,
    iv,
    ivSuspect,
    delta,
    gamma,
    theta,
    vega,
    greeksSource: "DHAN_NATIVE",
    greeksSuspect,
    averagePrice: typeof leg.average_price === "number" ? leg.average_price : null,
    averagePriceSource: "UNVERIFIED AVERAGE PRICE — NOT VWAP",
    dayHigh: null,
    dayLow: null,
    pdh: null,
    pdl: null,
    quoteTimestamp: "UNAVAILABLE_FROM_PROVIDER",
    contractRegime: "DHAN_OPTIONCHAIN_DERIVED",
  };
}

app.get("/api/dhan/normalized", async (c) => {
  const symbolParam = (c.req.query("symbol") || "").trim().toUpperCase();
  const rangeParam = parseInt(c.req.query("range") || "3", 10);
  const range = Number.isFinite(rangeParam) && rangeParam > 0 && rangeParam <= 10 ? rangeParam : 3;
  const accessToken = (await getValidDhanAccessToken()) || "";
  const clientId = process.env.DHAN_CLIENT_ID?.trim() || "";

  if (!accessToken || !clientId) {
    return c.json(
      {
        architectureRole: "D4_NORMALIZED_ADAPTER",
        generatedAt: new Date().toISOString(),
        status: "NOT_CONFIGURED",
        error: "DHAN_ACCESS_TOKEN or DHAN_CLIENT_ID missing in Railway variables",
      },
      503
    );
  }

  const mapping = DHAN_UNDERLYING_MAP[symbolParam];
  if (!mapping) {
    return c.json(
      {
        architectureRole: "D4_NORMALIZED_ADAPTER",
        generatedAt: new Date().toISOString(),
        status: "NOT_YET_MAPPED",
        symbol: symbolParam,
        supportedSymbols: Object.keys(DHAN_UNDERLYING_MAP),
      },
      501
    );
  }

  const headers = {
    "Content-Type": "application/json",
    "access-token": accessToken,
    "client-id": clientId,
  };

  try {
    const expiryCacheKey = `expirylist_${symbolParam}`;
    let expiries: string[];
    const cachedExpiry = DHAN_LIVE_CACHE.get(expiryCacheKey);
    if (cachedExpiry && Date.now() - cachedExpiry.fetchedAt < 5 * 60 * 1000) {
      expiries = cachedExpiry.payload;
    } else {
      const expiryRes = await dhanRateLimitedFetch("https://api.dhan.co/v2/optionchain/expirylist", {
        method: "POST",
        headers,
        body: JSON.stringify({
          UnderlyingScrip: mapping.underlyingScrip,
          UnderlyingSeg: mapping.underlyingSeg,
        }),
      });
      const raw = await expiryRes.text();
      let parsed: any = null;
      try {
        parsed = raw ? JSON.parse(raw) : null;
      } catch {
        parsed = null;
      }
      if (!expiryRes.ok || !parsed || !Array.isArray(parsed.data) || parsed.data.length === 0) {
        console.error(
          `[DHAN D4 FAIL] step=expirylist symbol=${symbolParam} httpStatus=${expiryRes.status} bodySnippet=${raw.slice(0, 300)}`
        );
        return c.json(
          {
            architectureRole: "D4_NORMALIZED_ADAPTER",
            generatedAt: new Date().toISOString(),
            status: "FAIL",
            symbol: symbolParam,
            step: "expirylist",
            httpStatus: expiryRes.status,
          },
          502
        );
      }
      expiries = parsed.data;
      DHAN_LIVE_CACHE.set(expiryCacheKey, { fetchedAt: Date.now(), payload: expiries });
    }

    const expiryQuery = c.req.query("expiry");
    const targetExpiry = expiryQuery && expiries.includes(expiryQuery) ? expiryQuery : expiries[0];

    const chainCacheKey = `optionchain_${symbolParam}_${targetExpiry}`;
    let chainPayload: any;
    const cachedChain = DHAN_LIVE_CACHE.get(chainCacheKey);
    if (cachedChain && Date.now() - cachedChain.fetchedAt < DHAN_LIVE_CACHE_TTL_MS) {
      chainPayload = cachedChain.payload;
    } else {
      const chainRes = await dhanRateLimitedFetch("https://api.dhan.co/v2/optionchain", {
        method: "POST",
        headers,
        body: JSON.stringify({
          UnderlyingScrip: mapping.underlyingScrip,
          UnderlyingSeg: mapping.underlyingSeg,
          Expiry: targetExpiry,
        }),
      });
      const raw = await chainRes.text();
      let parsed: any = null;
      try {
        parsed = raw ? JSON.parse(raw) : null;
      } catch {
        parsed = null;
      }
      if (!chainRes.ok || !parsed || !parsed.data || typeof parsed.data.oc !== "object") {
        console.error(
          `[DHAN D4 FAIL] step=optionchain symbol=${symbolParam} httpStatus=${chainRes.status} bodySnippet=${raw.slice(0, 300)}`
        );
        return c.json(
          {
            architectureRole: "D4_NORMALIZED_ADAPTER",
            generatedAt: new Date().toISOString(),
            status: "FAIL",
            symbol: symbolParam,
            step: "optionchain",
            httpStatus: chainRes.status,
          },
          502
        );
      }
      chainPayload = parsed;
      DHAN_LIVE_CACHE.set(chainCacheKey, { fetchedAt: Date.now(), payload: chainPayload });
    }

    const spot: number | null =
      typeof chainPayload.data.last_price === "number" ? chainPayload.data.last_price : null;
    const oc: Record<string, { ce?: any; pe?: any }> = chainPayload.data.oc;
    const allStrikes = Object.keys(oc)
      .map((s) => ({ raw: s, val: parseFloat(s) }))
      .filter((x) => !Number.isNaN(x.val))
      .sort((a, b) => a.val - b.val);

    if (spot === null || allStrikes.length === 0) {
      return c.json(
        {
          architectureRole: "D4_NORMALIZED_ADAPTER",
          generatedAt: new Date().toISOString(),
          status: "FAIL",
          symbol: symbolParam,
          error: "spot or strikes UNAVAILABLE from provider — fail-closed",
        },
        502
      );
    }

    let atmIndex = 0;
    let atmDiff = Math.abs(allStrikes[0].val - spot);
    for (let i = 1; i < allStrikes.length; i++) {
      const diff = Math.abs(allStrikes[i].val - spot);
      if (diff < atmDiff) {
        atmDiff = diff;
        atmIndex = i;
      }
    }
    const lo = Math.max(0, atmIndex - range);
    const hi = Math.min(allStrikes.length - 1, atmIndex + range);
    const selected = allStrikes.slice(lo, hi + 1);

    const normalized: { strike: number; ce: DhanNormalizedLeg | null; pe: DhanNormalizedLeg | null }[] = [];
    let suspectCount = 0;
    for (const s of selected) {
      const entry = oc[s.raw];
      const ceNorm = normalizeDhanLeg({
        underlying: symbolParam,
        underlyingSeg: mapping.underlyingSeg,
        expiry: targetExpiry,
        strike: s.val,
        optionType: "CE",
        spot,
        leg: entry?.ce,
      });
      const peNorm = normalizeDhanLeg({
        underlying: symbolParam,
        underlyingSeg: mapping.underlyingSeg,
        expiry: targetExpiry,
        strike: s.val,
        optionType: "PE",
        spot,
        leg: entry?.pe,
      });
      if (ceNorm?.ivSuspect || ceNorm?.greeksSuspect) suspectCount++;
      if (peNorm?.ivSuspect || peNorm?.greeksSuspect) suspectCount++;
      normalized.push({ strike: s.val, ce: ceNorm, pe: peNorm });
    }

    return c.json({
      architectureRole: "D4_NORMALIZED_ADAPTER",
      generatedAt: new Date().toISOString(),
      status: "PASS",
      symbol: symbolParam,
      expiry: targetExpiry,
      spot,
      atmStrike: allStrikes[atmIndex].val,
      strikeCount: normalized.length,
      suspectLegCount: suspectCount,
      dataQualityNote:
        suspectCount > 0
          ? `${suspectCount} leg(s) have ivSuspect or greeksSuspect === true — Dhan returned literal 0 for IV/Greeks despite a real nonzero premium (known zero-DTE/deep-ITM quirk observed live 2026-08-11). Downstream consumers MUST treat these as UNAVAILABLE, not as genuine zero readings.`
          : "No suspect legs detected in this snapshot.",
      normalized,
      schemaNote:
        "This is a NEW, parallel type (DhanNormalizedLeg) — it does NOT modify or replace the existing PremiumData/IndexMetrics interfaces used by M1-M12B. Wiring normalized Dhan data into those modules is explicit D6 scope, not this pass. tradingSymbol/lotSize/tickSize are null — UNAVAILABLE_FROM_OPTIONCHAIN_API, require the separate instrument-master endpoint (not fetched in D1-D4).",
      readOnlyMode: true,
      orderAccessUsed: false,
      tokenExposed: false,
    });
  } catch (err) {
    return c.json(
      {
        architectureRole: "D4_NORMALIZED_ADAPTER",
        generatedAt: new Date().toISOString(),
        status: "FAIL",
        symbol: symbolParam,
        step: "network-error",
        error: err instanceof Error ? err.message : String(err),
      },
      500
    );
  }
});

// ============================================================================
// DHAN MIGRATION — D5 CROSS-VALIDATION (READ-ONLY, DIAGNOSTIC ONLY)
// Purpose: compare the LIVE Dhan feed (via the same fetch path as D3/D4)
// against the CURRENTLY CACHED Zerodha/Kite snapshot for the same browser
// session, on spot, ATM strike premium, and OI — before any decision is
// made about removing Zerodha (that is explicitly D8, gated on D1-D7 PASS).
//
// This does NOT force a fresh Kite refresh and does NOT touch scoring,
// the Rule Engine, or refreshMarketSnapshot(). It reads whatever Kite
// snapshot is already cached on the requester's existing session cookie
// (the same one the dashboard itself uses) and compares it, as-is, against
// a fresh Dhan pull. If no Kite session/snapshot is available, this fails
// closed with INSUFFICIENT_COMPARISON_DATA rather than fabricating a
// comparison.
//
// Divergence thresholds below are PROVISIONAL (no historical evidence yet
// to calibrate them) and only used to LABEL the comparison for a human to
// read — they do not gate or feed any other module.
// ============================================================================

const DHAN_D5_MINOR_DIVERGENCE_PCT = 0.15; // provisional
const DHAN_D5_MAJOR_DIVERGENCE_PCT = 0.5; // provisional

function pctDiff(a: number, b: number): number | null {
  if (a === 0 && b === 0) return 0;
  const base = Math.abs(a) > Math.abs(b) ? Math.abs(a) : Math.abs(b);
  if (base === 0) return null;
  return (Math.abs(a - b) / base) * 100;
}

app.get("/api/dhan/cross-validate", async (c) => {
  const symbolParam = (c.req.query("symbol") || "").trim().toUpperCase();
  const accessToken = (await getValidDhanAccessToken()) || "";
  const clientId = process.env.DHAN_CLIENT_ID?.trim() || "";

  if (!accessToken || !clientId) {
    return c.json(
      {
        architectureRole: "D5_CROSS_VALIDATION",
        generatedAt: new Date().toISOString(),
        status: "NOT_CONFIGURED",
        error: "DHAN_ACCESS_TOKEN or DHAN_CLIENT_ID missing in Railway variables",
      },
      503
    );
  }

  const mapping = DHAN_UNDERLYING_MAP[symbolParam];
  if (!mapping) {
    return c.json(
      {
        architectureRole: "D5_CROSS_VALIDATION",
        generatedAt: new Date().toISOString(),
        status: "NOT_YET_MAPPED",
        symbol: symbolParam,
        supportedSymbols: Object.keys(DHAN_UNDERLYING_MAP),
      },
      501
    );
  }

  // --- Zerodha/Kite side: read the EXISTING cached snapshot on this
  // browser's session cookie. Never force a fresh Kite call from here. ---
  const session = getSession(c);
  const kiteSnapshot: IndexMetrics | undefined = session?.marketSnapshot?.[symbolParam];

  if (!session || !kiteSnapshot) {
    return c.json({
      architectureRole: "D5_CROSS_VALIDATION",
      generatedAt: new Date().toISOString(),
      status: "INSUFFICIENT_COMPARISON_DATA",
      symbol: symbolParam,
      reason: !session
        ? "No active Kite session cookie on this request. Open this URL in the SAME browser tab/session where the OptionPilot dashboard is logged into Kite, then retry."
        : "Kite session found but has no cached market snapshot yet for this symbol — open the dashboard tab for this symbol first so it refreshes, then retry.",
      readOnlyMode: true,
    }, 200);
  }

  const kiteSnapshotAgeMs = session.snapshotTime ? Date.now() - session.snapshotTime : null;

  // NOTE: kiteSnapshot.expiries[].expiry holds a DISPLAY LABEL ("Current
  // Expiry", "Next Expiry", ...), NOT a date string — the platform's own
  // convention (see e.g. line ~260, ~1852 elsewhere in this file). The real
  // date lives in .expiryDate (a Date object). Sort/compare on that instead.
  const kiteExpiriesSorted = (kiteSnapshot.expiries || [])
    .filter((e) => e && e.expiryDate instanceof Date)
    .slice()
    .sort((a, b) => a.expiryDate.getTime() - b.expiryDate.getTime());
  const kiteNearestExpiry = kiteExpiriesSorted[0];
  const kiteNearestExpiryDateStr = kiteNearestExpiry
    ? kiteNearestExpiry.expiryDate.toISOString().slice(0, 10)
    : null;

  if (!kiteNearestExpiry || !kiteNearestExpiryDateStr) {
    return c.json({
      architectureRole: "D5_CROSS_VALIDATION",
      generatedAt: new Date().toISOString(),
      status: "INSUFFICIENT_COMPARISON_DATA",
      symbol: symbolParam,
      reason: "Kite snapshot has no usable expiryDate for this symbol.",
      readOnlyMode: true,
    }, 200);
  }

  const headers = {
    "Content-Type": "application/json",
    "access-token": accessToken,
    "client-id": clientId,
  };

  try {
    // --- Dhan side: same fetch path as D3/D4, using the cache so this
    // doesn't burn an extra rate-limited call if D3/D4 was just hit. ---
    const expiryCacheKey = `expirylist_${symbolParam}`;
    let dhanExpiries: string[];
    const cachedExpiry = DHAN_LIVE_CACHE.get(expiryCacheKey);
    if (cachedExpiry && Date.now() - cachedExpiry.fetchedAt < 5 * 60 * 1000) {
      dhanExpiries = cachedExpiry.payload;
    } else {
      const expiryRes = await dhanRateLimitedFetch("https://api.dhan.co/v2/optionchain/expirylist", {
        method: "POST",
        headers,
        body: JSON.stringify({ UnderlyingScrip: mapping.underlyingScrip, UnderlyingSeg: mapping.underlyingSeg }),
      });
      const raw = await expiryRes.text();
      let parsed: any = null;
      try { parsed = raw ? JSON.parse(raw) : null; } catch { parsed = null; }
      if (!expiryRes.ok || !parsed || !Array.isArray(parsed.data) || parsed.data.length === 0) {
        return c.json({
          architectureRole: "D5_CROSS_VALIDATION",
          generatedAt: new Date().toISOString(),
          status: "FAIL",
          symbol: symbolParam,
          step: "dhan-expirylist",
          httpStatus: expiryRes.status,
        }, 502);
      }
      dhanExpiries = parsed.data;
      DHAN_LIVE_CACHE.set(expiryCacheKey, { fetchedAt: Date.now(), payload: dhanExpiries });
    }

    const dhanNearestExpiry = dhanExpiries[0];
    const expiryMatch = dhanNearestExpiry === kiteNearestExpiryDateStr;

    if (!expiryMatch) {
      return c.json({
        architectureRole: "D5_CROSS_VALIDATION",
        generatedAt: new Date().toISOString(),
        status: "CONTRACT_MAPPING_MISMATCH",
        symbol: symbolParam,
        kiteNearestExpiry: kiteNearestExpiryDateStr,
        dhanNearestExpiry,
        note: "Zerodha and Dhan disagree on which expiry is nearest for this symbol right now. Not comparing further until this is understood — could be a genuine listing difference or a stale side.",
        kiteSnapshotAgeMs,
        readOnlyMode: true,
      }, 200);
    }

    const chainCacheKey = `optionchain_${symbolParam}_${dhanNearestExpiry}`;
    let chainPayload: any;
    const cachedChain = DHAN_LIVE_CACHE.get(chainCacheKey);
    if (cachedChain && Date.now() - cachedChain.fetchedAt < DHAN_LIVE_CACHE_TTL_MS) {
      chainPayload = cachedChain.payload;
    } else {
      const chainRes = await dhanRateLimitedFetch("https://api.dhan.co/v2/optionchain", {
        method: "POST",
        headers,
        body: JSON.stringify({ UnderlyingScrip: mapping.underlyingScrip, UnderlyingSeg: mapping.underlyingSeg, Expiry: dhanNearestExpiry }),
      });
      const raw = await chainRes.text();
      let parsed: any = null;
      try { parsed = raw ? JSON.parse(raw) : null; } catch { parsed = null; }
      if (!chainRes.ok || !parsed || !parsed.data || typeof parsed.data.oc !== "object") {
        return c.json({
          architectureRole: "D5_CROSS_VALIDATION",
          generatedAt: new Date().toISOString(),
          status: "FAIL",
          symbol: symbolParam,
          step: "dhan-optionchain",
          httpStatus: chainRes.status,
        }, 502);
      }
      chainPayload = parsed;
      DHAN_LIVE_CACHE.set(chainCacheKey, { fetchedAt: Date.now(), payload: chainPayload });
    }

    const dhanSpot: number | null = typeof chainPayload.data.last_price === "number" ? chainPayload.data.last_price : null;
    const kiteSpot: number | null = typeof kiteSnapshot.spot === "number" ? kiteSnapshot.spot : null;

    if (dhanSpot === null || kiteSpot === null) {
      return c.json({
        architectureRole: "D5_CROSS_VALIDATION",
        generatedAt: new Date().toISOString(),
        status: "INSUFFICIENT_COMPARISON_DATA",
        symbol: symbolParam,
        reason: "spot UNAVAILABLE from one or both providers",
        kiteSpot, dhanSpot,
      }, 200);
    }

    const spotDivergencePct = pctDiff(kiteSpot, dhanSpot);
    const spotDivergenceAbs = Math.abs(kiteSpot - dhanSpot);

    // --- ATM strike comparison: find Kite's ATM CE/PE for this expiry and
    // the matching strike on the Dhan side. ---
    const kiteAtmStrike = kiteSnapshot.atmStrike;
    const kiteCe = kiteNearestExpiry.ceStrikes?.find((p) => p.strike === kiteAtmStrike);
    const kitePe = kiteNearestExpiry.peStrikes?.find((p) => p.strike === kiteAtmStrike);

    const dhanOc: Record<string, { ce?: any; pe?: any }> = chainPayload.data.oc;
    const dhanAtmKey = Object.keys(dhanOc).find((k) => parseFloat(k) === kiteAtmStrike);
    const dhanCe = dhanAtmKey ? dhanOc[dhanAtmKey]?.ce : undefined;
    const dhanPe = dhanAtmKey ? dhanOc[dhanAtmKey]?.pe : undefined;

    const legComparisons: any[] = [];
    for (const [label, kiteLeg, dhanLeg] of [
      ["CE", kiteCe, dhanCe],
      ["PE", kitePe, dhanPe],
    ] as const) {
      if (!kiteLeg || !dhanLeg) {
        legComparisons.push({
          leg: label,
          status: "INSUFFICIENT_COMPARISON_DATA",
          kiteAvailable: !!kiteLeg,
          dhanAvailable: !!dhanLeg,
        });
        continue;
      }
      const kiteLtp = typeof kiteLeg.lastPrice === "number" ? kiteLeg.lastPrice : null;
      const dhanLtp = typeof dhanLeg.last_price === "number" ? dhanLeg.last_price : null;
      const kiteOi = typeof kiteLeg.oi === "number" ? kiteLeg.oi : null;
      const dhanOi = typeof dhanLeg.oi === "number" ? dhanLeg.oi : null;
      const ltpDivergencePct = kiteLtp !== null && dhanLtp !== null ? pctDiff(kiteLtp, dhanLtp) : null;
      const oiDivergencePct = kiteOi !== null && dhanOi !== null ? pctDiff(kiteOi, dhanOi) : null;
      legComparisons.push({
        leg: label,
        kiteLtp, dhanLtp, ltpDivergencePct,
        kiteOi, dhanOi, oiDivergencePct,
        kiteIv: typeof kiteLeg.iv === "number" ? kiteLeg.iv : null,
        dhanIv: typeof dhanLeg.implied_volatility === "number" ? dhanLeg.implied_volatility : null,
        kiteDelta: typeof kiteLeg.delta === "number" ? kiteLeg.delta : null,
        dhanDelta: dhanLeg.greeks && typeof dhanLeg.greeks.delta === "number" ? dhanLeg.greeks.delta : null,
        note: "Kite delta/IV are Black-Scholes ESTIMATES (Kite doesn't publish Greeks); Dhan delta/IV are provider-native. A divergence here does not necessarily mean either is 'wrong'.",
      });
    }

    // PHASE 0 FIX (2026-08-14): overallState previously looked ONLY at
    // spotDivergencePct and completely ignored legComparisons (the actual
    // CE/PE option-premium LTP divergence). Confirmed live on 2026-08-14:
    // BANKNIFTY spot diverged 0.05% (fine) while CE LTP diverged 2.39% and
    // PE LTP diverged 2.91% (both far past the 0.5% "major" threshold), yet
    // the endpoint still reported "SOURCE_ALIGNED" — misleading for a card
    // that exists specifically to catch option-premium mismatches. The
    // worst leg divergence must now also drive the overall status.
    const legDivergencePcts = legComparisons
      .map((l: any) => (typeof l.ltpDivergencePct === "number" ? l.ltpDivergencePct : null))
      .filter((v: number | null): v is number => v !== null);
    const worstLegDivergencePct = legDivergencePcts.length > 0 ? Math.max(...legDivergencePcts) : null;
    const worstDivergencePct = [spotDivergencePct, worstLegDivergencePct]
      .filter((v): v is number => v !== null)
      .reduce((max, v) => (v > max ? v : max), 0);

    let overallState: string;
    if (spotDivergencePct === null && worstLegDivergencePct === null) {
      overallState = "INSUFFICIENT_COMPARISON_DATA";
    } else if (worstDivergencePct >= DHAN_D5_MAJOR_DIVERGENCE_PCT) {
      overallState = "SOURCE_MAJOR_DIVERGENCE";
    } else if (worstDivergencePct >= DHAN_D5_MINOR_DIVERGENCE_PCT) {
      overallState = "SOURCE_MINOR_DIVERGENCE";
    } else {
      overallState = "SOURCE_ALIGNED";
    }

    // PHASE 0 FIX (2026-08-14): the staleness caveat previously only fired
    // past 6 minutes — far too loose for option premiums, which can move
    // several percent in under 2 minutes on BANKNIFTY (exactly what
    // happened in the 2026-08-14 sample: kiteSnapshotAgeMs=122309 i.e.
    // ~2min, alongside 2-3% leg LTP divergence). Lowered to 60s, and the
    // field now also explicitly names which side is stale so this isn't
    // read as a Dhan-side data problem when it's a Kite dashboard-refresh
    // staleness problem instead. Labeling only — per divergenceThresholds
    // note below, this does not gate any other module.
    const kiteSnapshotStale = kiteSnapshotAgeMs !== null && kiteSnapshotAgeMs > 60 * 1000;

    return c.json({
      architectureRole: "D5_CROSS_VALIDATION",
      generatedAt: new Date().toISOString(),
      status: overallState,
      symbol: symbolParam,
      expiry: dhanNearestExpiry,
      kiteSnapshotAgeMs,
      kiteSnapshotAgeCaveat: kiteSnapshotStale
        ? `Kite snapshot is ${Math.round((kiteSnapshotAgeMs as number) / 1000)}s old (Dhan side is fetched fresh on every call) — some or all of the divergence below may reflect Kite-side staleness rather than a true source disagreement. Refresh the OptionPilot dashboard tab immediately before re-running this check for a fair comparison.`
        : null,
      spot: { kite: kiteSpot, dhan: dhanSpot, divergenceAbs: spotDivergenceAbs, divergencePct: spotDivergencePct },
      atmStrike: kiteAtmStrike,
      legComparisons,
      divergenceThresholds: {
        minorPct: DHAN_D5_MINOR_DIVERGENCE_PCT,
        majorPct: DHAN_D5_MAJOR_DIVERGENCE_PCT,
        note: "PROVISIONAL — no historical evidence yet to calibrate these. For labeling only; does not gate any other module.",
      },
      readOnlyMode: true,
      orderAccessUsed: false,
      tokenExposed: false,
    });
  } catch (err) {
    return c.json({
      architectureRole: "D5_CROSS_VALIDATION",
      generatedAt: new Date().toISOString(),
      status: "FAIL",
      symbol: symbolParam,
      step: "network-error",
      error: err instanceof Error ? err.message : String(err),
    }, 500);
  }
});

