// DHAN MIGRATION — D6.1 M1 PREMIUM COMPOSITION COMPATIBILITY AUDIT
// (READ-ONLY, DIAGNOSTIC ONLY)
//
// Purpose: prove M1's CORE, UNMODIFIED math (v2ComputeIntrinsicValue,
// v2PctPart) produces correct results when fed Dhan-sourced legs, WITHOUT
// touching the live M1 pipeline (buildV2PremiumCompositionHistory), the
// Recorder, or Kite. This endpoint does NOT read recorderSession at all —
// it fetches Dhan data independently and reuses M1's real functions by
// direct reference, so a PASS here proves the math is provider-agnostic,
// not that live M1 has been switched over (it has not — that's a separate,
// later decision explicitly gated on D7).
//
// KNOWN LIMITATION (reported honestly per spec, not hidden): this endpoint
// has NO history buffer of its own for Dhan data (the Recorder's 3-minute
// snapshot history is a Kite-only structure, untouched here), so
// compositionState always reports INSUFFICIENT_HISTORY for the Dhan side.
// Building a parallel Dhan history buffer is out of scope for D6.1.
// ============================================================================

interface D6M1FieldCheck {
  field: string;
  status: "PASS" | "PARTIAL" | "IV_UNAVAILABLE" | "GREEKS_UNAVAILABLE" | "INVALID" | "UNAVAILABLE_FROM_PROVIDER";
  detail: string;
}

// ============================================================================
// DHAN MIGRATION — D6.1.1 SHADOW INFRASTRUCTURE (READ-ONLY, DIAGNOSTIC ONLY)
//
// IMPORTANT SCOPE NOTE: per explicit confirmation, this builds a SHADOW
// Dhan-backed M1 pipeline (Dhan → normalized → M1 math → shadow candidate)
// running ALONGSIDE the existing Kite-backed production dashboard — it does
// NOT replace buildV2PremiumCompositionHistory or the live Recorder path.
// productionM1Provider stays honestly reported as KITE below. Full
// production cutover to Dhan is a separate, later decision gated on D7.
// ============================================================================

// --- Instrument master: lotSize/tickSize/tradingSymbol/expirySeriesType ---
// GET /v2/instrument/{exchangeSegment} returns CSV. Columns are parsed by
// HEADER NAME (case-insensitive keyword match), never by fixed position —
// if a column can't be confidently identified, the field stays null with an
// explicit reason rather than risking a silently-misaligned value.
interface DhanInstrumentMeta {
  securityId: string;
  lotSize: number | null;
  tickSize: number | null;
  tradingSymbol: string | null;
  expirySeriesType: string | null; // e.g. WEEKLY/MONTHLY if the CSV exposes it, else null
}

let dhanInstrumentMasterCache: { fetchedAt: number; bySecurityId: Map<string, DhanInstrumentMeta> } | null = null;
const DHAN_INSTRUMENT_MASTER_TTL_MS = 24 * 60 * 60 * 1000; // instrument master doesn't change intraday

function csvParseLine(line: string): string[] {
  // Minimal CSV split (Dhan's instrument CSV fields are not quote-escaped in
  // practice for this column set); good enough for header + numeric/symbol rows.
  return line.split(",").map((s) => s.trim());
}

async function getDhanInstrumentMaster(
  accessToken: string,
  clientId: string
): Promise<{ bySecurityId: Map<string, DhanInstrumentMeta>; fromCache: boolean; error?: string }> {
  if (dhanInstrumentMasterCache && Date.now() - dhanInstrumentMasterCache.fetchedAt < DHAN_INSTRUMENT_MASTER_TTL_MS) {
    return { bySecurityId: dhanInstrumentMasterCache.bySecurityId, fromCache: true };
  }

  try {
    const res = await dhanRateLimitedFetch("https://api.dhan.co/v2/instrument/NSE_FNO", {
      method: "GET",
      headers: { Accept: "text/csv", "access-token": accessToken, "client-id": clientId },
    });
    const text = await res.text();
    if (!res.ok || !text || text.length < 20) {
      return { bySecurityId: new Map(), fromCache: false, error: `instrument master fetch failed, httpStatus=${res.status}` };
    }

    const lines = text.split(/\r?\n/).filter((l) => l.length > 0);
    if (lines.length < 2) {
      return { bySecurityId: new Map(), fromCache: false, error: "instrument master CSV had no data rows" };
    }
    const header = csvParseLine(lines[0]).map((h) => h.toUpperCase());

    const findCol = (...keywords: string[]) =>
      header.findIndex((h) => keywords.every((kw) => h.includes(kw)));

    const secIdCol = findCol("SECURITY", "ID");
    const lotCol = findCol("LOT");
    const tickCol = findCol("TICK");
    const symbolCol = findCol("TRADING", "SYMBOL");
    const seriesCol = findCol("SERIES"); // best-effort; may not exist

    const bySecurityId = new Map<string, DhanInstrumentMeta>();
    for (let i = 1; i < lines.length; i++) {
      const row = csvParseLine(lines[i]);
      const secId = secIdCol >= 0 ? row[secIdCol] : null;
      if (!secId) continue;
      bySecurityId.set(secId, {
        securityId: secId,
        lotSize: lotCol >= 0 && row[lotCol] && !Number.isNaN(Number(row[lotCol])) ? Number(row[lotCol]) : null,
        tickSize: tickCol >= 0 && row[tickCol] && !Number.isNaN(Number(row[tickCol])) ? Number(row[tickCol]) : null,
        tradingSymbol: symbolCol >= 0 ? row[symbolCol] || null : null,
        expirySeriesType: seriesCol >= 0 ? row[seriesCol] || null : null,
      });
    }

    dhanInstrumentMasterCache = { fetchedAt: Date.now(), bySecurityId };
    return { bySecurityId, fromCache: false };
  } catch (err) {
    return { bySecurityId: new Map(), fromCache: false, error: err instanceof Error ? err.message : String(err) };
  }
}

// --- Price-bound validation: LTP must not be below the no-arbitrage
// intrinsic floor beyond a small numerical tolerance. ---
const PRICE_BOUND_TOLERANCE = 0.05; // rupees; not a scoring threshold, purely a data-sanity check

function checkPriceBound(lastPrice: number, intrinsic: number): { anomaly: boolean; deficit: number } {
  const deficit = intrinsic - lastPrice;
  return { anomaly: deficit > PRICE_BOUND_TOLERANCE, deficit };
}

// --- Shadow (Dhan-backed) M1 history buffer — SEPARATE from the Kite
// Recorder. Same securityId + expiry + strike + CE/PE required to compare
// two points; never compares across a mismatch (fail-closed per spec). ---
interface DhanShadowSnapshotPoint {
  fetchedAt: number;
  securityId: number;
  expiry: string;
  strike: number;
  optionType: "CE" | "PE";
  lastPrice: number;
  intrinsic: number;
  extrinsic: number;
  iv: number | null;
  delta: number | null;
  gamma: number | null;
  theta: number | null;
  vega: number | null;
  oi: number | null;
  priceBoundAnomaly: boolean;
}

const DHAN_SHADOW_M1_HISTORY = new Map<string, DhanShadowSnapshotPoint[]>();
const DHAN_SHADOW_M1_MAX_SNAPSHOTS = 20;

function pushShadowSnapshot(key: string, point: DhanShadowSnapshotPoint) {
  const arr = DHAN_SHADOW_M1_HISTORY.get(key) || [];
  arr.push(point);
  if (arr.length > DHAN_SHADOW_M1_MAX_SNAPSHOTS) arr.shift();
  DHAN_SHADOW_M1_HISTORY.set(key, arr);
}

// ============================================================================
// DHAN MIGRATION — D6.1.2 PRODUCTION M1 CUTOVER
//
// CONFIRMED WITH USER, WITH EXPLICIT RISK ACKNOWLEDGEMENT: production M1
// (buildV2PremiumCompositionHistory, called by M1/M6/M7 and the dashboard's
// premium-composition card) now runs on DHAN-normalized data for NIFTY and
// BANKNIFTY. SENSEX has NO confirmed Dhan security ID (see D2) and stays on
// the original Kite path below — this is a deliberate fail-closed choice,
// not an oversight. The original Kite logic is preserved byte-for-byte as
// buildV2PremiumCompositionHistoryKite() for rollback.
// ============================================================================

interface DhanM1HistoryLeg {
  provider: "DHAN";
  fetchedAt: number;
  securityId: number;
  expiry: string;
  strike: number;
  optionType: "CE" | "PE";
  spot: number;
  atmStrike: number;
  lastPrice: number;
  intrinsic: number;
  extrinsic: number;
  iv: number | null;
  delta: number | null;
  gamma: number | null;
  theta: number | null;
  vega: number | null;
  oi: number | null;
  priceBoundAnomaly: boolean;
}

interface DhanM1Snapshot {
  fetchedAt: number;
  legs: DhanM1HistoryLeg[];
}

const DHAN_M1_PRODUCTION_HISTORY = new Map<"NIFTY" | "BANKNIFTY", DhanM1Snapshot[]>();
const DHAN_M1_PRODUCTION_MAX_SNAPSHOTS = 200; // matches RECORDER_MAX_SNAPSHOTS
const DHAN_M1_PRODUCTION_STRIKE_RANGE = 3; // ATM±3, matching the existing Recorder convention
const DHAN_M1_PRODUCTION_REFRESH_MS = 3 * 60 * 1000; // matches existing 3-minute Recorder cadence
const DHAN_M1_PRODUCTION_STALE_MS = 6 * 60 * 1000; // a snapshot older than 2 cycles is rejected as stale

// Builds one production snapshot for a Dhan-mapped symbol, reusing the SAME
// D3/D4 cache (DHAN_LIVE_CACHE) and rate-limited fetch — this does NOT add a
// new/duplicate Dhan Option Chain call beyond what D3/D4/D5/shadow already
// share when their TTL windows overlap.
async function dhanM1BuildProductionSnapshot(symbol: "NIFTY" | "BANKNIFTY"): Promise<DhanM1Snapshot | null> {
  const accessToken = (await getValidDhanAccessToken()) || "";
  const clientId = process.env.DHAN_CLIENT_ID?.trim() || "";
  if (!accessToken || !clientId) return null;
  const mapping = DHAN_UNDERLYING_MAP[symbol];
  if (!mapping) return null;
  const headers = { "Content-Type": "application/json", "access-token": accessToken, "client-id": clientId };

  try {
    const expiryCacheKey = `expirylist_${symbol}`;
    let expiries: string[];
    const cachedExpiry = DHAN_LIVE_CACHE.get(expiryCacheKey);
    if (cachedExpiry && Date.now() - cachedExpiry.fetchedAt < 5 * 60 * 1000) {
      expiries = cachedExpiry.payload;
    } else {
      const expiryRes = await dhanRateLimitedFetch("https://api.dhan.co/v2/optionchain/expirylist", {
        method: "POST", headers,
        body: JSON.stringify({ UnderlyingScrip: mapping.underlyingScrip, UnderlyingSeg: mapping.underlyingSeg }),
      });
      const raw = await expiryRes.text();
      let parsed: any = null;
      try { parsed = raw ? JSON.parse(raw) : null; } catch { parsed = null; }
      if (!expiryRes.ok || !parsed || !Array.isArray(parsed.data) || parsed.data.length === 0) return null;
      expiries = parsed.data;
      DHAN_LIVE_CACHE.set(expiryCacheKey, { fetchedAt: Date.now(), payload: expiries });
    }
    const targetExpiry = expiries[0];

    const chainCacheKey = `optionchain_${symbol}_${targetExpiry}`;
    let chainPayload: any;
    let chainFetchedAt: number;
    const cachedChain = DHAN_LIVE_CACHE.get(chainCacheKey);
    if (cachedChain && Date.now() - cachedChain.fetchedAt < DHAN_LIVE_CACHE_TTL_MS) {
      chainPayload = cachedChain.payload;
      chainFetchedAt = cachedChain.fetchedAt;
    } else {
      const chainRes = await dhanRateLimitedFetch("https://api.dhan.co/v2/optionchain", {
        method: "POST", headers,
        body: JSON.stringify({ UnderlyingScrip: mapping.underlyingScrip, UnderlyingSeg: mapping.underlyingSeg, Expiry: targetExpiry }),
      });
      const raw = await chainRes.text();
      let parsed: any = null;
      try { parsed = raw ? JSON.parse(raw) : null; } catch { parsed = null; }
      if (!chainRes.ok || !parsed || !parsed.data || typeof parsed.data.oc !== "object") return null;
      chainPayload = parsed;
      chainFetchedAt = Date.now();
      DHAN_LIVE_CACHE.set(chainCacheKey, { fetchedAt: chainFetchedAt, payload: chainPayload });
    }

    const spot: number | null = typeof chainPayload.data.last_price === "number" ? chainPayload.data.last_price : null;
    const oc: Record<string, { ce?: any; pe?: any }> = chainPayload.data.oc;
    const allStrikes = Object.keys(oc).map((s) => parseFloat(s)).filter((n) => !Number.isNaN(n)).sort((a, b) => a - b);
    if (spot === null || allStrikes.length === 0) return null;

    let atmStrike = allStrikes[0];
    let atmDiff = Math.abs(atmStrike - spot);
    for (const s of allStrikes) {
      const diff = Math.abs(s - spot);
      if (diff < atmDiff) { atmDiff = diff; atmStrike = s; }
    }
    const atmIndex = allStrikes.indexOf(atmStrike);
    const lo = Math.max(0, atmIndex - DHAN_M1_PRODUCTION_STRIKE_RANGE);
    const hi = Math.min(allStrikes.length - 1, atmIndex + DHAN_M1_PRODUCTION_STRIKE_RANGE);
    const selected = allStrikes.slice(lo, hi + 1);

    const legs: DhanM1HistoryLeg[] = [];
    for (const strike of selected) {
      const key = Object.keys(oc).find((k) => parseFloat(k) === strike)!;
      for (const [optionType, raw] of [["CE", oc[key]?.ce], ["PE", oc[key]?.pe]] as const) {
        if (!raw || typeof raw.security_id !== "number" || typeof raw.last_price !== "number") continue; // fail-closed: missing_required_price or identity = excluded, never fabricated
        const lastPrice = raw.last_price;
        const intrinsic = v2ComputeIntrinsicValue(optionType, spot, strike); // <-- M1's real, unmodified function
        const extrinsicRaw = Math.max(lastPrice - intrinsic, 0);
        const { anomaly: priceBoundAnomaly } = checkPriceBound(lastPrice, intrinsic);
        const ivRaw = typeof raw.implied_volatility === "number" ? raw.implied_volatility : null;
        const ivSuspect = ivRaw === 0 && lastPrice > 0;
        const delta = raw.greeks?.delta, gamma = raw.greeks?.gamma, theta = raw.greeks?.theta, vega = raw.greeks?.vega;
        const greeksAllZero = delta === 0 && gamma === 0 && theta === 0 && vega === 0;
        const greeksSuspect = greeksAllZero && lastPrice > 0;
        const greeksMissing = [delta, gamma, theta, vega].some((v) => typeof v !== "number");
        legs.push({
          provider: "DHAN", fetchedAt: chainFetchedAt, securityId: raw.security_id, expiry: targetExpiry,
          strike, optionType, spot, atmStrike, lastPrice,
          intrinsic, extrinsic: priceBoundAnomaly ? extrinsicRaw : extrinsicRaw, // extrinsic itself is still a real derived number; only intrinsicPct/extrinsicPct-as-evidence are suppressed downstream for anomalies
          iv: ivSuspect ? null : ivRaw,
          delta: greeksSuspect || greeksMissing ? null : delta,
          gamma: greeksSuspect || greeksMissing ? null : gamma,
          theta: greeksSuspect || greeksMissing ? null : theta,
          vega: greeksSuspect || greeksMissing ? null : vega,
          oi: typeof raw.oi === "number" ? raw.oi : null,
          priceBoundAnomaly,
        });
      }
    }
    if (legs.length === 0) return null;
    return { fetchedAt: chainFetchedAt, legs };
  } catch (err) {
    console.error(`[DHAN_M1] production snapshot fetch failed for ${symbol}:`, err instanceof Error ? err.message : err);
    return null;
  }
}

async function dhanM1ProductionRefreshCycle() {
  for (const symbol of ["NIFTY", "BANKNIFTY"] as const) {
    const snap = await dhanM1BuildProductionSnapshot(symbol);
    if (!snap) continue;
    const arr = DHAN_M1_PRODUCTION_HISTORY.get(symbol) || [];
    arr.push(snap);
    if (arr.length > DHAN_M1_PRODUCTION_MAX_SNAPSHOTS) arr.shift();
    DHAN_M1_PRODUCTION_HISTORY.set(symbol, arr);
  }
}

