function dhanM1LegPoint(snap: DhanM1Snapshot, symbol: "NIFTY" | "BANKNIFTY", side: "CE" | "PE", strike: number): V2PremiumLegPoint | null {
  if (Date.now() - snap.fetchedAt > DHAN_M1_PRODUCTION_STALE_MS) return null; // fail-closed: stale snapshot rejected
  const leg = snap.legs.find((l) => l.optionType === side && l.strike === strike);
  if (!leg || leg.priceBoundAnomaly) return null; // fail-closed: PRICE_BOUND_ANOMALY excluded from valid evidence
  const moneyness: "ITM" | "ATM" | "OTM" = leg.atmStrike === strike ? "ATM" : leg.intrinsic > 0 ? "ITM" : "OTM";
  return {
    timestamp: new Date(leg.fetchedAt).toISOString(),
    snapshotId: `dhan_${symbol}_${leg.fetchedAt}`,
    snapshotStatus: "OK" as RecorderSnapshot["snapshotStatus"],
    symbol, side, strike, atmStrike: leg.atmStrike, spot: leg.spot, moneyness,
    premium: leg.lastPrice, intrinsic: leg.intrinsic, extrinsic: leg.extrinsic,
    intrinsicPct: v2PctPart(leg.intrinsic, leg.lastPrice), // <-- M1's real, unmodified function
    extrinsicPct: v2PctPart(leg.extrinsic, leg.lastPrice),
    iv: leg.iv, theta: leg.theta, vega: leg.vega, delta: leg.delta, oi: leg.oi,
  };
}

function buildDhanM1CompositionHistory(symbol: "NIFTY" | "BANKNIFTY", maxSnapshots = 20) {
  const all = DHAN_M1_PRODUCTION_HISTORY.get(symbol) || [];
  const eligible = all.slice(-Math.max(2, Math.min(maxSnapshots, DHAN_M1_PRODUCTION_MAX_SNAPSHOTS)));

  if (eligible.length === 0) {
    return { symbol, provider: "DHAN" as const, generatedAt: new Date().toISOString(), snapshotCount: 0, comparisons: [], dataQuality: "INSUFFICIENT" as V2DataQuality };
  }

  const currentSnap = eligible[eligible.length - 1];
  const strikes = [...new Set(currentSnap.legs.map((l) => l.strike))];
  const targets: { side: V2PremiumSide; strike: number }[] = [];
  for (const strike of strikes) {
    if (currentSnap.legs.some((l) => l.strike === strike && l.optionType === "CE")) targets.push({ side: "CE", strike });
    if (currentSnap.legs.some((l) => l.strike === strike && l.optionType === "PE")) targets.push({ side: "PE", strike });
  }

  const comparisons: V2PremiumCompositionComparison[] = [];
  for (const target of targets) {
    const current = dhanM1LegPoint(currentSnap, symbol, target.side, target.strike);
    if (!current) continue;
    let previous: V2PremiumLegPoint | null = null;
    for (let i = eligible.length - 2; i >= 0; i--) {
      previous = dhanM1LegPoint(eligible[i], symbol, target.side, target.strike);
      if (previous) break;
    }
    comparisons.push(v2BuildComparison(current, previous)); // <-- M1's real, unmodified function
  }

  const overallQuality: V2DataQuality = comparisons.length === 0
    ? "INSUFFICIENT"
    : comparisons.every((x) => x.dataQuality === "OK") ? "OK"
    : comparisons.some((x) => x.dataQuality === "OK" || x.dataQuality === "PARTIAL") ? "PARTIAL" : "INSUFFICIENT";

  return {
    symbol,
    provider: "DHAN" as const,
    generatedAt: new Date().toISOString(),
    latestSnapshotAt: new Date(currentSnap.fetchedAt).toISOString(),
    source: "Dhan normalized 3-minute production snapshots; current expiry ATM±3 only",
    scoringImpact: "NONE",
    snapshotCount: eligible.length,
    dataQuality: overallQuality,
    comparisons,
  };
}

// Production router: NIFTY/BANKNIFTY -> Dhan, SENSEX -> Kite (rollback path,
// deliberate fail-closed choice — Dhan has no confirmed security ID for it).
// ============================================================================
// D6-A — RECORDER PROVIDER CUTOVER (NIFTY/BANKNIFTY -> DHAN)
//
// Rather than modifying the shared, already-verified Truth Engine functions
// (computeTruthReport, toTruthValidatedRecorderIndexSnapshot — these MUST
// stay byte-identical for the Kite/SENSEX path), this builds an honest
// IndexMetrics-SHAPED adapter from the already-running D6.1.2 Dhan
// production buffer and feeds it through those SAME UNMODIFIED functions.
// No new Dhan fetch — reuses DHAN_M1_PRODUCTION_HISTORY (already refreshed
// every 3 minutes independently of any request).
//
// HONEST LIMITATION: Dhan futures were never built in D1-D6 (only the
// Option Chain adapter exists). futuresContracts is therefore left EMPTY
// (not fabricated), which makes the "futures" Truth field permanently
// INVALID for Dhan-sourced entries — the existing computeTruthReport logic
// then correctly caps overallVerdict at PARTIAL (never TRUE) for
// NIFTY/BANKNIFTY under Dhan. This is a genuine, disclosed capability gap,
// not a bug. Per this spec's own fail_closed_rules ("Missing Dhan
// normalized snapshot => PARTIAL/INVALID"), PARTIAL is an anticipated,
// acceptable state — and every downstream consumer that reads
// recorderSession.snapshots only excludes STALE/INVALID, not PARTIAL, so
// this does not block M1/M2/M8/Journal/Drive from consuming the data.
//
// exchangeTimestamp is left null (Dhan's Option Chain has no genuine
// per-quote exchange timestamp — already established in D3/D4). This
// triggers the EXISTING, already-approved fallback in computeTruthReport
// (m.timestamp = honest backend receipt time) — the exact same pattern
// already used for index spot on the Kite side (see the 2026-08-07 bugfix
// comment above computeTruthReport). No new special-casing was needed.
// ============================================================================

function dhanToIndexMetricsShim(symbol: "NIFTY" | "BANKNIFTY", dhanSnap: DhanM1Snapshot): IndexMetrics {
  const atmStrike = dhanSnap.legs[0]?.atmStrike ?? 0;
  const spot = dhanSnap.legs[0]?.spot ?? 0;
  const expiry = dhanSnap.legs[0]?.expiry ?? "";
  const receiptIso = new Date(dhanSnap.fetchedAt).toISOString();

  const toPremiumData = (l: DhanM1HistoryLeg): PremiumData =>
    ({
      strike: l.strike,
      isAtm: l.strike === atmStrike,
      instrumentToken: null,
      exchangeToken: null,
      expiryDate: l.expiry,
      expiryBucket: "Current Expiry",
      optionType: l.optionType,
      lotSize: null,
      tickSize: null,
      exchange: "NSE",
      segment: "NFO-OPT",
      contractRegime: "DHAN_OPTIONCHAIN_DERIVED",
      tradingSymbol: null,
      bid: null,
      ask: null,
      lastPrice: l.priceBoundAnomaly ? 0 : l.lastPrice, // PRICE_BOUND_ANOMALY legs excluded from valid evidence, per spec
      change: null,
      iv: l.iv,
      oi: l.oi,
      volume: null,
      vwap: null,
      vwapSource: "UNAVAILABLE",
      quoteTimestamp: receiptIso, // honest backend-receipt proxy — same pattern already used for spot
      atDayHigh: false,
      atDayLow: false,
      dayHigh: null,
      dayLow: null,
      pdc: null,
      pdh: null,
      pdl: null,
      vega: l.vega,
      theta: l.theta,
      delta: l.delta,
    } as unknown as PremiumData);

  const ceStrikes = dhanSnap.legs.filter((l) => l.optionType === "CE").sort((a, b) => a.strike - b.strike).map(toPremiumData);
  const peStrikes = dhanSnap.legs.filter((l) => l.optionType === "PE").sort((a, b) => a.strike - b.strike).map(toPremiumData);

  return {
    symbol,
    current: spot,
    change: 0,
    spot,
    atmStrike,
    vwap: 0,
    pdh: 0,
    pdl: 0,
    futuresContracts: [], // HONEST: no Dhan futures adapter exists (D1-D6 built option-chain only)
    snapshotId: `dhan_${symbol}_${dhanSnap.fetchedAt}`,
    exchangeTimestamp: null, // HONEST: Dhan Option Chain has no genuine per-quote exchange timestamp
    expiries: [{ expiry: "Current Expiry", expiryDate: new Date(expiry), ceStrikes, peStrikes } as unknown as ExpiryData],
    error: undefined,
    timestamp: receiptIso,
  } as unknown as IndexMetrics;
}

function dhanRecorderSourceMetrics(symbol: "NIFTY" | "BANKNIFTY"): IndexMetrics {
  const history = DHAN_M1_PRODUCTION_HISTORY.get(symbol);
  const latest = history && history.length > 0 ? history[history.length - 1] : null;
  if (!latest) {
    // Fail-closed: no silent Kite fallback. computeTruthReport's `!m || m.error`
    // branch returns INVALID for this shape.
    return { error: "no_dhan_snapshot_available", symbol } as unknown as IndexMetrics;
  }
  return dhanToIndexMetricsShim(symbol, latest);
}

// ===== M1 (Dhan) for SENSEX — SENSEX Dhan migration sub-step 1 of 2
// (2026-08-16). SENSEX securityId=51 is already confirmed and
// TRADELAB_DHAN_MULTIEXPIRY_HISTORY already fetches SENSEX every 3
// minutes independently of any request (same cadence M2/M3/M4/M8/M9/
// M10/M5/M11/M12-Dhan already rely on for SENSEX) — so this adds ZERO
// new Dhan API calls. M6 (buildV2PremiumAttribution) and M7
// (buildV2OiPositioningEvidence) both call buildV2PremiumCompositionHistory
// internally, so fixing the router below upgrades M1/M6/M7 together.
// Does NOT touch the separate, deeper-wired Main Recorder/Truth-Engine
// SENSEX path (dhanRecorderSourceMetrics, dhanM1BuildProductionSnapshot)
// — those remain Kite-only, unchanged, pending a dedicated future step.
function tradeLabDhanM1LegPoint(
  snap: TradeLabDhanMultiExpirySnapshot,
  side: V2PremiumSide,
  strike: number
): V2PremiumLegPoint | null {
  const ed = tradeLabDhanNormalizedToExpiryData(snap.current);
  if (!ed) return null;
  const arr = side === "CE" ? ed.ceStrikes : ed.peStrikes;
  const leg = (arr || []).find((l: any) => l.strike === strike) as any;
  if (!leg || leg.lastPrice == null || leg.lastPrice <= 0) return null;
  const spot = (snap.current as any)?.spot ?? 0;
  const atmStrike = (snap.current as any)?.atmStrike ?? null;
  const intrinsic = v2ComputeIntrinsicValue(side, spot, strike);
  const extrinsic = Math.max(0, leg.lastPrice - intrinsic);
  const moneyness: "ITM" | "ATM" | "OTM" = atmStrike === strike ? "ATM" : intrinsic > 0 ? "ITM" : "OTM";
  return {
    timestamp: leg.quoteTimestamp || snap.generatedAt,
    snapshotId: `dhan_SENSEX_${snap.generatedAt}`,
    snapshotStatus: "OK" as RecorderSnapshot["snapshotStatus"],
    symbol: "SENSEX" as V2PremiumSymbol, side, strike, atmStrike, spot, moneyness,
    premium: leg.lastPrice, intrinsic, extrinsic,
    intrinsicPct: v2PctPart(intrinsic, leg.lastPrice),
    extrinsicPct: v2PctPart(extrinsic, leg.lastPrice),
    iv: leg.iv ?? null, theta: leg.theta ?? null, vega: leg.vega ?? null, delta: leg.delta ?? null, oi: leg.oi ?? null,
  };
}

function buildDhanM1CompositionHistorySensex(maxSnapshots = 20) {
  const all = TRADELAB_DHAN_MULTIEXPIRY_HISTORY.get("SENSEX") || [];
  const eligible = all.slice(-Math.max(2, Math.min(maxSnapshots, TRADELAB_DHAN_MULTIEXPIRY_MAX_SNAPSHOTS)));
  const empty = { symbol: "SENSEX" as V2PremiumSymbol, provider: "DHAN" as const, generatedAt: new Date().toISOString(), snapshotCount: 0, comparisons: [] as V2PremiumCompositionComparison[], dataQuality: "INSUFFICIENT" as V2DataQuality };
  if (eligible.length === 0) return empty;

  const currentSnap = eligible[eligible.length - 1];
  const curED = tradeLabDhanNormalizedToExpiryData(currentSnap.current);
  if (!curED) return { ...empty, snapshotCount: eligible.length };

  const targets: { side: V2PremiumSide; strike: number }[] = [
    ...curED.ceStrikes.map((l) => ({ side: "CE" as V2PremiumSide, strike: l.strike })),
    ...curED.peStrikes.map((l) => ({ side: "PE" as V2PremiumSide, strike: l.strike })),
  ];

  const comparisons: V2PremiumCompositionComparison[] = [];
  for (const target of targets) {
    const current = tradeLabDhanM1LegPoint(currentSnap, target.side, target.strike);
    if (!current) continue;
    let previous: V2PremiumLegPoint | null = null;
    for (let i = eligible.length - 2; i >= 0; i--) {
      previous = tradeLabDhanM1LegPoint(eligible[i], target.side, target.strike);
      if (previous) break;
    }
    comparisons.push(v2BuildComparison(current, previous)); // M1's real, unmodified function
  }

  const overallQuality: V2DataQuality = comparisons.length === 0
    ? "INSUFFICIENT"
    : comparisons.every((x) => x.dataQuality === "OK") ? "OK"
    : comparisons.some((x) => x.dataQuality === "OK" || x.dataQuality === "PARTIAL") ? "PARTIAL" : "INSUFFICIENT";

  return {
    symbol: "SENSEX" as V2PremiumSymbol,
    provider: "DHAN" as const,
    generatedAt: new Date().toISOString(),
    latestSnapshotAt: currentSnap.generatedAt,
    source: "Dhan normalized 3-minute TradeLab multi-expiry snapshots (current expiry) — same buffer M2/M3/M4/M8/M9/M10/M5/M11/M12-Dhan already use for SENSEX, zero new Dhan calls.",
    scoringImpact: "NONE",
    snapshotCount: eligible.length,
    dataQuality: overallQuality,
    comparisons,
  };
}

// Production router — UPDATED 2026-08-16 (SENSEX M1/M6/M7 Dhan migration,
// sub-step 1 of 2): SENSEX now also routes through Dhan here, same as
// NIFTY/BANKNIFTY. Fail-closed: if the Dhan SENSEX buffer isn't warm yet
// (snapshotCount 0, e.g. right after a fresh deploy), falls through to the
// existing Kite path rather than returning an empty result. This does NOT
// touch the separate Main Recorder/Truth-Engine SENSEX path (still Kite,
// unchanged — that is a dedicated future step, deliberately deferred).
function buildV2PremiumCompositionHistory(symbol: V2PremiumSymbol, maxSnapshots = 20) {
  if (symbol === "NIFTY" || symbol === "BANKNIFTY") {
    return buildDhanM1CompositionHistory(symbol, maxSnapshots);
  }
  if (symbol === "SENSEX" && isDhanConfigured()) {
    const dhanResult = buildDhanM1CompositionHistorySensex(maxSnapshots);
    if (dhanResult.snapshotCount > 0) return dhanResult;
  }
  return buildV2PremiumCompositionHistoryKite(symbol, maxSnapshots);
}

app.get("/api/v2/d6/m1-audit", async (c) => {
  const symbolParam = (c.req.query("symbol") || "").trim().toUpperCase();
  const accessToken = (await getValidDhanAccessToken()) || "";
  const clientId = process.env.DHAN_CLIENT_ID?.trim() || "";

  if (!accessToken || !clientId) {

    return c.json({
      status: "FAIL", phase: "D6.1", module: "M1_PREMIUM_COMPOSITION",
      generatedAt: new Date().toISOString(),
      error: "DHAN_ACCESS_TOKEN or DHAN_CLIENT_ID missing in Railway variables",
    }, 503);
  }

  const mapping = DHAN_UNDERLYING_MAP[symbolParam];
  if (!mapping) {
    return c.json({
      status: "FAIL", phase: "D6.1", module: "M1_PREMIUM_COMPOSITION",
      generatedAt: new Date().toISOString(),
      symbol: symbolParam,
      reason: "NOT_YET_MAPPED", supportedSymbols: Object.keys(DHAN_UNDERLYING_MAP),
    }, 501);
  }

  const headers = { "Content-Type": "application/json", "access-token": accessToken, "client-id": clientId };
  const invalidOrPartialReasons: string[] = [];

  try {
    // --- Reuse D3/D4's exact fetch + cache path. Zero Zerodha/Kite/Recorder
    // reference anywhere in this function — zerodhaFallbackUsed is provably
    // false by construction, not just asserted. ---
    const expiryCacheKey = `expirylist_${symbolParam}`;
    let expiries: string[];
    const cachedExpiry = DHAN_LIVE_CACHE.get(expiryCacheKey);
    if (cachedExpiry && Date.now() - cachedExpiry.fetchedAt < 5 * 60 * 1000) {
      expiries = cachedExpiry.payload;
    } else {
      const expiryRes = await dhanRateLimitedFetch("https://api.dhan.co/v2/optionchain/expirylist", {
        method: "POST", headers,
        body: JSON.stringify({ UnderlyingScrip: mapping.underlyingScrip, UnderlyingSeg: mapping.underlyingSeg }),
      });
      const raw = await expiryRes.text();
      let parsed: any = null;
      try { parsed = raw ? JSON.parse(raw) : null; } catch { parsed = null; }
      if (!expiryRes.ok || !parsed || !Array.isArray(parsed.data) || parsed.data.length === 0) {
        return c.json({ status: "FAIL", phase: "D6.1", module: "M1_PREMIUM_COMPOSITION", step: "expirylist", httpStatus: expiryRes.status }, 502);
      }
      expiries = parsed.data;
      DHAN_LIVE_CACHE.set(expiryCacheKey, { fetchedAt: Date.now(), payload: expiries });
    }
    const targetExpiry = expiries[0];

    const chainCacheKey = `optionchain_${symbolParam}_${targetExpiry}`;
    let chainFetchedAt: number;
    let chainPayload: any;
    const cachedChain = DHAN_LIVE_CACHE.get(chainCacheKey);
    if (cachedChain && Date.now() - cachedChain.fetchedAt < DHAN_LIVE_CACHE_TTL_MS) {
      chainPayload = cachedChain.payload;
      chainFetchedAt = cachedChain.fetchedAt;
    } else {
      const chainRes = await dhanRateLimitedFetch("https://api.dhan.co/v2/optionchain", {
        method: "POST", headers,
        body: JSON.stringify({ UnderlyingScrip: mapping.underlyingScrip, UnderlyingSeg: mapping.underlyingSeg, Expiry: targetExpiry }),
      });
      const raw = await chainRes.text();
      let parsed: any = null;
      try { parsed = raw ? JSON.parse(raw) : null; } catch { parsed = null; }
      if (!chainRes.ok || !parsed || !parsed.data || typeof parsed.data.oc !== "object") {
        return c.json({ status: "FAIL", phase: "D6.1", module: "M1_PREMIUM_COMPOSITION", step: "optionchain", httpStatus: chainRes.status }, 502);
      }
      chainPayload = parsed;
      chainFetchedAt = Date.now();
      DHAN_LIVE_CACHE.set(chainCacheKey, { fetchedAt: chainFetchedAt, payload: chainPayload });
    }

    const spot: number | null = typeof chainPayload.data.last_price === "number" ? chainPayload.data.last_price : null;
    const oc: Record<string, { ce?: any; pe?: any }> = chainPayload.data.oc;
    const allStrikes = Object.keys(oc).map((s) => parseFloat(s)).filter((n) => !Number.isNaN(n)).sort((a, b) => a - b);

    if (spot === null || allStrikes.length === 0) {
      return c.json({ status: "FAIL", phase: "D6.1", module: "M1_PREMIUM_COMPOSITION", error: "spot or strikes UNAVAILABLE from provider — fail-closed" }, 502);
    }

    let atmStrike = allStrikes[0];
    let atmDiff = Math.abs(atmStrike - spot);
    for (const s of allStrikes) {
      const diff = Math.abs(s - spot);
      if (diff < atmDiff) { atmDiff = diff; atmStrike = s; }
    }

    const atmKey = Object.keys(oc).find((k) => parseFloat(k) === atmStrike)!;
    const legs: { side: "CE" | "PE"; raw: any | undefined }[] = [
      { side: "CE", raw: oc[atmKey]?.ce },
      { side: "PE", raw: oc[atmKey]?.pe },
    ];

    const freshnessMs = Date.now() - chainFetchedAt;
    const freshnessStatus: D6M1FieldCheck = {
      field: "timestamp/data freshness",
      status: freshnessMs <= 60_000 ? "PASS" : "PARTIAL",
      detail: `Backend fetch was ${freshnessMs}ms ago (Dhan does not expose an exchange-side quoteTimestamp on this endpoint — same limitation already documented in D3/D4). Judged against backend receipt time only.`,
    };
    if (freshnessStatus.status !== "PASS") invalidOrPartialReasons.push(freshnessStatus.detail);

    // --- D6.1.1: instrument master fetch (cached 24h) for lotSize/tickSize/tradingSymbol ---
    const instrumentMaster = await getDhanInstrumentMaster(accessToken, clientId);
    if (instrumentMaster.error) invalidOrPartialReasons.push(`instrument master: ${instrumentMaster.error}`);

    const sampleComposition: any[] = [];
    let contractIdentityOverall: "PASS" | "INVALID" = "PASS";
    let priceBoundAnomalyCount = 0;
    const sameContractComparisons: any[] = [];

    for (const { side, raw } of legs) {
      const fieldChecks: D6M1FieldCheck[] = [];

      // --- Contract identity (fail-closed per spec table) ---
      const securityId = raw && typeof raw.security_id === "number" ? raw.security_id : null;
      const identityOk = !!raw && securityId !== null && !!targetExpiry && !!atmStrike && (side === "CE" || side === "PE");
      fieldChecks.push({
        field: "securityId + underlying + expiry + strike + CE/PE identity",
        status: identityOk ? "PASS" : "INVALID",
        detail: identityOk
          ? `securityId=${securityId}, ${symbolParam}, ${targetExpiry}, strike=${atmStrike}, ${side}`
          : "Leg missing or securityId not returned by provider — treated as INVALID, not defaulted.",
      });
      if (!identityOk) { contractIdentityOverall = "INVALID"; invalidOrPartialReasons.push(`${side} leg failed contract identity check`); }

      const lastPrice = raw && typeof raw.last_price === "number" ? raw.last_price : null;
      fieldChecks.push({
        field: "option LTP",
        status: lastPrice !== null ? "PASS" : "INVALID",
        detail: lastPrice !== null ? `${lastPrice}` : "missing_required_price — INVALID per fail-closed rule, not treated as 0.",
      });

      // --- Reuse M1's REAL, unmodified functions directly. No reimplementation. ---
      let intrinsic: number | null = null;
      let extrinsic: number | null = null;
      let intrinsicPct: number | null = null;
      let extrinsicPct: number | null = null;
      let dhanImpliedIntrinsicMatch: boolean | null = null;
      if (lastPrice !== null && spot !== null) {
        intrinsic = v2ComputeIntrinsicValue(side, spot, atmStrike); // <-- actual M1 function, unmodified
        extrinsic = Math.max(lastPrice - intrinsic, 0);
        intrinsicPct = v2PctPart(intrinsic, lastPrice); // <-- actual M1 function, unmodified
        extrinsicPct = v2PctPart(extrinsic, lastPrice);
        // Cross-check: does M1's formula reproduce the same intrinsic D4 already computed independently?
        const d4StyleIntrinsic = side === "CE" ? Math.max(0, spot - atmStrike) : Math.max(0, atmStrike - spot);
        dhanImpliedIntrinsicMatch = Math.abs(d4StyleIntrinsic - intrinsic) < 1e-9;
      }

      // --- D6.1.1: price-bound validation (no-arbitrage floor check) ---
      let priceBoundAnomaly = false;
      let priceBoundDeficit: number | null = null;
      if (lastPrice !== null && intrinsic !== null) {
        const check = checkPriceBound(lastPrice, intrinsic);
        priceBoundAnomaly = check.anomaly;
        priceBoundDeficit = check.deficit;
        if (priceBoundAnomaly) {
          priceBoundAnomalyCount++;
          invalidOrPartialReasons.push(`${side}: PRICE_BOUND_ANOMALY — LTP ${lastPrice} is below intrinsic ${intrinsic} by ${check.deficit.toFixed(2)}, beyond ${PRICE_BOUND_TOLERANCE} tolerance. Excluded from valid composition evidence.`);
          // Per fail-closed rule: intrinsicPct above 100 from this condition is NOT published as valid evidence.
          intrinsicPct = null;
          extrinsicPct = null;
        }
      }
      fieldChecks.push({
        field: "price-bound validation (LTP vs no-arbitrage intrinsic floor)",
        status: priceBoundAnomaly ? "INVALID" : lastPrice !== null && intrinsic !== null ? "PASS" : "PARTIAL",
        detail: priceBoundAnomaly
          ? `PRICE_BOUND_ANOMALY: deficit=${priceBoundDeficit?.toFixed(2)} — excluded from valid evidence, not published as intrinsicPct>100`
          : lastPrice !== null && intrinsic !== null ? "within bounds" : "could not evaluate — missing LTP or intrinsic",
      });
      fieldChecks.push({
        field: "intrinsic value (M1 formula: v2ComputeIntrinsicValue, unmodified)",
        status: intrinsic !== null ? "PASS" : "INVALID",
        detail: intrinsic !== null ? `intrinsic=${intrinsic}, formulaCrossCheckMatch=${dhanImpliedIntrinsicMatch}` : "could not compute — missing spot or LTP",
      });
      fieldChecks.push({
        field: "extrinsic value (derived, never fabricated)",
        status: extrinsic !== null ? "PASS" : "INVALID",
        detail: extrinsic !== null ? `extrinsic=${extrinsic}` : "could not compute",
      });

      const ivRaw = raw && typeof raw.implied_volatility === "number" ? raw.implied_volatility : null;
      const ivSuspect = ivRaw === 0 && lastPrice !== null && lastPrice > 0;
      fieldChecks.push({
        field: "IV (Dhan native)",
        status: ivRaw === null ? "IV_UNAVAILABLE" : ivSuspect ? "IV_UNAVAILABLE" : "PASS",
        detail: ivRaw === null ? "not returned by provider" : ivSuspect ? `raw value 0 but lastPrice=${lastPrice}>0 — known Dhan zero-DTE/deep-ITM quirk (see D4), treated as UNAVAILABLE not as a real 0` : `${ivRaw}`,
      });
      if (ivRaw === null || ivSuspect) invalidOrPartialReasons.push(`${side}: IV_UNAVAILABLE`);

      const delta = raw?.greeks?.delta, gamma = raw?.greeks?.gamma, theta = raw?.greeks?.theta, vega = raw?.greeks?.vega;
      const greeksAllZero = delta === 0 && gamma === 0 && theta === 0 && vega === 0;
      const greeksSuspect = greeksAllZero && lastPrice !== null && lastPrice > 0;
      const greeksMissing = [delta, gamma, theta, vega].some((v) => typeof v !== "number");
      fieldChecks.push({
        field: "Greeks: delta/gamma/theta/vega (Dhan native)",
        status: greeksMissing ? "GREEKS_UNAVAILABLE" : greeksSuspect ? "GREEKS_UNAVAILABLE" : "PASS",
        detail: greeksMissing ? "one or more Greeks not returned by provider" : greeksSuspect ? `all Greeks literally 0 but lastPrice=${lastPrice}>0 — known quirk, treated as UNAVAILABLE not as real 0 (fake_zero_for_missing_data is PROHIBITED)` : `delta=${delta}, gamma=${gamma}, theta=${theta}, vega=${vega}`,
      });
      if (greeksMissing || greeksSuspect) invalidOrPartialReasons.push(`${side}: GREEKS_UNAVAILABLE`);

      const oi = raw && typeof raw.oi === "number" ? raw.oi : null;
      fieldChecks.push({ field: "OI", status: oi !== null ? "PASS" : "PARTIAL", detail: oi !== null ? `${oi}` : "missing_oi — PARTIAL per fail-closed rule" });
      if (oi === null) invalidOrPartialReasons.push(`${side}: OI missing (PARTIAL)`);

      const bid = raw && typeof raw.top_bid_price === "number" ? raw.top_bid_price : null;
      const ask = raw && typeof raw.top_ask_price === "number" ? raw.top_ask_price : null;
      fieldChecks.push({
        field: "bid/ask (same securityId)",
        status: bid !== null && ask !== null ? "PASS" : "PARTIAL",
        detail: bid !== null && ask !== null ? `bid=${bid}, ask=${ask}, securityId=${securityId}` : "one or both missing",
      });

      const tradingSymbolCheck: D6M1FieldCheck = (() => {
        if (securityId === null) {
          return { field: "tradingSymbol / lotSize / tickSize (instrument master)", status: "UNAVAILABLE_FROM_PROVIDER", detail: "no securityId to look up" };
        }
        const meta = instrumentMaster.bySecurityId.get(String(securityId));
        if (!meta || (meta.lotSize === null && meta.tickSize === null && meta.tradingSymbol === null)) {
          return { field: "tradingSymbol / lotSize / tickSize (instrument master)", status: "PARTIAL", detail: `securityId ${securityId} not found in instrument master CSV (or all target columns unidentifiable by header) — per spec, missing metadata is PARTIAL, not PASS` };
        }
        const missingSome = meta.lotSize === null || meta.tickSize === null;
        return {
          field: "tradingSymbol / lotSize / tickSize (instrument master)",
          status: missingSome ? "PARTIAL" : "PASS",
          detail: `lotSize=${meta.lotSize}, tickSize=${meta.tickSize}, tradingSymbol=${meta.tradingSymbol}, expirySeriesType=${meta.expirySeriesType}${instrumentMaster.fromCache ? " (from 24h cache)" : " (freshly fetched)"}`,
        };
      })();
      if (tradingSymbolCheck.status !== "PASS") invalidOrPartialReasons.push(`${side}: ${tradingSymbolCheck.detail}`);
      const instrumentMeta = securityId !== null ? instrumentMaster.bySecurityId.get(String(securityId)) || null : null;

      const moneyness: "ITM" | "ATM" | "OTM" = side === "CE"
        ? (atmStrike === spot ? "ATM" : atmStrike < spot ? "ITM" : "OTM")
        : (atmStrike === spot ? "ATM" : atmStrike > spot ? "ITM" : "OTM");

      // --- D6.1.1: shadow history — same securityId+expiry+strike+CE/PE only ---
      let sameContractComparison: any = { status: "INSUFFICIENT_HISTORY" };
      if (securityId !== null && lastPrice !== null && intrinsic !== null && !priceBoundAnomaly) {
        const historyKey = `${symbolParam}_${side}`;
        const history = DHAN_SHADOW_M1_HISTORY.get(historyKey) || [];
        // Find the most recent PRIOR point with an EXACT identity match (fail-closed: never compares across a mismatch)
        const prior = [...history].reverse().find(
          (p) => p.securityId === securityId && p.expiry === targetExpiry && p.strike === atmStrike && p.optionType === side && !p.priceBoundAnomaly
        );
        if (prior) {
          sameContractComparison = {
            status: "OK",
            identityMatch: true,
            previousFetchedAt: new Date(prior.fetchedAt).toISOString(),
            premiumChange: lastPrice - prior.lastPrice,
            intrinsicChange: intrinsic - prior.intrinsic,
            extrinsicChange: (extrinsic ?? 0) - prior.extrinsic,
          };
        }
        pushShadowSnapshot(historyKey, {
          fetchedAt: chainFetchedAt, securityId, expiry: targetExpiry, strike: atmStrike, optionType: side,
          lastPrice, intrinsic, extrinsic: extrinsic ?? 0,
          iv: ivSuspect ? null : ivRaw, delta: greeksSuspect ? null : delta, gamma: greeksSuspect ? null : gamma,
          theta: greeksSuspect ? null : theta, vega: greeksSuspect ? null : vega, oi, priceBoundAnomaly,
        });
      }
      sameContractComparisons.push({ side, ...sameContractComparison });

      sampleComposition.push({
        side, strike: atmStrike, moneyness, spot, expiry: targetExpiry,
        securityId, lastPrice, intrinsic, extrinsic, intrinsicPct, extrinsicPct,
        iv: ivSuspect ? null : ivRaw, delta: greeksSuspect ? null : delta, gamma: greeksSuspect ? null : gamma,
        theta: greeksSuspect ? null : theta, vega: greeksSuspect ? null : vega, oi,
        priceBoundAnomaly,
        instrumentMetadata: instrumentMeta ? { lotSize: instrumentMeta.lotSize, tickSize: instrumentMeta.tickSize, tradingSymbol: instrumentMeta.tradingSymbol, expirySeriesType: instrumentMeta.expirySeriesType } : null,
        compositionState: sameContractComparison.status === "OK" ? "SAME_CONTRACT_COMPARISON_AVAILABLE" : "INSUFFICIENT_HISTORY",
        fieldChecks: [...fieldChecks, tradingSymbolCheck, freshnessStatus],
      });
    }

    const anyInvalid = sampleComposition.some((s) =>
      s.fieldChecks.some((f: D6M1FieldCheck) => f.status === "INVALID" && !f.field.startsWith("price-bound validation"))
    );
    const overallStatus = contractIdentityOverall === "INVALID" || anyInvalid
      ? "FAIL"
      : invalidOrPartialReasons.length > 0
        ? "PARTIAL_PASS"
        : "PASS";

    const snapshotCounts = ["CE", "PE"].map((side) => ({
      side,
      count: (DHAN_SHADOW_M1_HISTORY.get(`${symbolParam}_${side}`) || []).length,
    }));

    // --- D6.1.2: call the REAL production function (not a re-implementation)
    // to prove the actual cutover, not just this diagnostic's own math. ---
    const isDhanProductionSymbol = symbolParam === "NIFTY" || symbolParam === "BANKNIFTY";
    const productionResult = isDhanProductionSymbol
      ? buildV2PremiumCompositionHistory(symbolParam as V2PremiumSymbol, 20)
      : null; // SENSEX: production still Kite-backed, not queried here (needs Kite session cookie, out of scope for this Dhan-only diagnostic)
    const productionSnapshotCount = DHAN_M1_PRODUCTION_HISTORY.get(symbolParam as "NIFTY" | "BANKNIFTY")?.length || 0;

    return c.json({
      status: overallStatus,
      phase: "D6.1.2",
      module: "M1_PREMIUM_COMPOSITION",
      generatedAt: new Date().toISOString(),
      // Diagnostic path (this endpoint's own legs) is Dhan-backed:
      provider: "DHAN",
      symbol: symbolParam,
      // PRODUCTION status — genuinely cut over for NIFTY/BANKNIFTY, confirmed
      // by the user with explicit risk acknowledgement. SENSEX stays on Kite
      // (no confirmed Dhan security ID — deliberate, not an oversight).
      productionM1Provider: isDhanProductionSymbol ? "DHAN" : "KITE",
      productionHistorySource: isDhanProductionSymbol ? "DHAN_NORMALIZED_SNAPSHOTS" : "KITE_RECORDER_UNCHANGED",
      kiteRecorderUsedByM1: !isDhanProductionSymbol,
      productionSnapshotCount,
      productionResult, // actual output of the live buildV2PremiumCompositionHistory() call — same function the dashboard/M6/M7 call
      shadowM1Provider: "DHAN",
      shadowHistorySource: "DHAN_NORMALIZED_SNAPSHOTS",
      snapshotCount: snapshotCounts,
      contractIdentity: contractIdentityOverall,
      freshness: freshnessStatus.status,
      fieldAvailability: sampleComposition.map((s) => ({ side: s.side, checks: s.fieldChecks })),
      sampleComposition: sampleComposition.map(({ fieldChecks, ...rest }) => rest),
      sameContractComparison: sameContractComparisons,
      priceBoundValidation: {
        tolerance: PRICE_BOUND_TOLERANCE,
        anomalyCount: priceBoundAnomalyCount,
        note: priceBoundAnomalyCount > 0
          ? "One or more legs breached the no-arbitrage intrinsic floor beyond tolerance — excluded from valid evidence, intrinsicPct not published for those legs."
          : "No price-bound anomalies detected in this snapshot.",
      },
      instrumentMasterMetadata: {
        fetchedFromCache: instrumentMaster.fromCache,
        error: instrumentMaster.error || null,
        legsResolved: sampleComposition.filter((s) => s.instrumentMetadata !== null).length,
        legsTotal: sampleComposition.length,
      },
      invalidOrPartialReasons,
      zerodhaFallbackUsed: false, // provably true for the Dhan production path — buildDhanM1CompositionHistory never references recorderSession
      scoringChanged: false, // v2ComputeIntrinsicValue/v2PctPart/v2CompositionState/v2BuildComparison are called by reference, unmodified — see diff report
      orderAccessUsed: false,
      scopeNote: isDhanProductionSymbol
        ? "PRODUCTION CUTOVER LIVE for this symbol: buildV2PremiumCompositionHistory() now routes to Dhan for NIFTY/BANKNIFTY. Background refresh runs every 3 minutes independent of this request. SENSEX remains on the original Kite path (buildV2PremiumCompositionHistoryKite, unchanged) — no confirmed Dhan security ID exists for it."
        : "This symbol (SENSEX) is NOT part of the Dhan cutover — production still reads the original Kite-backed function, unchanged.",
      readOnlyMode: true,
      tokenExposed: false,
    });
  } catch (err) {
    return c.json({
      status: "FAIL", phase: "D6.1", module: "M1_PREMIUM_COMPOSITION",
      generatedAt: new Date().toISOString(), symbol: symbolParam,
      step: "network-error", error: err instanceof Error ? err.message : String(err),
    }, 500);
  }
});


// ============================================================================
// V3-D STEP 1 — DHAN RAW DATA AVAILABILITY AUDIT (READ-ONLY, DIAGNOSTIC ONLY)
//
// Purpose: audit exactly what raw data Dhan's historical Charts API returns
// for index spot OHLC — before ANY V3 engine, feature derivation, or
// backtest work begins. Read-only. Does NOT feed V2 scoring, does NOT write
// to any store, does NOT touch buildV2PremiumCompositionHistory, the Rule
// Engine, or any Verdict path. Reuses existing D1-D5 Dhan credentials,
// DHAN_UNDERLYING_MAP and the existing rate-limited fetch helper — no new
// duplicate identity source for NIFTY/BANKNIFTY.
//
// SENSEX: DHAN_UNDERLYING_MAP has no confirmed SENSEX entry (see D2). This
// endpoint separately test-probes an UNOFFICIAL candidate (securityId=51,
// IDX_I) sourced from a third-party community SDK README — NOT Dhan's
// official docs. The probe result is clearly labelled isUnofficialCandidate
// and carries a promotionGate note: it must NEVER be copied into
// DHAN_UNDERLYING_MAP without Bhagi Sir's explicit confirmation after
// reviewing this output.
//
// Auth: requires ?key=<DHAN_AUDIT_KEY> (set in Railway Variables) or the
// route 403s. Keeps this diagnostic route from sitting open on the public
// internet.
// ============================================================================

type DhanAuditStatus = "PASS" | "PARTIAL" | "UNAVAILABLE" | "ERROR";

// Unofficial candidate only — sourced from a third-party community SDK
// README, NOT Dhan's official documentation, and NOT part of the confirmed
// DHAN_UNDERLYING_MAP used by D1-D6 production paths. Exists solely so
// V3-D Step 1 can test-verify it with a real API call.
const DHAN_SENSEX_UNCONFIRMED_CANDIDATE = { underlyingScrip: 51, underlyingSeg: "IDX_I" };

async function dhanAuditSpotHistory(
  symbol: string,
  mapping: { underlyingScrip: number; underlyingSeg: string },
  isUnofficialCandidate: boolean
) {
  const generatedAt = new Date().toISOString();
  const accessToken = (await getValidDhanAccessToken()) || "";
  const clientId = process.env.DHAN_CLIENT_ID?.trim() || "";
  if (!accessToken || !clientId) {
    return {
      architectureRole: "V3D_STEP1_DHAN_RAW_AUDIT",
      generatedAt, symbol, dataField: "spot_history",
      status: "ERROR" as DhanAuditStatus,
      error: "DHAN_ACCESS_TOKEN or DHAN_CLIENT_ID missing in Railway variables",
    };
  }

  const toDate = new Date();
  const fromDate = new Date(toDate.getTime() - 5 * 24 * 60 * 60 * 1000);
  const fmt = (d: Date) => d.toISOString().slice(0, 10);

  try {
    const res = await dhanRateLimitedFetch("https://api.dhan.co/v2/charts/historical", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Accept: "application/json",
        "access-token": accessToken,
        "client-id": clientId,
      },
      body: JSON.stringify({
        securityId: String(mapping.underlyingScrip),
        exchangeSegment: mapping.underlyingSeg,
        instrument: "INDEX",
        expiryCode: 0,
        oi: false,
        fromDate: fmt(fromDate),
        toDate: fmt(toDate),
      }),
    });

    const httpStatus = res.status;
    const raw = await res.text();
    let payload: any = null;
    try { payload = raw ? JSON.parse(raw) : null; } catch { payload = null; }

    if (!res.ok || !payload || typeof payload !== "object") {
      return {
        architectureRole: "V3D_STEP1_DHAN_RAW_AUDIT",
        generatedAt, symbol, dataField: "spot_history",
        status: "ERROR" as DhanAuditStatus,
        httpStatus,
        isUnofficialCandidate,
        securityIdTested: mapping.underlyingScrip,
        providerError: payload && typeof payload === "object" ? {
          errorType: payload.errorType ?? null,
          errorCode: payload.errorCode ?? null,
          errorMessage: payload.errorMessage ?? null,
        } : { errorType: "NON_JSON_RESPONSE", errorCode: null, errorMessage: `Dhan historical returned HTTP ${httpStatus}` },
        rawSnippet: raw.slice(0, 300),
        readOnlyMode: true, tokenExposed: false,
      };
    }

    const expectedFields = ["open", "high", "low", "close", "volume", "timestamp"];
    const fieldAudit: Record<string, any> = {};
    let presentCount = 0;

    for (const f of expectedFields) {
      const has = Object.prototype.hasOwnProperty.call(payload, f);
      const val = payload[f];
      const isArray = Array.isArray(val);
      const len = isArray ? val.length : null;
      const lastValue = isArray && len && len > 0 ? val[len - 1] : (has ? val : null);
      let provenance: "MISSING" | "PRESENT_EMPTY" | "PRESENT_WITH_DATA";
      if (!has) provenance = "MISSING";
      else if (isArray && len === 0) provenance = "PRESENT_EMPTY";
      else provenance = "PRESENT_WITH_DATA";
      if (provenance === "PRESENT_WITH_DATA") presentCount++;
      fieldAudit[f] = { provenance, candleCount: len, sampleLastValue: lastValue };
    }

    const timestampSample = fieldAudit.timestamp?.sampleLastValue ?? null;
    let timestampResolution = "UNKNOWN";
    if (typeof timestampSample === "number") {
      timestampResolution = timestampSample > 10_000_000_000 ? "EPOCH_MILLISECONDS" : "EPOCH_SECONDS";
    } else if (typeof timestampSample === "string") {
      timestampResolution = "STRING_ISO_OR_OTHER";
    }

    // Sanity check for the SENSEX candidate: SENSEX trades in the tens of
    // thousands; if "close" is wildly outside that band, this ID is
    // almost certainly NOT SENSEX.
    let candidateSanityCheck: string | undefined;
    if (isUnofficialCandidate) {
      const closeVal = fieldAudit.close?.sampleLastValue;
      if (typeof closeVal === "number") {
        candidateSanityCheck = closeVal > 40000 && closeVal < 150000
          ? "PLAUSIBLE_RANGE_FOR_SENSEX"
          : "IMPLAUSIBLE_RANGE — this securityId likely does NOT map to SENSEX, do not trust it";
      } else {
        candidateSanityCheck = "NO_NUMERIC_CLOSE_VALUE_TO_CHECK";
      }
    }

    const status: DhanAuditStatus =
      presentCount === expectedFields.length ? "PASS" :
      presentCount > 0 ? "PARTIAL" : "UNAVAILABLE";

    return {
      architectureRole: "V3D_STEP1_DHAN_RAW_AUDIT",
      generatedAt, symbol, dataField: "spot_history",
      status,
      httpStatus,
      isUnofficialCandidate,
      candidateSource: isUnofficialCandidate
        ? "Third-party community SDK README (NOT Dhan's official docs) — unverified until this probe and Bhagi Sir's explicit confirmation."
        : undefined,
      candidateSanityCheck,
      promotionGate: isUnofficialCandidate
        ? "DO NOT add to DHAN_UNDERLYING_MAP based on this result alone — requires Bhagi Sir's explicit confirmation after reviewing this output."
        : undefined,
      requestedRange: { fromDate: fmt(fromDate), toDate: fmt(toDate) },
      securityIdTested: mapping.underlyingScrip,
      exchangeSegment: mapping.underlyingSeg,
      fieldAudit,
      timestampResolution,
      timestampSampleRaw: timestampSample,
      provenanceRule: "DHAN_NATIVE fields only — nothing derived, nothing assumed.",
      limitations: [
        "This is a small (5-day) probe, not proof of 5-year availability — do not infer long-history availability from this result.",
        "Only spot_history (index OHLC) is checked here. Futures, expired options, live chain and instrument master need separate Step 1 checks.",
      ],
      v3StepGate: status === "PASS" ? "SAFE_TO_PROCEED_TO_NEXT_FIELD_CHECK" : "HOLD — resolve this field before continuing V3-D Step 1",
      readOnlyMode: true,
      orderAccessUsed: false,
      tokenExposed: false,
    };
  } catch (err) {
    return {
      architectureRole: "V3D_STEP1_DHAN_RAW_AUDIT",
      generatedAt, symbol, dataField: "spot_history",
      status: "ERROR" as DhanAuditStatus,
      isUnofficialCandidate,
      error: err instanceof Error ? err.message : "Unknown Dhan historical request failure",
      readOnlyMode: true, tokenExposed: false,
    };
  }
}

app.get("/api/audit/dhan-raw-check", async (c) => {
  const auditKey = process.env.DHAN_AUDIT_KEY?.trim() || "";
  const providedKey = c.req.query("key")?.trim() || "";
  if (!auditKey || providedKey !== auditKey) {
    return c.json({ status: "ERROR" as DhanAuditStatus, error: "Missing or invalid audit key." }, 403);
  }

  const symbolParam = (c.req.query("symbol") || "NIFTY").toUpperCase();

  if (symbolParam === "SENSEX") {
    const result = await dhanAuditSpotHistory("SENSEX", DHAN_SENSEX_UNCONFIRMED_CANDIDATE, true);
    return c.json(result, 200);
  }

  const mapping = DHAN_UNDERLYING_MAP[symbolParam];
  if (!mapping) {
    return c.json({
      architectureRole: "V3D_STEP1_DHAN_RAW_AUDIT",
      generatedAt: new Date().toISOString(),
      symbol: symbolParam,
      status: "ERROR" as DhanAuditStatus,
      error: "Symbol not in DHAN_UNDERLYING_MAP.",
      supportedSymbols: [...Object.keys(DHAN_UNDERLYING_MAP), "SENSEX"],
    }, 400);
  }

  const result = await dhanAuditSpotHistory(symbolParam, mapping, false);
  return c.json(result, 200);
});


// ============================================================================
// V3-D STEP 1 (continued) — EXPIRED OPTIONS HISTORY AUDIT (READ-ONLY, DIAGNOSTIC ONLY)
//
// Purpose: probe Dhan's Rolling Option History API (POST
// /v2/charts/rollingoption) for expired-options fields (OI, IV, OHLC,
// volume, spot) on a small ATM-CALL/nearest-weekly sample. Read-only,
// no writes, no scoring, no Kite fallback. Reuses D1-D5 Dhan credentials,
// DHAN_UNDERLYING_MAP and the rate-limited fetch helper.
//
// Field names in requiredData ("oi", "implied_volatility", "spot") are our
// best-effort read of Dhan's documentation summary, NOT a confirmed exact
// schema — the response is audited key-by-key against whatever Dhan
// actually returns, never against what we assumed it would return.
//
// Auth: requires ?key=<DHAN_AUDIT_KEY>, same gate as the spot_history probe.
// ============================================================================

app.get("/api/audit/dhan-expired-options-check", async (c) => {
  const auditKey = process.env.DHAN_AUDIT_KEY?.trim() || "";
  const providedKey = c.req.query("key")?.trim() || "";
  if (!auditKey || providedKey !== auditKey) {
    return c.json({ status: "ERROR", error: "Missing or invalid audit key." }, 403);
  }

  const symbolParam = (c.req.query("symbol") || "NIFTY").toUpperCase();
  const generatedAt = new Date().toISOString();
  const mapping = DHAN_UNDERLYING_MAP[symbolParam];

  if (!mapping) {
    return c.json({
      architectureRole: "V3D_STEP1_DHAN_RAW_AUDIT",
      generatedAt, symbol: symbolParam, dataField: "expired_options_history",
      status: "ERROR",
      error: "Symbol not in DHAN_UNDERLYING_MAP.",
      supportedSymbols: Object.keys(DHAN_UNDERLYING_MAP),
    }, 400);
  }

  const accessToken = (await getValidDhanAccessToken()) || "";
  const clientId = process.env.DHAN_CLIENT_ID?.trim() || "";
  if (!accessToken || !clientId) {
    return c.json({
      architectureRole: "V3D_STEP1_DHAN_RAW_AUDIT",
      generatedAt, symbol: symbolParam, dataField: "expired_options_history",
      status: "ERROR",
      error: "DHAN_ACCESS_TOKEN or DHAN_CLIENT_ID missing in Railway variables",
    }, 503);
  }

  const toDate = new Date();
  const fromDate = new Date(toDate.getTime() - 10 * 24 * 60 * 60 * 1000);
  const fmt = (d: Date) => d.toISOString().slice(0, 10);

  // NIFTY/BANKNIFTY trade on NSE_FNO; SENSEX trades on BSE_FNO. The
  // DHAN_UNDERLYING_MAP segment (IDX_I) is the SPOT index segment, not the
  // derivatives segment, so it is NOT reused here — never assume, map
  // explicitly per exchange.
  const optionsSegment = symbolParam === "SENSEX" ? "BSE_FNO" : "NSE_FNO";

  const requestBody = {
    exchangeSegment: optionsSegment,
    interval: "1",
    securityId: mapping.underlyingScrip,
    instrument: "OPTIDX",
    expiryFlag: "WEEK",
    expiryCode: 1, // Dhan DH-905 "expiryCode is required" when 0 was sent — 1-indexed nearest expiry, confirmed by live probe on 2026-08-11
    strike: "ATM",
    drvOptionType: "CALL",
    requiredData: ["open", "high", "low", "close", "volume", "oi", "implied_volatility", "spot"],
    fromDate: fmt(fromDate),
    toDate: fmt(toDate),
  };

  try {
    const res = await dhanRateLimitedFetch("https://api.dhan.co/v2/charts/rollingoption", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Accept: "application/json",
        "access-token": accessToken,
        "client-id": clientId,
      },
      body: JSON.stringify(requestBody),
    });

    const httpStatus = res.status;
    const raw = await res.text();
    let payload: any = null;
    try { payload = raw ? JSON.parse(raw) : null; } catch { payload = null; }

    if (!res.ok || !payload || typeof payload !== "object") {
      return c.json({
        architectureRole: "V3D_STEP1_DHAN_RAW_AUDIT",
        generatedAt, symbol: symbolParam, dataField: "expired_options_history",
        status: "ERROR",
        httpStatus,
        requestSent: requestBody,
        providerError: payload && typeof payload === "object" ? {
          errorType: payload.errorType ?? null,
          errorCode: payload.errorCode ?? null,
          errorMessage: payload.errorMessage ?? null,
        } : { errorType: "NON_JSON_OR_EMPTY", errorCode: null, errorMessage: `Dhan rollingoption returned HTTP ${httpStatus}` },
        rawSnippet: raw.slice(0, 500),
        readOnlyMode: true, tokenExposed: false,
      }, 200);
    }

    // Schema NOT hardcoded in advance — audit exactly whatever keys came
    // back, whatever they are, rather than checking for names we guessed.
    const fieldAudit: Record<string, any> = {};
    let presentCount = 0;
    const keys = Object.keys(payload);
    for (const k of keys) {
      const val = payload[k];
      const isArray = Array.isArray(val);
      const len = isArray ? val.length : null;
      const lastValue = isArray && len && len > 0 ? val[len - 1] : val;
      const provenance = isArray && len === 0 ? "PRESENT_EMPTY" : "PRESENT_WITH_DATA";
      if (provenance === "PRESENT_WITH_DATA") presentCount++;
      fieldAudit[k] = { provenance, candleCount: len, sampleLastValue: lastValue };
    }

    return c.json({
      architectureRole: "V3D_STEP1_DHAN_RAW_AUDIT",
      generatedAt, symbol: symbolParam, dataField: "expired_options_history",
      status: keys.length > 0 ? "PASS" : "UNAVAILABLE",
      httpStatus,
      requestSent: requestBody,
      responseKeysFound: keys,
      fieldAudit,
      provenanceRule: "DHAN_NATIVE fields only — nothing derived, nothing assumed. Every key above is exactly what Dhan returned, not what we requested.",
      limitations: [
        "Small (10-day) probe only, ATM CALL, nearest weekly expiry — not proof of the full 5-year / multi-strike / multi-expiry availability the final matrix needs.",
        "requiredData field names (oi, implied_volatility, spot) were our best-effort read of Dhan's docs, not a confirmed schema — check fieldAudit for what actually came back.",
      ],
      v3StepGate: keys.length > 0 ? "SAFE_TO_PROCEED_TO_NEXT_FIELD_CHECK" : "HOLD — resolve this field before continuing V3-D Step 1",
      readOnlyMode: true, orderAccessUsed: false, tokenExposed: false,
    }, 200);
  } catch (err) {
    return c.json({
      architectureRole: "V3D_STEP1_DHAN_RAW_AUDIT",
      generatedAt, symbol: symbolParam, dataField: "expired_options_history",
      status: "ERROR",
      error: err instanceof Error ? err.message : "Unknown Dhan rollingoption request failure",
      readOnlyMode: true, tokenExposed: false,
    }, 500);
  }
});


// ============================================================================
// V3-D STEP 1 (continued) — INSTRUMENT MASTER + FUTURES HISTORY AUDIT
// (READ-ONLY, DIAGNOSTIC ONLY)
//
// Shared helper: streams Dhan's public compact scrip-master CSV
// (https://images.dhan.co/api-data/api-scrip-master.csv) and stops early
// once a handful of matching FUTIDX/OPTIDX sample rows are found for the
// requested symbol+exchange, rather than loading the entire multi-MB file
// into memory. Column names are read from the CSV's own header row, never
// hardcoded positions — if Dhan reorders columns this still works.
//
// Two endpoints reuse this helper:
//   /api/audit/dhan-instrument-master  — audits the master-list fields
//     themselves (securityId, lot size, tick size, trading symbol, etc.)
//   /api/audit/dhan-futures-check      — resolves the nearest-expiry
//     FUTIDX contract's real securityId from the master list (never
//     fabricated/guessed), then probes Dhan's historical OHLC+OI for it.
//
// Auth: both require ?key=<DHAN_AUDIT_KEY>, same gate as the other probes.
// ============================================================================

type DhanCsvRow = Record<string, string>;

async function dhanScanScripMaster(
  symbolParam: string,
  maxSamplesEach: number = 8
): Promise<{
  headerCols: string[] | null;
  colIndex: Record<string, number>;
  totalRowsScanned: number;
  futRows: DhanCsvRow[];
  optRows: DhanCsvRow[];
  idxRows: DhanCsvRow[];
  exchangeFiltered: string;
  fetchOk: boolean;
  httpStatus: number;
}> {
  const exchangeFilter = symbolParam === "SENSEX" ? "BSE" : "NSE";
  const res = await fetch("https://images.dhan.co/api-data/api-scrip-master.csv");
  if (!res.ok || !res.body) {
    return {
      headerCols: null, colIndex: {}, totalRowsScanned: 0,
      futRows: [], optRows: [], idxRows: [], exchangeFiltered: exchangeFilter,
      fetchOk: false, httpStatus: res.status,
    };
  }

  const reader = res.body.getReader();
  const decoder = new TextDecoder();
  let buffer = "";
  let headerCols: string[] | null = null;
  const colIndex: Record<string, number> = {};
  let totalRowsScanned = 0;
  const futRows: DhanCsvRow[] = [];
  const optRows: DhanCsvRow[] = [];
  const idxRows: DhanCsvRow[] = [];

  outer: while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    buffer += decoder.decode(value, { stream: true });
    const lines = buffer.split("\n");
    buffer = lines.pop() ?? "";
    for (const rawLine of lines) {
      const line = rawLine.trim();
      if (!line) continue;
      if (!headerCols) {
        headerCols = line.split(",");
        headerCols.forEach((h, i) => { colIndex[h.trim()] = i; });
        continue;
      }
      totalRowsScanned++;
      const cols = line.split(",");
      const exch = cols[colIndex["SEM_EXM_EXCH_ID"]] ?? "";
      const instType = cols[colIndex["SEM_INSTRUMENT_NAME"]] ?? "";
      const symName = cols[colIndex["SM_SYMBOL_NAME"]] ?? "";
      const tradingSymbol = cols[colIndex["SEM_TRADING_SYMBOL"]] ?? "";
      if (exch !== exchangeFilter) continue;
      // EXACT match only, not substring — "NIFTY" as a substring also
      // matches BANKNIFTY, FINNIFTY, MIDCPNIFTY, NIFTYNXT50, which is a
      // confirmed false-positive found via live audit on 2026-08-11. The
      // trading symbol always has "<SYMBOL>-<expiry>-..." shape, so require
      // that exact prefix + delimiter rather than a loose substring test.
      const symNameUp = symName.toUpperCase();
      const tradingSymbolUp = tradingSymbol.toUpperCase();
      const symbolMatches =
        symNameUp === symbolParam ||
        tradingSymbolUp === symbolParam ||
        tradingSymbolUp.startsWith(symbolParam + "-");
      if (!symbolMatches) continue;

      const row: DhanCsvRow = {};
      headerCols.forEach((h, i) => { row[h.trim()] = cols[i] ?? ""; });

      if (instType === "FUTIDX" && futRows.length < maxSamplesEach) futRows.push(row);
      if (instType === "OPTIDX" && optRows.length < maxSamplesEach) optRows.push(row);
      if (instType === "INDEX" && idxRows.length < maxSamplesEach) idxRows.push(row);

      if (futRows.length >= maxSamplesEach && optRows.length >= maxSamplesEach && idxRows.length >= 1) break outer;
    }
  }
  try { await reader.cancel(); } catch {}

  return { headerCols, colIndex, totalRowsScanned, futRows, optRows, idxRows, exchangeFiltered: exchangeFilter, fetchOk: true, httpStatus: res.status };
}

// ============================================================================
// DHAN FUTURES ADAPTER — Near-month futures VWAP bias (2026-08-14)
//
// Purpose: give TradeLab's Entry Quality layer a Dhan-sourced equivalent of
// the existing Kite "Rule-14" futuresVwapBias signal, so it no longer needs
// a Kite session for this one input. Reuses the SAME proven building blocks
// already live-verified for the V3 Historical Store Brain's F1 futures
// module: dhanScanScripMaster (above) for FUTIDX identity resolution, and
// /v2/charts/intraday for minute data (the daily endpoint is confirmed
// broken for FUTIDX with DH-905 — see fetchFuturesHistory elsewhere in this
// file; intraday is the proven-working path).
//
// Kite's signal compares near-month futures LTP against Kite's own
// session-traded average_price field. Dhan's intraday endpoint has no such
// field, so this computes a genuine volume-weighted VWAP from TODAY's
// minute bars (typical price = (H+L+C)/3 per candle, weighted by that
// candle's volume — the standard VWAP formula used industry-wide, not a
// fabricated number). If today has zero minute bars yet (market not open,
// or no data returned), this reports INSUFFICIENT/UNKNOWN honestly rather
// than silently substituting a stale day's data.
// ============================================================================

async function dhanFuturesVwapBias(symbol: "NIFTY" | "BANKNIFTY" | "SENSEX") {
  const accessToken = (await getValidDhanAccessToken()) || "";
  const clientId = process.env.DHAN_CLIENT_ID?.trim() || "";
  if (!accessToken || !clientId) {
    return { status: "SKIPPED" as const, reason: "DHAN_NOT_CONFIGURED", bias: "UNKNOWN" as const };
  }

  const scan = await dhanScanScripMaster(symbol, 8);
  if (!scan.fetchOk || !scan.headerCols || scan.futRows.length === 0) {
    return { status: "FAIL" as const, reason: "NO_FUTIDX_ROW_IN_SCRIP_MASTER", bias: "UNKNOWN" as const };
  }
  const sortedFut = [...scan.futRows].sort((a, b) => {
    const da = new Date(a["SEM_EXPIRY_DATE"] || "").getTime();
    const db = new Date(b["SEM_EXPIRY_DATE"] || "").getTime();
    return (isNaN(da) ? Infinity : da) - (isNaN(db) ? Infinity : db);
  });
  const nearest = sortedFut[0];
  const securityId = nearest["SEM_SMST_SECURITY_ID"];
  const tradingSymbol = nearest["SEM_TRADING_SYMBOL"] || null;
  const expiry = nearest["SEM_EXPIRY_DATE"] || null;
  if (!securityId) {
    return { status: "FAIL" as const, reason: "FUTIDX_ROW_MISSING_SECURITY_ID", bias: "UNKNOWN" as const, tradingSymbol, expiry };
  }

  const futuresSegment = symbol === "SENSEX" ? "BSE_FNO" : "NSE_FNO";
  const today = new Date().toISOString().slice(0, 10);
  const requestBodyObj = {
    securityId: String(securityId),
    exchangeSegment: futuresSegment,
    instrument: "FUTIDX",
    interval: "1",
    oi: false,
    fromDate: `${today} 09:15:00`,
    toDate: `${today} 23:59:59`,
  };

  try {
    const res = await dhanRateLimitedFetch("https://api.dhan.co/v2/charts/intraday", {
      method: "POST",
      headers: { "Content-Type": "application/json", Accept: "application/json", "access-token": accessToken, "client-id": clientId },
      body: JSON.stringify(requestBodyObj),
    });
    const raw = await res.text();
    let payload: any = null;
    try { payload = raw ? JSON.parse(raw) : null; } catch { payload = null; }

    if (!res.ok || !payload || typeof payload !== "object") {
      return { status: "FAIL" as const, reason: payload?.errorMessage || `intraday HTTP ${res.status}`, bias: "UNKNOWN" as const, tradingSymbol, expiry, securityId };
    }

    const highs: number[] = Array.isArray(payload.high) ? payload.high : [];
    const lows: number[] = Array.isArray(payload.low) ? payload.low : [];
    const closes: number[] = Array.isArray(payload.close) ? payload.close : [];
    const volumes: number[] = Array.isArray(payload.volume) ? payload.volume : [];
    const n = Math.min(highs.length, lows.length, closes.length, volumes.length);

    if (n === 0) {
      return { status: "INSUFFICIENT" as const, reason: "NO_INTRADAY_BARS_TODAY (market not yet open, or no data returned)", bias: "UNKNOWN" as const, tradingSymbol, expiry, securityId };
    }

    let sumPV = 0;
    let sumV = 0;
    for (let i = 0; i < n; i++) {
      const typicalPrice = (highs[i] + lows[i] + closes[i]) / 3;
      const vol = volumes[i] || 0;
      sumPV += typicalPrice * vol;
      sumV += vol;
    }
    const vwap = sumV > 0 ? sumPV / sumV : null;
    const lastPrice = closes[n - 1];
    const bias: "UP" | "DOWN" | "UNKNOWN" =
      vwap == null ? "UNKNOWN" : lastPrice > vwap ? "UP" : lastPrice < vwap ? "DOWN" : "UNKNOWN";

    return {
      status: "OK" as const,
      bias,
      vwap,
      lastPrice,
      sampleCount: n,
      totalVolume: sumV,
      tradingSymbol,
      expiry,
      securityId,
      methodology: "VWAP = volume-weighted typical price ((H+L+C)/3) across today's Dhan 1-minute FUTIDX bars so far. Dhan's intraday endpoint has no VWAP field of its own — this is computed here from genuine minute OHLCV data using the standard industry formula, not fabricated.",
    };
  } catch (e) {
    return { status: "FAIL" as const, reason: e instanceof Error ? e.message : "intraday futures request failed", bias: "UNKNOWN" as const, tradingSymbol, expiry, securityId };
  }
}

app.get("/api/audit/dhan-futures-vwap-bias-proof", async (c) => {
  const auditKey = process.env.DHAN_AUDIT_KEY?.trim() || "";
  const providedKey = c.req.query("key")?.trim() || "";
  if (!auditKey || providedKey !== auditKey) {
    return c.json({ status: "ERROR", error: "Missing or invalid audit key." }, 403);
  }
  const symbolParam = (c.req.query("symbol") || "NIFTY").toUpperCase();
  if (!(["NIFTY", "BANKNIFTY", "SENSEX"] as string[]).includes(symbolParam)) {
    return c.json({ status: "ERROR", error: "Unsupported symbol. Use NIFTY, BANKNIFTY, or SENSEX." }, 400);
  }
  const result = await dhanFuturesVwapBias(symbolParam as "NIFTY" | "BANKNIFTY" | "SENSEX");
  return c.json({ architectureRole: "DHAN_FUTURES_VWAP_BIAS_PROOF", readOnlyMode: true, orderAccessUsed: false, tokenExposed: false, ...result }, 200);
});

app.get("/api/audit/dhan-instrument-master", async (c) => {
  const auditKey = process.env.DHAN_AUDIT_KEY?.trim() || "";
  const providedKey = c.req.query("key")?.trim() || "";
  if (!auditKey || providedKey !== auditKey) {
    return c.json({ status: "ERROR", error: "Missing or invalid audit key." }, 403);
  }
  const symbolParam = (c.req.query("symbol") || "NIFTY").toUpperCase();
  const generatedAt = new Date().toISOString();

  try {
    const scan = await dhanScanScripMaster(symbolParam, 8);
    if (!scan.fetchOk || !scan.headerCols) {
      return c.json({
        architectureRole: "V3D_STEP1_DHAN_RAW_AUDIT",
        generatedAt, symbol: symbolParam, dataField: "instrument_master",
        status: "ERROR", httpStatus: scan.httpStatus,
        error: "Instrument master CSV fetch/parse failed.",
      }, 200);
    }

    const expectedFields = [
      "SEM_SMST_SECURITY_ID", "SM_SYMBOL_NAME", "SEM_INSTRUMENT_NAME",
      "SEM_EXPIRY_DATE", "SEM_STRIKE_PRICE", "SEM_OPTION_TYPE",
      "SEM_LOT_UNITS", "SEM_TICK_SIZE", "SEM_TRADING_SYMBOL",
    ];
    const fieldAudit: Record<string, any> = {};
    const sampleRow = scan.futRows[0] || scan.optRows[0] || null;
    for (const f of expectedFields) {
      fieldAudit[f] = {
        columnPresentInCsv: f in scan.colIndex,
        sampleValue: sampleRow ? (sampleRow[f] ?? null) : null,
      };
    }

    const status = (scan.futRows.length > 0 || scan.optRows.length > 0) ? "PASS" : "UNAVAILABLE";

    return c.json({
      architectureRole: "V3D_STEP1_DHAN_RAW_AUDIT",
      generatedAt, symbol: symbolParam, dataField: "instrument_master",
      status,
      exchangeFiltered: scan.exchangeFiltered,
      csvHeaderColumnCount: scan.headerCols.length,
      rowsScannedBeforeEnoughSamples: scan.totalRowsScanned,
      futuresContractsFound: scan.futRows.length,
      optionsContractsFound: scan.optRows.length,
      indexRowsFound: scan.idxRows.length,
      sampleFuturesRows: scan.futRows,
      sampleOptionsRows: scan.optRows.slice(0, 3),
      sampleIndexRows: scan.idxRows,
      fieldAudit,
      provenanceRule: "DHAN_NATIVE fields only — nothing derived, nothing assumed. Header columns read directly from the CSV, not hardcoded.",
      limitations: [
        "Scan stopped early once 8 sample futures + 8 sample options rows were found — rowsScannedBeforeEnoughSamples is a partial-scan count, not the file's true total row count.",
        "Only proves current/near-term contracts exist in the master — does not prove historical/expired listings were retained here.",
      ],
      v3StepGate: status === "PASS" ? "SAFE_TO_PROCEED_TO_NEXT_FIELD_CHECK" : "HOLD — resolve this field before continuing V3-D Step 1",
      readOnlyMode: true, orderAccessUsed: false, tokenExposed: false,
    }, 200);
  } catch (err) {
    return c.json({
      architectureRole: "V3D_STEP1_DHAN_RAW_AUDIT",
      generatedAt, symbol: symbolParam, dataField: "instrument_master",
      status: "ERROR",
      error: err instanceof Error ? err.message : "Unknown instrument master fetch failure",
      readOnlyMode: true, tokenExposed: false,
    }, 500);
  }
});

app.get("/api/audit/dhan-futures-check", async (c) => {
  const auditKey = process.env.DHAN_AUDIT_KEY?.trim() || "";
  const providedKey = c.req.query("key")?.trim() || "";
  if (!auditKey || providedKey !== auditKey) {
    return c.json({ status: "ERROR", error: "Missing or invalid audit key." }, 403);
  }
  const symbolParam = (c.req.query("symbol") || "NIFTY").toUpperCase();
  const generatedAt = new Date().toISOString();

  try {
    const scan = await dhanScanScripMaster(symbolParam, 8);
    if (!scan.fetchOk || !scan.headerCols) {
      return c.json({
        architectureRole: "V3D_BUG01_HISTORICAL_FUTURES_OI_MISSING",
        generatedAt, symbol: symbolParam, dataField: "futures_history",
        status: "ERROR", httpStatus: scan.httpStatus,
        error: "Could not read instrument master CSV to resolve a futures securityId.",
      }, 200);
    }
    if (scan.futRows.length === 0) {
      return c.json({
        architectureRole: "V3D_BUG01_HISTORICAL_FUTURES_OI_MISSING",
        generatedAt, symbol: symbolParam, dataField: "futures_history",
        status: "UNAVAILABLE",
        reason: "No FUTIDX row found for this symbol in the scrip master scan window.",
      }, 200);
    }

    const sorted = [...scan.futRows].sort((a, b) => {
      const da = new Date(a["SEM_EXPIRY_DATE"] || "").getTime();
      const db = new Date(b["SEM_EXPIRY_DATE"] || "").getTime();
      return (isNaN(da) ? Infinity : da) - (isNaN(db) ? Infinity : db);
    });
    const nearest = sorted[0];
    const securityId = nearest["SEM_SMST_SECURITY_ID"];
    const tradingSymbol = nearest["SEM_TRADING_SYMBOL"];
    const expiryDate = nearest["SEM_EXPIRY_DATE"];

    if (!securityId) {
      return c.json({
        architectureRole: "V3D_BUG01_HISTORICAL_FUTURES_OI_MISSING",
        generatedAt, symbol: symbolParam, dataField: "futures_history",
        status: "ERROR",
        error: "Matched a FUTIDX row but SEM_SMST_SECURITY_ID column was empty.",
        matchedRow: nearest,
      }, 200);
    }

    const accessToken = (await getValidDhanAccessToken()) || "";
    const clientId = process.env.DHAN_CLIENT_ID?.trim() || "";
    if (!accessToken || !clientId) {
      return c.json({
        architectureRole: "V3D_BUG01_HISTORICAL_FUTURES_OI_MISSING",
        generatedAt, symbol: symbolParam, dataField: "futures_history",
        status: "ERROR", error: "DHAN_ACCESS_TOKEN or DHAN_CLIENT_ID missing in Railway variables",
      }, 503);
    }

    const futuresSegment = symbolParam === "SENSEX" ? "BSE_FNO" : "NSE_FNO";
    const toDate = new Date();
    const fromDate = new Date(toDate.getTime() - 5 * 24 * 60 * 60 * 1000);
    const fmt = (d: Date) => d.toISOString().slice(0, 10);

    // Bug 01 check #1/#2: build the exact body, then prove oi:true is
    // literally present in the SERIALIZED string we send — not just in the
    // source object (a stray typo could silently drop it during stringify).
    const requestBodyObj = {
      securityId: String(securityId),
      exchangeSegment: futuresSegment,
      instrument: "FUTIDX",
      expiryCode: 1, // Dhan DH-905 confirmed live on 2026-08-12 (2 consecutive retries) -- 0 previously worked earlier the same day, now consistently rejected. Matches the same 0-treated-as-missing quirk already fixed for the options endpoints.
      oi: true,
      fromDate: fmt(fromDate),
      toDate: fmt(toDate),
    };
    const requestBodyStr = JSON.stringify(requestBodyObj);
    const oiFlagLiterallyInOutgoingBody = /"oi"\s*:\s*true/.test(requestBodyStr);

    async function probe(endpointUrl: string, endpointLabel: string) {
      const res = await dhanRateLimitedFetch(endpointUrl, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Accept: "application/json",
          "access-token": accessToken,
          "client-id": clientId,
        },
        body: requestBodyStr,
      });
      const httpStatus = res.status;
      const raw = await res.text();
      let payload: any = null;
      try { payload = raw ? JSON.parse(raw) : null; } catch { payload = null; }

      if (!res.ok || !payload || typeof payload !== "object") {
        return {
          endpointLabel, endpointUrl, httpStatus,
          ok: false,
          providerError: payload && typeof payload === "object" ? {
            errorType: payload.errorType ?? null,
            errorCode: payload.errorCode ?? null,
            errorMessage: payload.errorMessage ?? null,
          } : { errorType: "NON_JSON_OR_EMPTY", errorCode: null, errorMessage: `HTTP ${httpStatus}` },
          rawSnippet: raw.slice(0, 400),
        };
      }

      // Bug 01 check #3/#4/#5: dump EVERY top-level key Dhan actually
      // returned — no pre-decided field list — then case-insensitively
      // search all of them for anything OI-shaped, so a differently-named
      // or differently-cased field is never silently mistaken for MISSING.
      const rawTopLevelKeys = Object.keys(payload);
      const oiLikeKeyPattern = /(^oi$|open[_]?interest|openinterest)/i;
      const oiLikeKeysFound = rawTopLevelKeys.filter((k) => oiLikeKeyPattern.test(k));
      const rawOiPresent = oiLikeKeysFound.length > 0 &&
        oiLikeKeysFound.some((k) => Array.isArray(payload[k]) ? payload[k].length > 0 : payload[k] != null);

      const candleCounts: Record<string, number | null> = {};
      for (const k of rawTopLevelKeys) {
        candleCounts[k] = Array.isArray(payload[k]) ? payload[k].length : null;
      }

      return {
        endpointLabel, endpointUrl, httpStatus, ok: true,
        rawTopLevelKeys, candleCounts,
        oiLikeKeysFound, rawOiPresent,
        oiSampleTail: oiLikeKeysFound.length > 0 && Array.isArray(payload[oiLikeKeysFound[0]])
          ? payload[oiLikeKeysFound[0]].slice(-3)
          : (oiLikeKeysFound.length > 0 ? payload[oiLikeKeysFound[0]] : null),
      };
    }

    // Primary probe: /v2/charts/historical, which Dhan's own docs label
    // "Daily Historical Data" — this IS the daily endpoint, so the
    // "repeat with daily endpoint if supported" check is this same call;
    // there is no separate third daily endpoint to fall back to.
    const dailyResult = await probe("https://api.dhan.co/v2/charts/historical", "DAILY_HISTORICAL");

    // Normalized-adapter comparison: does the same rawTopLevelKeys audit
    // logic used elsewhere in this file (fieldAudit) agree with the raw
    // scan above? Re-derive it here from the SAME raw payload fetched
    // above (not a second network call) so there's no drift between the
    // two views.
    let normalizedOiPresent: boolean | null = null;
    let normalizedFieldAudit: Record<string, any> | null = null;
    if (dailyResult.ok) {
      const expectedFields = ["open", "high", "low", "close", "volume", "oi", "timestamp"];
      normalizedFieldAudit = {};
      for (const f of expectedFields) {
        const has = f in (dailyResult.candleCounts as Record<string, number | null>);
        normalizedFieldAudit[f] = has ? "PRESENT_IN_NORMALIZED_KEYSET" : "MISSING_FROM_NORMALIZED_KEYSET";
      }
      normalizedOiPresent = "oi" in (dailyResult.candleCounts as Record<string, number | null>);
    }

    // Classification per the Bug 01 spec's required_result_states.
    let rootCauseStatus: "PASS_OI_PRESENT" | "PARSER_BUG" | "REQUEST_BUG_OI_FLAG_MISSING" | "PROVIDER_RESPONSE_ANOMALY" | "ERROR";
    let rootCauseNote: string;
    let safeFixIfLocalBug: string | null;

    if (!oiFlagLiterallyInOutgoingBody) {
      rootCauseStatus = "REQUEST_BUG_OI_FLAG_MISSING";
      rootCauseNote = "The outgoing serialized request body did not literally contain \"oi\":true.";
      safeFixIfLocalBug = "Fix requestBodyObj construction so oi:true survives JSON.stringify.";
    } else if (!dailyResult.ok) {
      rootCauseStatus = "ERROR";
      rootCauseNote = "Dhan's historical endpoint did not return a usable response to classify against.";
      safeFixIfLocalBug = null;
    } else if (dailyResult.rawOiPresent) {
      rootCauseStatus = "PASS_OI_PRESENT";
      rootCauseNote = `OI-like key(s) found in Dhan's raw response with data: ${dailyResult.oiLikeKeysFound.join(", ")}.`;
      safeFixIfLocalBug = normalizedOiPresent ? null : "Normalized field-audit list should also check this key name — extend expectedFields.";
    } else {
      rootCauseStatus = "PROVIDER_RESPONSE_ANOMALY";
      rootCauseNote = "oi:true was sent, Dhan returned HTTP 200 with a normal-looking OHLC/volume/timestamp payload, but no key matching oi / OI / open_interest / openInterest (case-insensitive) was present anywhere in the raw top-level response, and no OI field is documented separately for FUTIDX under this endpoint. This does not match a local parser bug — the raw payload itself lacks the field.";
      safeFixIfLocalBug = null;
    }

    return c.json({
      architectureRole: "V3D_BUG01_HISTORICAL_FUTURES_OI_MISSING",
      generatedAt, symbol: symbolParam, dataField: "futures_history",
      bugId: "V3D_BUG_01",
      contractIdentity: { securityId, tradingSymbol, expiryDate, resolvedFrom: "api-scrip-master.csv scan, not fabricated" },
      sanitizedRequestBody: requestBodyObj,
      oiFlagLiterallyInOutgoingBody,
      httpStatus: dailyResult.httpStatus,
      rawResponseKeys: dailyResult.ok ? dailyResult.rawTopLevelKeys : null,
      rawResponseCandleCounts: dailyResult.ok ? dailyResult.candleCounts : null,
      oiLikeKeysFound: dailyResult.ok ? dailyResult.oiLikeKeysFound : null,
      rawOiPresent: dailyResult.ok ? dailyResult.rawOiPresent : null,
      oiSampleTail: dailyResult.ok ? dailyResult.oiSampleTail : null,
      normalizedOiPresent,
      normalizedFieldAudit,
      providerError: !dailyResult.ok ? (dailyResult as any).providerError : null,
      rawSnippetIfError: !dailyResult.ok ? (dailyResult as any).rawSnippet : null,
      rootCauseStatus,
      rootCauseNote,
      safeFixIfLocalBug,
      bug01Closed: rootCauseStatus !== "ERROR",
      dailyVsIntradayNote: "Only the daily historical endpoint (/v2/charts/historical) was probed — Dhan's docs label this endpoint itself 'Daily Historical Data', so this satisfies the 'repeat with daily endpoint' check; no separate third daily endpoint exists to additionally try.",
      limitations: [
        "Small (5-day) probe only, nearest-expiry contract.",
        "securityId was resolved from a partial CSV scan, not the full file.",
        "No OI values were derived or fabricated anywhere in this diagnostic.",
      ],
      readOnlyMode: true, orderAccessUsed: false, tokenExposed: false,
    }, 200);
  } catch (err) {
    return c.json({
      architectureRole: "V3D_BUG01_HISTORICAL_FUTURES_OI_MISSING",
      generatedAt, symbol: symbolParam, dataField: "futures_history",
      status: "ERROR",
      error: err instanceof Error ? err.message : "Unknown Dhan historical (futures) request failure",
      readOnlyMode: true, tokenExposed: false,
    }, 500);
  }
});


// ============================================================================
// V3D_BUG_02 — HISTORICAL_OPTION_IV_EMPTY DIAGNOSTIC (READ-ONLY, DIAGNOSTIC ONLY)
//
// Runs 4 mandatory tests against Dhan's rollingoption endpoint
// (ATM CALL / ATM PUT x current-expiry / next-expiry), inspects the RAW
// response before any parsing, generically walks every nested object/array
// in the payload (not a pre-decided field list) to find every IV-shaped key
// and every array's length, and classifies the result per the Bug 02 spec.
//
// Hard rules honoured: no historical IV calculated, no zero substituted for
// missing IV, no 5-year fetch, no V2 production path touched.
// ============================================================================

// Generic deep scanner: walks the whole payload and records, for every
// array found at any nesting depth, its dotted path and length. Scalars
// are recorded as null so a path can be distinguished from "doesn't
// exist" vs "exists but isn't an array". This is intentionally NOT tied
// to any assumed schema (e.g. data.ce.iv) — if Dhan nests things
// differently than our earlier probe, this still finds it.
function dhanScanArrayPaths(obj: any, prefix: string, results: Record<string, number | null>) {
  if (obj === null || obj === undefined) return;
  if (Array.isArray(obj)) {
    results[prefix] = obj.length;
    return;
  }
  if (typeof obj === "object") {
    for (const k of Object.keys(obj)) {
      const path = prefix ? `${prefix}.${k}` : k;
      if (Array.isArray(obj[k])) {
        results[path] = obj[k].length;
      } else if (obj[k] !== null && typeof obj[k] === "object") {
        dhanScanArrayPaths(obj[k], path, results);
      } else {
        results[path] = null;
      }
    }
  }
}

app.get("/api/audit/dhan-bug02-iv-check", async (c) => {
  const auditKey = process.env.DHAN_AUDIT_KEY?.trim() || "";
  const providedKey = c.req.query("key")?.trim() || "";
  if (!auditKey || providedKey !== auditKey) {
    return c.json({ status: "ERROR", error: "Missing or invalid audit key." }, 403);
  }

  const symbolParam = (c.req.query("symbol") || "NIFTY").toUpperCase();
  const generatedAt = new Date().toISOString();
  const mapping = DHAN_UNDERLYING_MAP[symbolParam];

  if (!mapping) {
    return c.json({
      architectureRole: "V3D_BUG02_HISTORICAL_OPTION_IV_EMPTY",
      generatedAt, symbol: symbolParam, bugId: "V3D_BUG_02",
      status: "ERROR", error: "Symbol not in DHAN_UNDERLYING_MAP.",
    }, 400);
  }

  const accessToken = (await getValidDhanAccessToken()) || "";
  const clientId = process.env.DHAN_CLIENT_ID?.trim() || "";
  if (!accessToken || !clientId) {
    return c.json({
      architectureRole: "V3D_BUG02_HISTORICAL_OPTION_IV_EMPTY",
      generatedAt, symbol: symbolParam, bugId: "V3D_BUG_02",
      status: "ERROR", error: "DHAN_ACCESS_TOKEN or DHAN_CLIENT_ID missing in Railway variables",
    }, 503);
  }

  const optionsSegment = symbolParam === "SENSEX" ? "BSE_FNO" : "NSE_FNO";
  const toDate = new Date();
  const fromDate = new Date(toDate.getTime() - 10 * 24 * 60 * 60 * 1000);
  const fmt = (d: Date) => d.toISOString().slice(0, 10);

  const mandatoryTests = [
    { name: "ATM_CALL_CURRENT_OR_NEAR_EXPIRY", optionType: "CALL", expiryCode: 1 },
    { name: "ATM_PUT_CURRENT_OR_NEAR_EXPIRY", optionType: "PUT", expiryCode: 1 },
    { name: "ATM_CALL_NEXT_EXPIRY", optionType: "CALL", expiryCode: 2 },
    { name: "ATM_PUT_NEXT_EXPIRY", optionType: "PUT", expiryCode: 2 },
  ] as const;

  const ivKeyPattern = /(\biv\b|implied[_]?volatility)/i;
  const timestampKeyPattern = /timestamp/i;
  const oiKeyPattern = /(\boi\b|open[_]?interest)/i;
  const spotKeyPattern = /spot/i;

  const testResults: any[] = [];

  for (const test of mandatoryTests) {
    const requestBodyObj = {
      exchangeSegment: optionsSegment,
      interval: "1",
      securityId: mapping.underlyingScrip,
      instrument: "OPTIDX",
      expiryFlag: "WEEK",
      expiryCode: test.expiryCode,
      strike: "ATM",
      drvOptionType: test.optionType,
      requiredData: ["open", "high", "low", "close", "volume", "oi", "implied_volatility", "spot"],
      fromDate: fmt(fromDate),
      toDate: fmt(toDate),
    };
    const requestBodyStr = JSON.stringify(requestBodyObj);

    try {
      const res = await dhanRateLimitedFetch("https://api.dhan.co/v2/charts/rollingoption", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Accept: "application/json",
          "access-token": accessToken,
          "client-id": clientId,
        },
        body: requestBodyStr,
      });

      const httpStatus = res.status;
      const raw = await res.text();
      let payload: any = null;
      try { payload = raw ? JSON.parse(raw) : null; } catch { payload = null; }

      if (!res.ok || !payload || typeof payload !== "object") {
        testResults.push({
          test: test.name,
          sanitizedRequestBody: requestBodyObj,
          httpStatus,
          ok: false,
          providerError: payload && typeof payload === "object" ? {
            errorType: payload.errorType ?? null,
            errorCode: payload.errorCode ?? null,
            errorMessage: payload.errorMessage ?? null,
          } : { errorType: "NON_JSON_OR_EMPTY", errorCode: null, errorMessage: `HTTP ${httpStatus}` },
          rawSnippet: raw.slice(0, 400),
        });
        continue;
      }

      const arrayPaths: Record<string, number | null> = {};
      dhanScanArrayPaths(payload, "", arrayPaths);

      const allPaths = Object.keys(arrayPaths);
      const ivPaths = allPaths.filter((p) => ivKeyPattern.test(p));
      const timestampPaths = allPaths.filter((p) => timestampKeyPattern.test(p));
      const oiPaths = allPaths.filter((p) => oiKeyPattern.test(p));
      const spotPaths = allPaths.filter((p) => spotKeyPattern.test(p));

      const ivLengths = ivPaths.map((p) => arrayPaths[p]);
      const timestampLengths = timestampPaths.map((p) => arrayPaths[p]);
      const oiLengths = oiPaths.map((p) => arrayPaths[p]);
      const spotLengths = spotPaths.map((p) => arrayPaths[p]);

      const ivHasAnyData = ivLengths.some((len) => typeof len === "number" && len > 0);

      testResults.push({
        test: test.name,
        sanitizedRequestBody: requestBodyObj,
        httpStatus,
        ok: true,
        allArrayPaths: arrayPaths,
        ivFieldPaths: ivPaths,
        ivArrayLengths: ivLengths,
        timestampFieldPaths: timestampPaths,
        timestampArrayLengths: timestampLengths,
        oiFieldPaths: oiPaths,
        oiArrayLengths: oiLengths,
        spotFieldPaths: spotPaths,
        spotArrayLengths: spotLengths,
        ivHasAnyData,
      });
    } catch (err) {
      testResults.push({
        test: test.name,
        sanitizedRequestBody: requestBodyObj,
        ok: false,
        error: err instanceof Error ? err.message : "Unknown request failure",
      });
    }
  }

  // Classification across all 4 tests together, per the Bug 02 spec's
  // required_result_states.
  const okResults = testResults.filter((r) => r.ok);
  let rootCauseStatus: "PASS_IV_PRESENT" | "PARSER_BUG" | "REQUEST_SCHEMA_BUG" | "CONTRACT_OR_EXPIRY_SPECIFIC_BEHAVIOR" | "PROVIDER_RESPONSE_ANOMALY" | "ERROR";
  let rootCauseNote: string;
  let safeLocalFix: string | null;

  if (okResults.length === 0) {
    rootCauseStatus = "ERROR";
    rootCauseNote = "None of the 4 tests returned a usable HTTP 200 JSON response to classify against.";
    safeLocalFix = null;
  } else {
    const anyIvFieldFoundAtAll = okResults.some((r) => r.ivFieldPaths.length > 0);
    const allIvEmpty = okResults.every((r) => !r.ivHasAnyData);
    const someIvHasData = okResults.some((r) => r.ivHasAnyData);
    const someIvEmpty = okResults.some((r) => !r.ivHasAnyData);

    if (!anyIvFieldFoundAtAll) {
      rootCauseStatus = "REQUEST_SCHEMA_BUG";
      rootCauseNote = "No key matching iv / implied_volatility (case-insensitive, any nesting depth) appeared anywhere in any of the 4 raw responses — not even as an empty array. This suggests requiredData's 'implied_volatility' name, or the request schema itself, does not match what Dhan's rollingoption endpoint expects.";
      safeLocalFix = "Try alternate requiredData field-name spellings for IV (e.g. 'iv') and re-run this same diagnostic; if a differently-named key then appears (even empty), this reclassifies away from REQUEST_SCHEMA_BUG.";
    } else if (someIvHasData && someIvEmpty) {
      rootCauseStatus = "CONTRACT_OR_EXPIRY_SPECIFIC_BEHAVIOR";
      rootCauseNote = "The IV field exists in the schema and has real data for at least one test combination, but is empty for at least one other (CALL vs PUT and/or current vs next expiry) — see per-test ivHasAnyData below for which combination(s) are affected.";
      safeLocalFix = "None needed in the audit code itself — downstream consumers must treat IV availability as expiry/side-dependent, not assume it is always present once the field exists.";
    } else if (allIvEmpty) {
      rootCauseStatus = "PROVIDER_RESPONSE_ANOMALY";
      rootCauseNote = "The IV field is present in the schema (as an array key) across all 4 tests, but its array is empty ([]) in every single test — CALL and PUT, current and next expiry alike — while OI/spot/timestamp arrays for the same requests are populated. This is consistent with Dhan's rollingoption endpoint not actually back-filling historical IV for this instrument, not a local parsing defect.";
      safeLocalFix = null;
    } else {
      rootCauseStatus = "PASS_IV_PRESENT";
      rootCauseNote = "IV array has real (non-empty) data in all 4 tested combinations.";
      safeLocalFix = null;
    }
  }

  return c.json({
    architectureRole: "V3D_BUG02_HISTORICAL_OPTION_IV_EMPTY",
    generatedAt, symbol: symbolParam, bugId: "V3D_BUG_02",
    requestedRange: { fromDate: fmt(fromDate), toDate: fmt(toDate) },
    testResults,
    rootCauseStatus,
    rootCauseNote,
    safeLocalFix,
    bug02Closed: rootCauseStatus !== "ERROR",
    hardRulesHonoured: {
      noHistoricalIvCalculated: true,
      noZeroSubstitutedForMissingIv: true,
      noFiveYearFetch: true,
      v2ProductionUntouched: true,
    },
    limitations: [
      "10-day probe window only, ATM strike only, WEEK expiryFlag only — does not test every strike/expiry-flag combination.",
      "requiredData field name 'implied_volatility' was our best-effort guess at Dhan's schema; see rootCauseStatus if that guess itself is wrong.",
    ],
    readOnlyMode: true, orderAccessUsed: false, tokenExposed: false,
  }, 200);
});


// ============================================================================
// V3D_MASTER_AUDIT_HARNESS — read-only master audit orchestrator
// Source: v3_master_audit_harness.ts (provided by Bhagi Sir). Embedded here
// rather than as a separate import file, to match this codebase's existing
// single-file Railway/tsx convention and avoid new build/import-resolution
// risk. Harness logic itself is unchanged from the provided file; only
// names are prefixed v3* to avoid collisions with existing code.
//
// Historical Store Brain (Google Drive L0/L1/L2 write-read proof) is
// intentionally NOT wired in this pass -- the harness marks it optional,
// and wiring any new write path against the Drive connector needs its own
// explicit confirmation, even for a read-back diagnostic.
// ============================================================================

type V3AuditStatus = "PASS" | "PARTIAL" | "FAIL" | "UNKNOWN" | "BLOCKED_BY_DATA";
type V3AuditSymbol = "NIFTY" | "BANKNIFTY" | "FINNIFTY" | "MIDCPNIFTY" | "SENSEX";

interface V3AuditCheck {
  id: string;
  name: string;
  status: V3AuditStatus;
  evidence?: Record<string, unknown>;
  reason?: string;
  dependsOn?: string[];
}

interface V3SymbolAuditReport {
  symbol: V3AuditSymbol;
  checks: V3AuditCheck[];
  overallStatus: V3AuditStatus;
}

interface V3MasterAuditReport {
  architectureRole: "V3D_MASTER_AUDIT_HARNESS";
  generatedAt: string;
  readOnlyMode: true;
  tokenExposed: false;
  orderAccessUsed: false;
  symbols: V3SymbolAuditReport[];
  summary: { pass: number; partial: number; fail: number; unknown: number; blockedByData: number };
  blockers: Array<{ symbol: V3AuditSymbol; checkId: string; name: string; reason?: string }>;
}

interface V3AuditAdapter {
  resolveContracts(symbol: V3AuditSymbol): Promise<{ ok: boolean; spotSecurityId?: string | number | null; currentFuture?: unknown; nextFuture?: unknown; farFuture?: unknown; currentOptionExpiries?: unknown[]; errors?: string[] }>;
  fetchFuturesHistory(symbol: V3AuditSymbol): Promise<{ ok: boolean; identityOk: boolean; openCount?: number; highCount?: number; lowCount?: number; closeCount?: number; volumeCount?: number; oiCount?: number; timestampCount?: number; rawHasOi?: boolean; requestHadOiTrue?: boolean; errors?: string[] }>;
  fetchExpiredOptionProbe(symbol: V3AuditSymbol): Promise<{ ok: boolean; callOk?: boolean; putOk?: boolean; ohlcCount?: number; volumeCount?: number; oiCount?: number; ivCount?: number; strikeCount?: number; spotCount?: number; timestampCount?: number; requestUsedOfficialIvField?: boolean; expiryCodeZeroAccepted?: boolean | null; errors?: string[] }>;
  fetchLiveOptionChainProbe(symbol: V3AuditSymbol): Promise<{ ok: boolean; strikeCount?: number; hasOi?: boolean; hasVolume?: boolean; hasIv?: boolean; hasGreeks?: boolean; hasBidAsk?: boolean; providerTimestampAvailable?: boolean; zeroGreekAnomalyCount?: number; priceBoundAnomalyCount?: number; errors?: string[] }>;
  verifyHistoricalStoreBrain?(): Promise<{ ok: boolean; l0ManifestWriteRead?: boolean; l1RawImmutableWriteRead?: boolean; l2IdentityWriteRead?: boolean; checksumMatch?: boolean; errors?: string[] }>;
}

function v3StatusFromCounts(ok: boolean, counts: Array<number | undefined>): V3AuditStatus {
  if (!ok) return "FAIL";
  const present = counts.filter((v) => typeof v === "number" && v > 0).length;
  if (present === counts.length) return "PASS";
  if (present > 0) return "PARTIAL";
  return "FAIL";
}

function v3AggregateStatus(checks: V3AuditCheck[]): V3AuditStatus {
  if (checks.some((c) => c.status === "FAIL")) return "FAIL";
  if (checks.some((c) => c.status === "PARTIAL")) return "PARTIAL";
  if (checks.some((c) => c.status === "UNKNOWN")) return "UNKNOWN";
  if (checks.every((c) => c.status === "BLOCKED_BY_DATA")) return "BLOCKED_BY_DATA";
  if (checks.some((c) => c.status === "BLOCKED_BY_DATA")) return "PARTIAL";
  return "PASS";
}

function v3BlockDependents(checks: V3AuditCheck[]): V3AuditCheck[] {
  const map = new Map(checks.map((c) => [c.id, c.status]));
  return checks.map((c) => {
    const bad = c.dependsOn?.find((id) => ["FAIL", "UNKNOWN", "BLOCKED_BY_DATA"].includes(String(map.get(id))));
    return bad ? { ...c, status: "BLOCKED_BY_DATA" as V3AuditStatus, reason: `Blocked because prerequisite ${bad} is not usable.` } : c;
  });
}

async function v3AuditOne(symbol: V3AuditSymbol, adapter: V3AuditAdapter): Promise<V3SymbolAuditReport> {
  const checks: V3AuditCheck[] = [];

  try {
    const r = await adapter.resolveContracts(symbol);
    checks.push({ id: "A_IDENTITY", name: "Contract identity", status: r.ok ? "PASS" : "FAIL", evidence: { spotSecurityId: r.spotSecurityId ?? null, currentFuture: r.currentFuture ?? null, nextFuture: r.nextFuture ?? null, farFuture: r.farFuture ?? null, expiryCount: r.currentOptionExpiries?.length ?? 0 }, reason: r.errors?.join("; ") });
  } catch (e) {
    checks.push({ id: "A_IDENTITY", name: "Contract identity", status: "FAIL", reason: e instanceof Error ? e.message : String(e) });
  }

  try {
    const r = await adapter.fetchFuturesHistory(symbol);
    checks.push({ id: "B_FUTURES_HISTORY", name: "Futures OHLC/volume/timestamp", status: v3StatusFromCounts(r.ok && r.identityOk, [r.openCount, r.highCount, r.lowCount, r.closeCount, r.volumeCount, r.timestampCount]), dependsOn: ["A_IDENTITY"], evidence: r as unknown as Record<string, unknown>, reason: r.errors?.join("; ") });
    let s: V3AuditStatus = "UNKNOWN";
    if (r.requestHadOiTrue === false) s = "FAIL";
    else if (r.rawHasOi === true && (r.oiCount ?? 0) > 0) s = "PASS";
    else if (r.requestHadOiTrue === true && r.rawHasOi === false) s = "PARTIAL";
    checks.push({ id: "B_FUTURES_OI", name: "Historical futures OI", status: s, dependsOn: ["A_IDENTITY"], evidence: { requestHadOiTrue: r.requestHadOiTrue ?? null, rawHasOi: r.rawHasOi ?? null, oiCount: r.oiCount ?? 0 } });
  } catch (e) {
    checks.push({ id: "B_FUTURES_HISTORY", name: "Futures OHLC/volume/timestamp", status: "FAIL", dependsOn: ["A_IDENTITY"], reason: e instanceof Error ? e.message : String(e) });
    checks.push({ id: "B_FUTURES_OI", name: "Historical futures OI", status: "UNKNOWN", dependsOn: ["A_IDENTITY"], reason: "Futures probe failed before OI could be proven." });
  }

  try {
    const r = await adapter.fetchExpiredOptionProbe(symbol);
    checks.push({ id: "C_OPTION_HISTORY", name: "Expired option OHLC/OI/volume/spot/timestamp", status: v3StatusFromCounts(r.ok, [r.ohlcCount, r.volumeCount, r.oiCount, r.spotCount, r.timestampCount]), dependsOn: ["A_IDENTITY"], evidence: r as unknown as Record<string, unknown>, reason: r.errors?.join("; ") });
    checks.push({ id: "C_HISTORICAL_IV", name: "Historical option IV", status: r.requestUsedOfficialIvField !== true ? "FAIL" : (r.ivCount ?? 0) > 0 ? "PASS" : "PARTIAL", dependsOn: ["C_OPTION_HISTORY"], evidence: { requestUsedOfficialIvField: r.requestUsedOfficialIvField ?? null, ivCount: r.ivCount ?? 0 } });
    checks.push({ id: "C_HISTORICAL_STRIKE", name: "Historical option strike identity", status: (r.strikeCount ?? 0) > 0 ? "PASS" : "PARTIAL", dependsOn: ["C_OPTION_HISTORY"], evidence: { strikeCount: r.strikeCount ?? 0 } });
    checks.push({ id: "C_CALL_PUT_COVERAGE", name: "CALL and PUT historical coverage", status: r.callOk && r.putOk ? "PASS" : "PARTIAL", dependsOn: ["C_OPTION_HISTORY"], evidence: { callOk: !!r.callOk, putOk: !!r.putOk } });
    checks.push({ id: "C_EXPIRYCODE_ZERO", name: "Current/near expiryCode=0 behavior", status: r.expiryCodeZeroAccepted === true ? "PASS" : r.expiryCodeZeroAccepted === false ? "PARTIAL" : "UNKNOWN", dependsOn: ["C_OPTION_HISTORY"], evidence: { expiryCodeZeroAccepted: r.expiryCodeZeroAccepted ?? null } });
  } catch (e) {
    checks.push({ id: "C_OPTION_HISTORY", name: "Expired option history", status: "FAIL", dependsOn: ["A_IDENTITY"], reason: e instanceof Error ? e.message : String(e) });
  }

  try {
    const r = await adapter.fetchLiveOptionChainProbe(symbol);
    const live = r.ok && r.hasOi && r.hasVolume && r.hasIv && r.hasBidAsk && (r.strikeCount ?? 0) > 0 ? "PASS" : r.ok ? "PARTIAL" : "FAIL";
    checks.push({ id: "D_LIVE_CHAIN", name: "Live option-chain raw fields", status: live, dependsOn: ["A_IDENTITY"], evidence: r as unknown as Record<string, unknown>, reason: r.errors?.join("; ") });
    checks.push({ id: "D_ZERO_GREEKS", name: "Live zero-IV/zero-Greeks anomaly gate", status: (r.zeroGreekAnomalyCount ?? 0) > 0 ? "PARTIAL" : "PASS", dependsOn: ["D_LIVE_CHAIN"], evidence: { anomalyCount: r.zeroGreekAnomalyCount ?? 0 } });
    checks.push({ id: "D_PRICE_BOUND", name: "Price-bound anomaly gate", status: (r.priceBoundAnomalyCount ?? 0) > 0 ? "PARTIAL" : "PASS", dependsOn: ["D_LIVE_CHAIN"], evidence: { anomalyCount: r.priceBoundAnomalyCount ?? 0 } });
    checks.push({ id: "D_PROVIDER_TIMESTAMP", name: "Exchange/provider timestamp availability", status: r.providerTimestampAvailable ? "PASS" : "PARTIAL", dependsOn: ["D_LIVE_CHAIN"], evidence: { providerTimestampAvailable: !!r.providerTimestampAvailable } });
  } catch (e) {
    checks.push({ id: "D_LIVE_CHAIN", name: "Live option-chain raw fields", status: "FAIL", dependsOn: ["A_IDENTITY"], reason: e instanceof Error ? e.message : String(e) });
  }

  const resolved = v3BlockDependents(checks);
  return { symbol, checks: resolved, overallStatus: v3AggregateStatus(resolved) };
}

async function v3RunMasterAudit(adapter: V3AuditAdapter, symbols: V3AuditSymbol[]): Promise<V3MasterAuditReport> {
  const reports: V3SymbolAuditReport[] = [];
  for (const symbol of symbols) reports.push(await v3AuditOne(symbol, adapter));

  if (adapter.verifyHistoricalStoreBrain) {
    try {
      const store = await adapter.verifyHistoricalStoreBrain();
      const s: V3AuditStatus = store.ok && store.l0ManifestWriteRead && store.l1RawImmutableWriteRead && store.l2IdentityWriteRead && store.checksumMatch ? "PASS" : store.ok ? "PARTIAL" : "FAIL";
      for (const r of reports) {
        r.checks.push({ id: "E_STORE_BRAIN", name: "Historical Store Brain L0/L1/L2 write-read proof", status: s, evidence: store as unknown as Record<string, unknown>, reason: store.errors?.join("; ") });
        r.overallStatus = v3AggregateStatus(r.checks);
      }
    } catch (e) {
      for (const r of reports) {
        r.checks.push({ id: "E_STORE_BRAIN", name: "Historical Store Brain L0/L1/L2 write-read proof", status: "FAIL", reason: e instanceof Error ? e.message : String(e) });
        r.overallStatus = v3AggregateStatus(r.checks);
      }
    }
  }

  const all = reports.flatMap((r) => r.checks);
  const cnt = (s: V3AuditStatus) => all.filter((c) => c.status === s).length;
  return {
    architectureRole: "V3D_MASTER_AUDIT_HARNESS",
    generatedAt: new Date().toISOString(),
    readOnlyMode: true,
    tokenExposed: false,
    orderAccessUsed: false,
    symbols: reports,
    summary: { pass: cnt("PASS"), partial: cnt("PARTIAL"), fail: cnt("FAIL"), unknown: cnt("UNKNOWN"), blockedByData: cnt("BLOCKED_BY_DATA") },
    blockers: reports.flatMap((r) => r.checks.filter((c) => c.status === "FAIL" || c.status === "UNKNOWN").map((c) => ({ symbol: r.symbol, checkId: c.id, name: c.name, reason: c.reason }))),
  };
}

// ----------------------------------------------------------------------------
// V3AuditAdapter implementation. Reuses existing D1-D6 Dhan credentials and
// the audit endpoints already LIVE_VERIFIED earlier today via internal
// self-fetch calls (no duplicated credentials, no new Dhan call sites for
// logic already proven correct today). Fresh logic is written only for the
// expired-options probe, per Bug 02A's official 'iv' field-name requirement.
// ----------------------------------------------------------------------------

function v3SelfBaseUrl(): string {
  const domain = process.env.RAILWAY_PUBLIC_DOMAIN?.trim();
  return domain ? `https://${domain}` : "http://localhost:8080";
}

const v3AuditKey = () => process.env.DHAN_AUDIT_KEY?.trim() || "";

async function v3SelfFetchJson(path: string): Promise<{ ok: boolean; status: number; json: any }> {
  const url = `${v3SelfBaseUrl()}${path}`;
  const res = await fetch(url);
  const text = await res.text();
  let json: any = null;
  try { json = text ? JSON.parse(text) : null; } catch { json = null; }
  return { ok: res.ok, status: res.status, json };
}

const v3RealDhanAdapter: V3AuditAdapter = {
  async resolveContracts(symbol) {
    const key = v3AuditKey();
    if (!key) return { ok: false, errors: ["DHAN_AUDIT_KEY not set in Railway variables"] };

    const [liveRes, scan] = await Promise.all([
      v3SelfFetchJson(`/api/dhan/live?symbol=${symbol}`),
      dhanScanScripMaster(symbol, 8),
    ]);

    const errors: string[] = [];
    if (!liveRes.ok) errors.push(`live probe HTTP ${liveRes.status}`);
    if (!scan.fetchOk) errors.push("scrip master scan failed");

    const sortedFut = [...scan.futRows].sort((a, b) => {
      const da = new Date(a["SEM_EXPIRY_DATE"] || "").getTime();
      const db = new Date(b["SEM_EXPIRY_DATE"] || "").getTime();
      return (isNaN(da) ? Infinity : da) - (isNaN(db) ? Infinity : db);
    });

    return {
      ok: liveRes.ok && scan.fetchOk && sortedFut.length > 0,
      spotSecurityId: liveRes.json?.underlyingScrip ?? null,
      currentFuture: sortedFut[0] ? { securityId: sortedFut[0]["SEM_SMST_SECURITY_ID"], tradingSymbol: sortedFut[0]["SEM_TRADING_SYMBOL"], expiry: sortedFut[0]["SEM_EXPIRY_DATE"] } : null,
      nextFuture: sortedFut[1] ? { securityId: sortedFut[1]["SEM_SMST_SECURITY_ID"], tradingSymbol: sortedFut[1]["SEM_TRADING_SYMBOL"], expiry: sortedFut[1]["SEM_EXPIRY_DATE"] } : null,
      farFuture: sortedFut[2] ? { securityId: sortedFut[2]["SEM_SMST_SECURITY_ID"], tradingSymbol: sortedFut[2]["SEM_TRADING_SYMBOL"], expiry: sortedFut[2]["SEM_EXPIRY_DATE"] } : null,
      currentOptionExpiries: Array.isArray(liveRes.json?.availableExpiries) ? liveRes.json.availableExpiries : [],
      errors: errors.length ? errors : undefined,
    };
  },

  async fetchFuturesHistory(symbol) {
    // PATCH (V3D_MASTER_AUDIT_PATCH_01): the daily endpoint
    // (/v2/charts/historical) started rejecting FUTIDX requests with
    // DH-905 regardless of expiryCode value (confirmed live 2026-08-12).
    // Bug 01B proved /v2/charts/intraday works reliably for the same
    // contract (374 minute rows, oi returned as "open_interest"). V3
    // futures research uses intraday going forward, per hard_rules
    // ("Do not use daily endpoint for minute V3 research").
    const mapping = (DHAN_UNDERLYING_MAP as Record<string, { underlyingScrip: number; underlyingSeg: string }>)[symbol];
    const accessToken = (await getValidDhanAccessToken()) || "";
    const clientId = process.env.DHAN_CLIENT_ID?.trim() || "";
    if (!accessToken || !clientId) return { ok: false, identityOk: false, errors: ["DHAN_ACCESS_TOKEN/DHAN_CLIENT_ID missing"] };

    const scan = await dhanScanScripMaster(symbol, 8);
    if (!scan.fetchOk || !scan.headerCols || scan.futRows.length === 0) {
      return { ok: false, identityOk: false, errors: ["Could not resolve a FUTIDX securityId from the scrip master scan."] };
    }
    const sortedFut = [...scan.futRows].sort((a, b) => {
      const da = new Date(a["SEM_EXPIRY_DATE"] || "").getTime();
      const db = new Date(b["SEM_EXPIRY_DATE"] || "").getTime();
      return (isNaN(da) ? Infinity : da) - (isNaN(db) ? Infinity : db);
    });
    const nearest = sortedFut[0];
    const securityId = nearest["SEM_SMST_SECURITY_ID"];
    if (!securityId) return { ok: false, identityOk: false, errors: ["Matched FUTIDX row had no SEM_SMST_SECURITY_ID"] };

    // Most recent already-completed calendar day (yesterday), full
    // market-hours window -- a fixed hardcoded date would go stale.
    // Weekend/holiday gaps are a known limitation here, same as
    // elsewhere in this codebase's small-window probes.
    const yesterday = new Date(Date.now() - 24 * 60 * 60 * 1000);
    const y = yesterday.toISOString().slice(0, 10);
    const futuresSegment = symbol === "SENSEX" ? "BSE_FNO" : "NSE_FNO"; // BUG FIX 2026-08-12: was hardcoded NSE_FNO, causing SENSEX futures history to silently return empty arrays (caught by V3D_CROSS_INDEX_MASTER_AUDIT_V2)
    const requestBodyObj = {
      securityId: String(securityId),
      exchangeSegment: futuresSegment,
      instrument: "FUTIDX",
      interval: "1",
      oi: true,
      fromDate: `${y} 09:15:00`,
      toDate: `${y} 15:30:00`,
    };

    try {
      const res = await dhanRateLimitedFetch("https://api.dhan.co/v2/charts/intraday", {
        method: "POST",
        headers: { "Content-Type": "application/json", Accept: "application/json", "access-token": accessToken, "client-id": clientId },
        body: JSON.stringify(requestBodyObj),
      });
      const raw = await res.text();
      let payload: any = null;
      try { payload = raw ? JSON.parse(raw) : null; } catch { payload = null; }

      if (!res.ok || !payload || typeof payload !== "object") {
        return { ok: false, identityOk: true, errors: [payload?.errorMessage || `intraday futures HTTP ${res.status}`] };
      }

      const arrLen = (v: any) => (Array.isArray(v) ? v.length : 0);
      return {
        ok: true,
        identityOk: true,
        openCount: arrLen(payload.open),
        highCount: arrLen(payload.high),
        lowCount: arrLen(payload.low),
        closeCount: arrLen(payload.close),
        volumeCount: arrLen(payload.volume),
        // Raw provider field name preserved for provenance; the
        // normalized-layer mapping open_interest -> oi (source:
        // DHAN_NATIVE) happens only here in the adapter's return shape,
        // never in raw storage.
        oiCount: arrLen(payload.open_interest),
        timestampCount: arrLen(payload.timestamp),
        rawHasOi: arrLen(payload.open_interest) > 0,
        requestHadOiTrue: true,
        errors: undefined,
      };
    } catch (e) {
      return { ok: false, identityOk: true, errors: [e instanceof Error ? e.message : "intraday futures request failed"] };
    }
  },

  async fetchExpiredOptionProbe(symbol) {
    const mapping = (DHAN_UNDERLYING_MAP as Record<string, { underlyingScrip: number; underlyingSeg: string }>)[symbol];
    const accessToken = (await getValidDhanAccessToken()) || "";
    const clientId = process.env.DHAN_CLIENT_ID?.trim() || "";
    if (!mapping) return { ok: false, errors: ["Symbol not in DHAN_UNDERLYING_MAP"] };
    if (!accessToken || !clientId) return { ok: false, errors: ["DHAN_ACCESS_TOKEN/DHAN_CLIENT_ID missing"] };

    const optionsSegment = symbol === "SENSEX" ? "BSE_FNO" : "NSE_FNO";
    const toDate = new Date();
    const fromDate = new Date(toDate.getTime() - 10 * 24 * 60 * 60 * 1000);
    const fmt = (d: Date) => d.toISOString().slice(0, 10);

    async function probe(optionType: "CALL" | "PUT", expiryCode: number) {
      const body = {
        exchangeSegment: optionsSegment,
        interval: "1",
        securityId: mapping.underlyingScrip,
        instrument: "OPTIDX",
        expiryFlag: "WEEK",
        expiryCode,
        strike: "ATM",
        drvOptionType: optionType,
        requiredData: ["open", "high", "low", "close", "iv", "volume", "strike", "oi", "spot"],
        fromDate: fmt(fromDate),
        toDate: fmt(toDate),
      };
      const res = await dhanRateLimitedFetch("https://api.dhan.co/v2/charts/rollingoption", {
        method: "POST",
        headers: { "Content-Type": "application/json", Accept: "application/json", "access-token": accessToken, "client-id": clientId },
        body: JSON.stringify(body),
      });
      const raw = await res.text();
      let payload: any = null;
      try { payload = raw ? JSON.parse(raw) : null; } catch { payload = null; }
      return { ok: res.ok, status: res.status, payload };
    }

    // Record-only check: does Dhan accept expiryCode:0 at all? (not used
    // for the real data pull below, since prior live probes confirmed 0
    // is rejected with DH-905).
    let expiryCodeZeroAccepted: boolean | null = null;
    try {
      const zeroProbe = await probe("CALL", 0);
      expiryCodeZeroAccepted = zeroProbe.ok;
    } catch {
      expiryCodeZeroAccepted = null;
    }

    const errors: string[] = [];
    let callResult: any = null;
    let putResult: any = null;
    try {
      const r = await probe("CALL", 1);
      if (r.ok && r.payload) callResult = r.payload; else errors.push(`CALL probe HTTP ${r.status}`);
    } catch (e) { errors.push(e instanceof Error ? e.message : "CALL probe failed"); }
    try {
      const r = await probe("PUT", 1);
      if (r.ok && r.payload) putResult = r.payload; else errors.push(`PUT probe HTTP ${r.status}`);
    } catch (e) { errors.push(e instanceof Error ? e.message : "PUT probe failed"); }

    function leg(payload: any): any {
      return payload?.data?.ce ?? payload?.data?.pe ?? null;
    }
    const callLeg = leg(callResult);
    const putLeg = leg(putResult);
    const arrLen = (v: any) => (Array.isArray(v) ? v.length : 0);

    return {
      ok: !!(callLeg || putLeg),
      callOk: !!callLeg,
      putOk: !!putLeg,
      ohlcCount: arrLen(callLeg?.open ?? putLeg?.open),
      volumeCount: arrLen(callLeg?.volume ?? putLeg?.volume),
      oiCount: arrLen(callLeg?.oi ?? putLeg?.oi),
      ivCount: Math.max(arrLen(callLeg?.iv), arrLen(putLeg?.iv)),
      strikeCount: Math.max(arrLen(callLeg?.strike), arrLen(putLeg?.strike)),
      spotCount: arrLen(callLeg?.spot ?? putLeg?.spot),
      timestampCount: arrLen(callLeg?.timestamp ?? putLeg?.timestamp),
      requestUsedOfficialIvField: true,
      expiryCodeZeroAccepted,
      errors: errors.length ? errors : undefined,
    };
  },

  async fetchLiveOptionChainProbe(symbol) {
    const { ok, status, json } = await v3SelfFetchJson(`/api/dhan/live?symbol=${symbol}`);
    if (!ok || !json || json.status !== "PASS") return { ok: false, errors: [`live probe HTTP ${status}`] };

    const strikes: any[] = Array.isArray(json.strikes) ? json.strikes : [];
    let zeroGreekAnomalyCount = 0;
    let priceBoundAnomalyCount = 0;
    let hasOi = false, hasVolume = false, hasIv = false, hasGreeks = false, hasBidAsk = false;

    for (const s of strikes) {
      for (const legKey of ["ce", "pe"] as const) {
        const leg = s[legKey];
        if (!leg) continue;
        if (typeof leg.oi === "number") hasOi = true;
        if (typeof leg.volume === "number") hasVolume = true;
        if (typeof leg.iv === "number") hasIv = true;
        if (typeof leg.delta === "number") hasGreeks = true;
        if (typeof leg.bid === "number" && typeof leg.ask === "number") hasBidAsk = true;
        if (leg.iv === 0 && leg.delta === 0 && leg.gamma === 0 && leg.theta === 0 && leg.vega === 0) zeroGreekAnomalyCount++;
        if (typeof leg.lastPrice === "number" && (leg.lastPrice < 0 || leg.lastPrice > (json.spot ?? Infinity) * 2)) priceBoundAnomalyCount++;
      }
    }

    return {
      ok: true,
      strikeCount: strikes.length,
      hasOi, hasVolume, hasIv, hasGreeks, hasBidAsk,
      providerTimestampAvailable: json.providerTimestamp !== "UNAVAILABLE_FROM_PROVIDER",
      zeroGreekAnomalyCount,
      priceBoundAnomalyCount,
    };
  },

  // verifyHistoricalStoreBrain intentionally omitted -- see banner comment above.
};

app.get("/v3/audit/master", async (c) => {
  const auditKey = process.env.DHAN_AUDIT_KEY?.trim() || "";
  const providedKey = c.req.query("key")?.trim() || "";
  if (!auditKey || providedKey !== auditKey) {
    return c.json({ status: "ERROR", error: "Missing or invalid audit key." }, 403);
  }

  const allParam = c.req.query("all")?.trim() === "true";
  const symbols: V3AuditSymbol[] = allParam
    ? ["NIFTY", "BANKNIFTY", "FINNIFTY", "MIDCPNIFTY", "SENSEX"]
    : ["NIFTY"];

  try {
    const report = await v3RunMasterAudit(v3RealDhanAdapter, symbols);
    return c.json(report, 200);
  } catch (err) {
    return c.json({
      architectureRole: "V3D_MASTER_AUDIT_HARNESS",
      generatedAt: new Date().toISOString(),
      status: "ERROR",
      error: err instanceof Error ? err.message : "Unknown master audit failure",
      readOnlyMode: true, tokenExposed: false, orderAccessUsed: false,
    }, 500);
  }
});


// ============================================================================
// V3D_BUG_01B — INTRADAY_FUTURES_HISTORY_AND_OI_PROOF (READ-ONLY, DIAGNOSTIC)
//
// Probes Dhan's official /v2/charts/intraday endpoint for one already-
// completed trading day of NIFTY futures minute data (OHLC+volume+OI),
// per the exact request spec Bhagi Sir provided. securityId is resolved
// dynamically via the scrip-master scan (never hardcoded/fabricated),
// then cross-checked against the expected contract from the spec.
// ============================================================================

app.get("/api/audit/dhan-bug01b-intraday-futures-check", async (c) => {
  const auditKey = process.env.DHAN_AUDIT_KEY?.trim() || "";
  const providedKey = c.req.query("key")?.trim() || "";
  if (!auditKey || providedKey !== auditKey) {
    return c.json({ status: "ERROR", error: "Missing or invalid audit key." }, 403);
  }

  const symbolParam = (c.req.query("symbol") || "NIFTY").toUpperCase();
  const generatedAt = new Date().toISOString();

  try {
    const scan = await dhanScanScripMaster(symbolParam, 8);
    if (!scan.fetchOk || !scan.headerCols || scan.futRows.length === 0) {
      return c.json({
        architectureRole: "V3D_BUG01B_INTRADAY_FUTURES_HISTORY_AND_OI_PROOF",
        generatedAt, symbol: symbolParam, bugId: "V3D_BUG_01B",
        status: "ERROR", error: "Could not resolve a FUTIDX securityId from the scrip master scan.",
      }, 200);
    }

    const sorted = [...scan.futRows].sort((a, b) => {
      const da = new Date(a["SEM_EXPIRY_DATE"] || "").getTime();
      const db = new Date(b["SEM_EXPIRY_DATE"] || "").getTime();
      return (isNaN(da) ? Infinity : da) - (isNaN(db) ? Infinity : db);
    });
    const nearest = sorted[0];
    const securityId = nearest["SEM_SMST_SECURITY_ID"];
    const tradingSymbol = nearest["SEM_TRADING_SYMBOL"];
    const expiryDate = nearest["SEM_EXPIRY_DATE"];

    const accessToken = (await getValidDhanAccessToken()) || "";
    const clientId = process.env.DHAN_CLIENT_ID?.trim() || "";
    if (!accessToken || !clientId) {
      return c.json({
        architectureRole: "V3D_BUG01B_INTRADAY_FUTURES_HISTORY_AND_OI_PROOF",
        generatedAt, symbol: symbolParam, bugId: "V3D_BUG_01B",
        status: "ERROR", error: "DHAN_ACCESS_TOKEN or DHAN_CLIENT_ID missing in Railway variables",
      }, 503);
    }

    // Exact request per Bhagi Sir's spec — one already-completed trading
    // day, minute interval, oi:true. Segment kept symbol-aware for
    // consistency (SENSEX trades on BSE_FNO, never NSE_FNO).
    const requestBodyObj = {
      securityId: String(securityId),
      exchangeSegment: symbolParam === "SENSEX" ? "BSE_FNO" : "NSE_FNO",
      instrument: "FUTIDX",
      interval: "1",
      oi: true,
      fromDate: "2026-08-11 09:15:00",
      toDate: "2026-08-11 15:30:00",
    };
    const requestBodyStr = JSON.stringify(requestBodyObj);
    const oiFlagLiterallyInOutgoingBody = /"oi"\s*:\s*true/.test(requestBodyStr);
    const intervalLiterallyInOutgoingBody = /"interval"\s*:\s*"1"/.test(requestBodyStr);

    const res = await dhanRateLimitedFetch("https://api.dhan.co/v2/charts/intraday", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Accept: "application/json",
        "access-token": accessToken,
        "client-id": clientId,
      },
      body: requestBodyStr,
    });

    const httpStatus = res.status;
    const raw = await res.text();
    let payload: any = null;
    try { payload = raw ? JSON.parse(raw) : null; } catch { payload = null; }

    if (!res.ok || !payload || typeof payload !== "object") {
      return c.json({
        architectureRole: "V3D_BUG01B_INTRADAY_FUTURES_HISTORY_AND_OI_PROOF",
        generatedAt, symbol: symbolParam, bugId: "V3D_BUG_01B",
        contractIdentity: { securityId, tradingSymbol, expiryDate, expectedFromSpec: "58072 / NIFTY-Aug2026-FUT", matchesSpec: String(securityId) === "58072" },
        sanitizedRequestBody: requestBodyObj,
        oiFlagLiterallyInOutgoingBody,
        intervalLiterallyInOutgoingBody,
        httpStatus,
        rootCauseStatus: "ERROR",
        providerError: payload && typeof payload === "object" ? {
          errorType: payload.errorType ?? null,
          errorCode: payload.errorCode ?? null,
          errorMessage: payload.errorMessage ?? null,
        } : { errorType: "NON_JSON_OR_EMPTY", errorCode: null, errorMessage: `HTTP ${httpStatus}` },
        rawSnippet: raw.slice(0, 500),
        bug01bClosed: false,
        readOnlyMode: true, orderAccessUsed: false, tokenExposed: false,
      }, 200);
    }

    const rawTopLevelKeys = Object.keys(payload);
    const arrLen = (v: any) => (Array.isArray(v) ? v.length : null);
    const counts: Record<string, number | null> = {};
    for (const k of rawTopLevelKeys) counts[k] = arrLen(payload[k]);

    // OI-shaped key search (case-insensitive, handles open_interest naming
    // confirmed for the daily endpoint's futures response earlier today).
    const oiKeyPattern = /(\boi\b|open[_]?interest)/i;
    const oiLikeKeys = rawTopLevelKeys.filter((k) => oiKeyPattern.test(k));
    const oiArrayLength = oiLikeKeys.length > 0 ? (counts[oiLikeKeys[0]] ?? 0) : null;
    const oiHasData = typeof oiArrayLength === "number" && oiArrayLength > 0;

    const ohlcvFields = ["open", "high", "low", "close", "volume", "timestamp"];
    const ohlcvNonEmpty = ohlcvFields.every((f) => (counts[f] ?? 0) > 0);

    let rootCauseStatus: "PASS" | "PARSER_BUG" | "PROVIDER_OI_ANOMALY" | "PARTIAL" | "ERROR";
    let rootCauseNote: string;
    if (!ohlcvNonEmpty) {
      rootCauseStatus = "PARTIAL";
      rootCauseNote = "OHLC/volume/timestamp arrays were not all non-empty -- cannot fully PASS the base data requirement.";
    } else if (oiLikeKeys.length === 0) {
      rootCauseStatus = "PROVIDER_OI_ANOMALY";
      rootCauseNote = "oi:true was sent and OHLC/volume/timestamp are populated, but no key matching oi/open_interest (case-insensitive) appeared anywhere in the raw top-level response.";
    } else if (!oiHasData) {
      rootCauseStatus = "PROVIDER_OI_ANOMALY";
      rootCauseNote = `An OI-shaped key (${oiLikeKeys.join(", ")}) exists in the schema but its array is empty, while OHLC/volume/timestamp are populated.`;
    } else {
      rootCauseStatus = "PASS";
      rootCauseNote = `OHLC/volume/timestamp all non-empty, and OI-shaped key (${oiLikeKeys.join(", ")}) has ${oiArrayLength} data points.`;
    }

    return c.json({
      architectureRole: "V3D_BUG01B_INTRADAY_FUTURES_HISTORY_AND_OI_PROOF",
      generatedAt, symbol: symbolParam, bugId: "V3D_BUG_01B",
      contractIdentity: { securityId, tradingSymbol, expiryDate, expectedFromSpec: "58072 / NIFTY-Aug2026-FUT", matchesSpec: String(securityId) === "58072" },
      sanitizedRequestBody: requestBodyObj,
      oiFlagLiterallyInOutgoingBody,
      intervalLiterallyInOutgoingBody,
      httpStatus,
      rawResponseKeys: rawTopLevelKeys,
      rawResponseArrayLengths: counts,
      ohlcvAllNonEmpty: ohlcvNonEmpty,
      oiLikeKeysFound: oiLikeKeys,
      oiArrayLength,
      oiHasData,
      rootCauseStatus,
      rootCauseNote,
      bug01bClosed: true,
      limitations: [
        "Single trading day (2026-08-11 09:15-15:30 IST) only, per stop_condition.",
        "No OI values were derived or fabricated -- oiArrayLength reflects exactly what Dhan returned.",
      ],
      readOnlyMode: true, orderAccessUsed: false, tokenExposed: false,
    }, 200);
  } catch (err) {
    return c.json({
      architectureRole: "V3D_BUG01B_INTRADAY_FUTURES_HISTORY_AND_OI_PROOF",
      generatedAt, symbol: symbolParam, bugId: "V3D_BUG_01B",
      status: "ERROR",
      error: err instanceof Error ? err.message : "Unknown intraday futures request failure",
      readOnlyMode: true, tokenExposed: false,
    }, 500);
  }
});


